# ---------------------------------------------------------------------------
# Talking to the model providers.
#
# OpenAI and Mistral both speak the OpenAI chat format, so one function covers
# both. Gemini is called over plain HTTP rather than through the SDK, because
# the installed SDK cannot switch thinking off or report when an answer was
# cut short, and both of those matter here.
# ---------------------------------------------------------------------------

OPENAI_FORMAT_ENDPOINTS = {
    "openai": ("https://api.openai.com/v1/chat/completions", lambda: OPENAI_API_KEY),
    "mistral": ("https://api.mistral.ai/v1/chat/completions", lambda: MISTRAL_API_KEY),
    "deepseek": ("https://api.deepseek.com/chat/completions", lambda: os.environ.get("DEEPSEEK_API_KEY")),
}


_DEEPSEEK_DOWN_UNTIL = [0.0]


def _ask_openai_format(provider, model_id, system_prompt, turns, question, images, max_tokens, auto_continue=False):
    """Call OpenAI or Mistral and return the answer text."""
    url, get_key = OPENAI_FORMAT_ENDPOINTS[provider]
    key = get_key()
    if not key:
        raise HTTPException(status_code=503, detail=f"{TYPEMYWORDZ_AI_NAME} is not connected to that model right now.")

    if provider == "deepseek":
        # Pictures go to ChatGPT Luna. So does everything while DeepSeek is
        # unavailable (for example an empty balance), so clients see no error.
        if images or time.time() < _DEEPSEEK_DOWN_UNTIL[0]:
            return _ask_openai_format("openai", ASK_LUNA_MODEL, system_prompt, turns, question, images, max_tokens, auto_continue)
    content = []
    for img in images:
        content.append({
            "type": "image_url",
            "image_url": {"url": f"data:{img['media_type']};base64,{img['data']}"},
        })
    content.append({"type": "text", "text": question})

    messages = [{"role": "system", "content": system_prompt}]
    for turn in turns:
        messages.append({"role": turn["role"], "content": turn["content"]})
    messages.append({"role": "user", "content": content})

    chunks = []
    max_attempts = 12 if auto_continue else 1
    for attempt in range(max_attempts):
        payload = {"model": model_id, "messages": messages}
        if provider == "deepseek":
            # The retired v4 names are still accepted, but the current name is
            # deepseek-flash. Reasoning is switched off: its tokens are billed as
            # output and a chat answer does not need them.
            payload["model"] = "deepseek-flash"
            payload["thinking"] = {"type": "disabled"}
        budget = max(max_tokens, 16000 if auto_continue else 4000)
        if provider == "openai":
            # These models count reasoning tokens against the output budget, so
            # keep reasoning light for chat and give the answer room to finish.
            payload["max_completion_tokens"] = budget
            payload["reasoning_effort"] = "low"
        else:
            payload["max_tokens"] = budget

        r = requests.post(
            url,
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
            json=payload,
            timeout=300 if auto_continue else 180,
        )
        if r.status_code != 200:
            logger.error(f"{provider} returned {r.status_code}: {r.text[:400]}")
            if provider == "deepseek":
                _DEEPSEEK_DOWN_UNTIL[0] = time.time() + 300
                return _ask_openai_format("openai", ASK_LUNA_MODEL, system_prompt, turns, question, images, max_tokens, auto_continue)
            raise HTTPException(status_code=502, detail=f"{TYPEMYWORDZ_AI_NAME} could not reach that model. Please try again.")
        data = r.json()
        choice = (data.get("choices") or [{}])[0]
        text = ((choice.get("message") or {}).get("content") or "").strip()
        if text:
            chunks.append(text)
        if choice.get("finish_reason") == "length":
            if not auto_continue:
                if text:
                    return text + "\n\n[The answer was cut short because it reached its length limit.  Ask me to continue and I will pick up where I stopped.]"
                return text
            if not text:
                raise RuntimeError("The model reached its output limit without a continuation point.")
            if attempt + 1 >= max_attempts:
                raise RuntimeError("The model could not finish the response after automatic continuation.")
            messages = messages + [
                {"role": "assistant", "content": text},
                {"role": "user", "content": "Continue exactly where the previous response stopped. Do not repeat earlier output. Return only the remaining text, with no explanation or status notice."},
            ]
            continue
        break
    return "".join(chunks).strip()


def _ask_gemini(model_id, system_prompt, turns, question, images, max_tokens, thinking_level=None, auto_continue=False):
    """Call Gemini and, for transcription jobs, continue automatically at the provider cap."""
    if not GEMINI_API_KEY:
        raise HTTPException(status_code=503, detail=f"{TYPEMYWORDZ_AI_NAME} is not connected to that model right now.")

    convo = [system_prompt]
    for turn in turns:
        convo.append(("You: " if turn["role"] == "user" else "Assistant: ") + turn["content"])
    convo.append("You: " + question)

    parts = [{"text": "\n\n".join(convo)}]
    for img in images:
        parts.append({"inline_data": {"mime_type": img["media_type"], "data": img["data"]}})

    gen = {"maxOutputTokens": max(max_tokens, 16000 if auto_continue else GEMINI_MIN_OUTPUT_TOKENS)}
    if thinking_level and str(model_id).startswith("gemini-3."):
        gen["thinkingConfig"] = {"thinkingLevel": str(thinking_level)}
    elif model_id in GEMINI_THINKING_OFF:
        gen["thinkingConfig"] = {"thinkingBudget": 0}

    contents = [{"role": "user", "parts": parts}]
    visible_chunks = []
    max_attempts = 12 if auto_continue else 1
    length_notice = "\n\n[The answer was cut short because it reached its length limit. Ask me to continue and I will pick up where I stopped.]"
    for attempt in range(max_attempts):
        r = requests.post(
            f"https://generativelanguage.googleapis.com/v1beta/models/{model_id}:generateContent",
            params={"key": GEMINI_API_KEY},
            headers={"Content-Type": "application/json"},
            json={"contents": contents, "generationConfig": gen},
            timeout=180,
        )
        if r.status_code != 200:
            logger.error(f"gemini returned {r.status_code}: {r.text[:400]}")
            raise HTTPException(status_code=502, detail=f"{TYPEMYWORDZ_AI_NAME} could not reach that model. Please try again.")
        data = r.json()
        cand = (data.get("candidates") or [{}])[0]
        response_parts = ((cand.get("content") or {}).get("parts") or [])
        # Never send Gemini thought-summary parts to the transcript editor.
        answer_parts = [part for part in response_parts if not part.get("thought")]
        chunk = "".join(part.get("text", "") for part in answer_parts)
        if chunk.strip():
            visible_chunks.append(chunk)

        if cand.get("finishReason") == "MAX_TOKENS":
            if not auto_continue:
                if visible_chunks:
                    visible_chunks.append(length_notice)
                    break
                raise RuntimeError("Gemini reached its output limit before returning an answer.")
            if attempt + 1 >= max_attempts:
                raise RuntimeError("Gemini could not finish the response after automatic continuation.")
            if not response_parts:
                raise RuntimeError("Gemini reached its output limit without a continuation point.")
            # Keep the complete model turn, including signatures, for Gemini's next turn.
            contents.append({"role": "model", "parts": response_parts})
            contents.append({
                "role": "user",
                "parts": [{"text": "Continue exactly where the previous response stopped. Do not repeat earlier output. Return only the remaining transcript text, with no explanation or status notice."}],
            })
            continue
        break

    text = "".join(visible_chunks).strip()
    if not text:
        raise HTTPException(status_code=502, detail=f"{TYPEMYWORDZ_AI_NAME} did not get an answer back. Please try again.")
    return text

def _ask_claude(model_id, system_prompt, turns, question, images, max_tokens, auto_continue=False):
    """Call Claude; optionally continue internally rather than returning a truncated draft."""
    if not claude_client:
        raise HTTPException(status_code=503, detail=f"{TYPEMYWORDZ_AI_NAME} service is not initialized.")
    content = []
    for img in images:
        content.append({
            "type": "image",
            "source": {"type": "base64", "media_type": img["media_type"], "data": img["data"]},
        })
    content.append({"type": "text", "text": question})
    messages = [{"role": t["role"], "content": t["content"]} for t in turns]
    messages.append({"role": "user", "content": content})
    max_attempts = 12 if auto_continue else 1
    output_chunks = []
    for attempt in range(max_attempts):
        response = claude_client.messages.create(
            model=model_id,
            max_tokens=max(max_tokens, 16000 if auto_continue else 4000),
            system=system_prompt,
            messages=messages,
        )
        text = claude_text(response)
        if getattr(response, "stop_reason", None) == "max_tokens":
            if not auto_continue:
                if text:
                    return text + "\n\n[The answer was cut short because it reached its length limit. Ask me to continue and I will pick up where I stopped.]"
                raise RuntimeError("Claude reached its output limit before returning text.")
            if not text:
                raise RuntimeError("Claude reached its output limit without a continuation point.")
            output_chunks.append(text)
            if attempt + 1 >= max_attempts:
                raise RuntimeError("Claude could not finish the response after automatic continuation.")
            messages.append({"role": "assistant", "content": text.rstrip()})
            messages.append({
                "role": "user",
                "content": "Continue exactly where the previous response stopped. Do not repeat earlier output. Return only the remaining transcript text, with no explanation or status notice.",
            })
            continue
        if not text:
            if auto_continue:
                raise RuntimeError("Claude returned no transcript text.")
            return (
                "That answer came back empty, which is a hiccup on the model's side "
                "rather than anything you did. Ask again, or pick a different model "
                "in Settings."
            )
        output_chunks.append(text)
        return "".join(output_chunks).strip()
    raise RuntimeError("Claude could not finish the response after automatic continuation.")


@app.get("/credits/balance")
async def credits_balance(
    request: Request, user_id: str = "", user_email: str = "",
    billable_ai_balance: bool = False,
):
    """What this account can spend, and what each thing costs.

    The client shows this; it never decides it. Any refill or expiry noticed
    while reading is written back here, so the number a client sees is the
    number the server will actually honour. The main admin's optional billable
    AI view is authenticated and only reveals their own account balance.
    """
    if billable_ai_balance:
        decoded = _verified_user(request)
        verified_email = str(decoded.get("email") or "").strip().lower()
        if (
            not is_admin_user(verified_email)
            or str(decoded.get("uid") or decoded.get("user_id") or decoded.get("sub") or "") != str(user_id or "")
            or verified_email != str(user_email or "").strip().lower()
        ):
            raise HTTPException(status_code=403, detail="You can view only your own AI credit balance.")
    elif credits_exempt(user_email):
        return {"exempt": True, "unlimited": True, "planCredits": None,
                "topUpCredits": None, "total": None,
                "costs": {"transcription_per_minute": 1},
                "bundles": TOPUP_BUNDLES}

    if not user_id and user_email:
        user_id = await get_user_profile_by_email_firestore(user_email)
    profile = await _load_profile(user_id) if user_id else None
    if profile is None:
        raise HTTPException(status_code=404, detail="We could not find that account.")

    bal = read_balance(profile)
    if bal["updates"]:
        await _save_credit_updates(user_id, bal["updates"])

    return {
        "exempt": False,
        "unlimited": False,
        "planCredits": bal["planCredits"],
        "topUpCredits": bal["topUpCredits"],
        "total": bal["total"],
        "spendable": bal["spendable"],
        "frozen": bal["frozen"],
        "planActive": bal["planActive"],
        "planCreditsExpireAt": bal["planCreditsExpireAt"].isoformat() if bal["planCreditsExpireAt"] else None,
        "topUpCreditsExpireAt": bal["topUpCreditsExpireAt"].isoformat() if bal["topUpCreditsExpireAt"] else None,
        "costs": {
            "transcription_per_minute": 1,
            "ask": {m["id"]: m.get("credits", 1) for m in ASK_MODEL_CATALOGUE},
        },
        "bundles": TOPUP_BUNDLES,
    }


@app.get("/credits/quote")
async def credits_quote(seconds: float = 0, user_id: str = "", user_email: str = ""):
    """Can this account afford a file of this length?

    Asked before an upload starts, so that a client is told up front rather
    than after waiting for a transcript they cannot have.
    """
    cost = minutes_to_credits(seconds)
    if credits_exempt(user_email):
        return {"cost": 0, "affordable": True, "exempt": True, "balance": None}

    if not user_id and user_email:
        user_id = await get_user_profile_by_email_firestore(user_email)
    profile = await _load_profile(user_id) if user_id else None
    if profile is None:
        return {"cost": cost, "affordable": False, "exempt": False,
                "balance": 0, "short_by": cost}

    bal = read_balance(profile)
    return {
        "cost": cost,
        "balance": bal["total"],
        "spendable": bal["spendable"],
        "frozen": bal["frozen"],
        "planActive": bal["planActive"],
        "affordable": bal["spendable"] >= cost,
        "short_by": max(0, cost - bal["spendable"]),
        "exempt": False,
    }



