def _human_iso(value):
    if value is None:
        return None
    if hasattr(value, "isoformat"):
        return value.isoformat()
    return value


def _human_public(data):
    out = dict(data or {})
    for key, value in list(out.items()):
        if isinstance(value, dict):
            out[key] = _human_public(value)
        elif isinstance(value, list):
            out[key] = [_human_public(item) if isinstance(item, dict) else _human_iso(item) for item in value]
        else:
            out[key] = _human_iso(value)
    return out


# Workers must never see who the client is, and clients must never see who
# the worker is: every human job goes through admin, and admin is the only
# party allowed to see both sides. This strips the other side's identity off
# a job dict before it goes out, on top of the ordinary timestamp cleanup.
_HUMAN_CLIENT_IDENTITY_FIELDS = ("client_uid", "client_email", "client_name")
_HUMAN_WORKER_IDENTITY_FIELDS = ("worker_uid", "worker_email", "worker_name")


def _human_worker_segment(segments, actor_uid):
    """Select this worker's active part first, then their most recent part.

    A worker may be assigned a later split part after finishing an earlier
    one. Choosing the first matching segment would keep exposing the submitted
    part and hide the new active assignment.
    """
    owned = [item for item in (segments or []) if (item or {}).get("worker_uid") == actor_uid]
    active = next((item for item in owned if item.get("status") in {"assigned", "in_progress"}), None)
    return active or (owned[-1] if owned else None)


def _human_worker_feedback(data, actor_uid):
    """Return only this worker's job ratings and comments, never their source."""
    data = data or {}
    actor_uid = str(actor_uid or "")
    segments = data.get("segments") or []
    part_ratings = data.get("part_ratings") or {}
    feedback = []
    for part_id, item in part_ratings.items():
        if not isinstance(item, dict) or str(item.get("worker_uid") or "") != actor_uid:
            continue
        try:
            rating = float(item.get("rating"))
        except (TypeError, ValueError):
            continue
        if not math.isfinite(rating) or not 1 <= rating <= 5:
            continue
        if str(part_id) == "proofreader":
            label = "Final proofreading"
        elif str(part_id) == "main":
            label = "Full transcript"
        else:
            position = next((index + 1 for index, segment in enumerate(segments) if str((segment or {}).get("id") or "") == str(part_id)), None)
            label = f"Part {position}" if position else "Job part"
        note = str(item.get("note") or "").strip()
        note = re.sub(r"^\s*AI review\s*:\s*", "", note, flags=re.IGNORECASE)
        note = re.sub(r"\bAI review\b", "Admin review", note, flags=re.IGNORECASE).strip()
        feedback.append({"label": label, "rating": rating, "note": note, "rater": "Admin"})

    # Older and non-split jobs store a single job rating and general feedback.
    assigned = bool(actor_uid) and (
        actor_uid == str(data.get("worker_uid") or "")
        or actor_uid == str(data.get("proofreader_uid") or "")
        or actor_uid in {str(uid) for uid in (data.get("assigned_worker_uids") or [])}
        or any(str((segment or {}).get("worker_uid") or "") == actor_uid for segment in segments)
    )
    if assigned and not feedback:
        ratings_by_worker = data.get("worker_ratings") or {}
        raw_rating = ratings_by_worker.get(actor_uid, data.get("worker_rating"))
        try:
            rating = float(raw_rating)
        except (TypeError, ValueError):
            rating = None
        if rating is not None and math.isfinite(rating) and 1 <= rating <= 5:
            feedback.append({
                "label": "Overall job review", "rating": rating,
                "note": str(data.get("admin_feedback") or "").strip(), "rater": "Admin",
            })
    return feedback


def _human_worker_audio_gate(job, uid, segment_id=""):
    """Decide whether a transcribing worker may open the recording yet.

    Returns (locked, key). The recording stays closed until the worker has
    generated their formatted draft, so the audio cannot be taken outside the
    system. Proofreaders, admins and clients are never gated here. An admin can
    unlock one assignment by hand if drafting fails (job["audio_unlocked"]).
    """
    if str(job.get("job_type") or "").lower() in {"pdf_job", "letter_job"}:
        return False, ""
    uid = str(uid or "")
    if _human_is_split_job(job):
        mine = [
            item for item in (job.get("segments") or [])
            if str(item.get("worker_uid") or "") == uid and item.get("status") in {"assigned", "in_progress"}
        ]
        if segment_id:
            mine = [item for item in mine if item.get("id") == segment_id]
        if not mine:
            return False, ""
        key = str(mine[0].get("id") or "")
    else:
        if str(job.get("worker_uid") or "") != uid or job.get("status") not in {"assigned", "in_progress"}:
            return False, ""
        key = "main"
    draft = (job.get("ai_drafts") or {}).get(key) or {}
    if str(draft.get("worker_uid") or "") == uid and str(draft.get("text") or "").strip():
        return False, key
    if (job.get("audio_unlocked") or {}).get(key):
        return False, key
    return True, key


def _human_audio_lock_entries(job):
    """Assignments whose worker is still waiting for the recording (shown to admins)."""
    entries = []
    if _human_is_split_job(job):
        for item in job.get("segments") or []:
            uid = str(item.get("worker_uid") or "")
            if uid and _human_worker_audio_gate(job, uid, str(item.get("id") or ""))[0]:
                entries.append({"key": str(item.get("id") or ""), "label": str(item.get("label") or "Part")})
    else:
        uid = str(job.get("worker_uid") or "")
        if uid and _human_worker_audio_gate(job, uid)[0]:
            entries.append({"key": "main", "label": "Whole job"})
    return entries


def _human_public_for(data, actor_role, actor_uid=""):
    """Serialize a human job without leaking the other side's identity.

    Split jobs keep one parent record but expose only the current worker's
    segment to that worker. Admins see the full assignment map.
    """
    data = data or {}
    out = _human_public(data)
    if actor_role not in {"admin", "human_ops_admin"}:
        for key in (
        "ai_agent_docx", "ai_agent_paused_segments", "ai_agent_previous_split_mode", "ai_agent_previous_status", "ai_agent_scope",
        "letter_agent_run_id", "letter_agent_error", "letter_agent_model_ids", "letter_agent_completedAt", "letter_agent_failedAt",
        "letter_ai_review_error", "letter_ai_review_attachment", "letter_ai_review_model_ids", "letter_ai_review_startedAt",
        "letter_ai_review_completedAt", "letter_ai_review_failedAt",
    ):
            out.pop(key, None)
    pdf_image = out.get("pdf_image") or {}
    if pdf_image:
        out["pdf_image"] = {key: pdf_image[key] for key in ("name", "content_type", "size", "source_filename", "page_number", "page_count") if key in pdf_image}
    if actor_role not in {"admin", "human_ops_admin"}:
        out.pop("worker_ratings", None)
        out.pop("worker_rating", None)
    segments = data.get("segments") or []
    if actor_role in {"admin", "human_ops_admin"}:
        out["audio_locked_assignments"] = _human_audio_lock_entries(data)
    if actor_role in {"worker", "client"}:
        for key in (
            "last_assignment_takeback_at", "last_assignment_takeback_worker_uid",
            "last_assignment_takeback_worker_name", "last_assignment_takeback_role",
            "last_assignment_takeback_label", "last_assignment_takeback_by_uid",
            "last_assignment_takeback_by_email",
        ):
            out.pop(key, None)

    def remaining(deadline, status):
        deadline_dt = _as_dt(deadline)
        if deadline_dt is not None and status in ("assigned", "in_progress"):
            return max(0, int((deadline_dt - datetime.now()).total_seconds()))
        return None

    if actor_role == "worker":
        out["my_job_ratings"] = _human_worker_feedback(data, actor_uid)
        for key in ("ai_agent_status", "ai_agent_id", "ai_agent_name", "ai_agent_model_ids", "ai_agent_run_id", "ai_agent_error", "ai_agent_completedAt", "ai_agent_docx", "ai_agent_scope"):
            out.pop(key, None)
        out.pop("last_message", None)
        out.pop("last_message_by_thread", None)
        out.pop("admin_feedback", None)
        for key in _HUMAN_CLIENT_IDENTITY_FIELDS:
            out.pop(key, None)
        for key in ("quote_credits", "credits_charged", "credits_deducted", "credit_cost", "price", "amount", "currency", "quote"):
            out.pop(key, None)
        owned_segment = _human_worker_segment(segments, actor_uid)
        assignment = dict(owned_segment) if owned_segment else None
        if assignment is not None:
            assignment["time_remaining_seconds"] = remaining(assignment.get("deadlineAt"), assignment.get("status"))
            assignment["role"] = "transcriber"
        if assignment is None and data.get("worker_uid") == actor_uid:
            assignment = {
                "id": "transcriber", "label": "Full transcript", "role": "transcriber",
                "status": data.get("status"), "transcript": data.get("transcript") or "",
                "transcript_html": data.get("transcript_html") or "",
                "final_attachment": _human_public(data.get("final_attachment") or {}) if data.get("final_attachment") else None,
                "assignedAt": data.get("assignedAt"), "deadlineAt": data.get("deadlineAt"),
                "time_remaining_seconds": remaining(data.get("deadlineAt"), data.get("status")),
                "start_seconds": 0, "end_seconds": data.get("seconds"),
            }
        if data.get("proofreader_uid") == actor_uid:
            assignment = {
                "id": "proofreader",
                "label": "Final proofreading",
                "role": "proofreader",
                "status": data.get("proofreader_status"),
                "transcript": data.get("transcript") or "\n\n".join(
                    item.get("transcript", "") for item in segments if item.get("transcript")
                ),
                "transcript_html": data.get("transcript_html") or "",
                "assignedAt": data.get("proofreader_assignedAt"),
                # The proofreader must start with a clean final-file input;
                # the earlier segment attachments are presented separately.
                "final_attachment": None,
                "deadlineAt": data.get("proofreader_deadlineAt"),
                "time_remaining_seconds": remaining(data.get("proofreader_deadlineAt"), data.get("proofreader_status")),
                "worker_minutes": data.get("minutes"),
            }
            proofreader_overrides = data.get("proofreader_parts_override") or {}
            def proofreader_part_content(item, field):
                override = proofreader_overrides.get(str(item.get("id") or ""))
                source = override if isinstance(override, dict) else item
                return source.get(field) or ""
            out["proofreader_parts"] = [
                {
                    "id": item.get("id"),
                    "label": item.get("label") or f"Part {index + 1}",
                    "index": index + 1,
                    "status": item.get("status"),
                    "pending": item.get("status") != "submitted",
                    # Attribute only by slice position, never disclose whether
                    # an internal AI agent or which human prepared the part.
                    "author_label": f"Worker {index + 1}",
                    "transcript": proofreader_part_content(item, "transcript") if item.get("status") == "submitted" else "",
                    "transcript_html": proofreader_part_content(item, "transcript_html") if item.get("status") == "submitted" else "",
                    "final_attachment": _human_public(item.get("final_attachment") or {}) if item.get("final_attachment") and item.get("status") == "submitted" else None,
                }
                for index, item in enumerate(segments)
            ]
        if assignment is not None:
            for key in ("worker_amount_kes", "worker_gross_amount_kes", "worker_deduction_kes", "worker_deduction_reason", "workerPaymentStatus", "workerPaidAt", "payout_status", "payout_period_id", "ai_agent_id", "ai_agent_name", "ai_agent_model_ids", "ai_agent_run_id", "ai_agent_status", "ai_agent_error", "ai_agent_docx", "ai_agent_scope"):
                assignment.pop(key, None)
            assignment = _human_public(assignment)
            out["worker_assignment"] = assignment
            out["time_remaining_seconds"] = assignment.get("time_remaining_seconds")
            out["transcript"] = assignment.get("transcript") or ""
            out["transcript_html"] = assignment.get("transcript_html") or ""
            out["final_attachment"] = assignment.get("final_attachment")
            if assignment.get("role") == "transcriber":
                out["audio_locked"] = _human_worker_audio_gate(data, actor_uid, str(assignment.get("id") or "") if owned_segment else "")[0]
                draft = (data.get("ai_drafts") or {}).get(str(assignment.get("id") or "main") if owned_segment else "main") or {}
                if draft.get("worker_uid") == actor_uid and draft.get("text"):
                    out["ai_draft"] = draft.get("text")
                    proofread = draft.get("proofread") or {}
                    if proofread.get("worker_uid") == actor_uid and proofread.get("text"):
                        out["ai_draft_proofread"] = proofread.get("text")
        else:
            out["transcript_html"] = ""
        if data.get("proofreader_uid") == actor_uid:
            mine = data.get("proofreader_suggested_ratings") or {}
            out["my_suggested_ratings"] = {k: {"rating": v.get("rating"), "note": v.get("note") or ""} for k, v in mine.items() if isinstance(v, dict)}
        # Preserve only the authorized worker-facing draft text above; never
        # return raw draft records that include provider/model metadata.
        out.pop("ai_drafts", None)
        for key in ("ai_review", "ai_review_run", "part_ratings", "whole_job_assignment", "proofreader_suggested_ratings", "proofreader_parts_override", "audio_unlocked"):
            out.pop(key, None)
        for key in (
            "worker_minutes", "worker_amount_kes", "worker_gross_amount_kes", "worker_deduction_kes", "worker_deduction_reason",
            "workerPaymentStatus", "workerPaidAt", "payout_status", "payout_period_id",
            "proofreader_minutes", "proofreader_amount_kes", "proofreader_gross_amount_kes", "proofreader_deduction_kes", "proofreader_deduction_reason",
            "proofreader_payout_status", "proofreader_payout_period_id", "proofreaderPaidAt",
        ):
            out.pop(key, None)
        out.pop("segments", None)
        out.pop("assigned_worker_uids", None)
        out.pop("proofreader_uid", None)
        out.pop("proofreader_email", None)
        out.pop("proofreader_name", None)
        out.pop("proofreader_status", None)
        out.pop("proofreader_deadlineAt", None)
        out.pop("proofreader_tat_seconds", None)
        out.pop("proofreader_completedAt", None)
        out.pop("proofreader_minutes", None)
        out.pop("proofreader_amount_kes", None)
        out.pop("proofreader_payout_status", None)
        out.pop("proofreader_payout_period_id", None)
    elif actor_role == "client":
        for key in ("ai_drafts", "ai_review", "ai_review_run", "ai_agent_status", "ai_agent_id", "ai_agent_name", "ai_agent_model_ids", "ai_agent_run_id", "ai_agent_error", "ai_agent_completedAt", "ai_agent_docx", "ai_agent_scope", "ai_agent_paused_segments", "ai_agent_previous_split_mode", "ai_agent_previous_status", "part_ratings", "whole_job_assignment", "proofreader_suggested_ratings", "proofreader_parts_override", "proofreader_use_combined_transcript"):
            out.pop(key, None)
        out.pop("last_message", None)
        out.pop("last_message_by_thread", None)
        for key in _HUMAN_WORKER_IDENTITY_FIELDS:
            out.pop(key, None)
        for segment in out.get("segments") or []:
            if isinstance(segment, dict):
                for key in _HUMAN_WORKER_IDENTITY_FIELDS:
                    segment.pop(key, None)
        out.pop("assigned_worker_uids", None)
        out.pop("segments", None)
        for key in ("proofreader_uid", "proofreader_email", "proofreader_name"):
            out.pop(key, None)
    else:
        # Human-work admins get assignment details and useful countdowns.
        public_segments = []
        for item in out.get("segments") or []:
            if isinstance(item, dict):
                item["time_remaining_seconds"] = remaining(item.get("deadlineAt"), item.get("status"))
                if actor_role == "human_ops_admin":
                    for key in ("worker_minutes", "worker_amount_kes", "worker_gross_amount_kes", "worker_deduction_kes", "worker_deduction_reason", "workerPaymentStatus", "workerPaidAt", "payout_status", "payout_period_id"):
                        item.pop(key, None)
            public_segments.append(item)
        out["segments"] = public_segments
        out["time_remaining_seconds"] = remaining(data.get("deadlineAt"), data.get("status"))
        if data.get("proofreader_status") in ("assigned", "in_progress"):
            out["proofreader_time_remaining_seconds"] = remaining(data.get("proofreader_deadlineAt"), data.get("proofreader_status"))
        if actor_role == "human_ops_admin":
            for key in (
                "worker_minutes", "worker_amount_kes", "worker_gross_amount_kes", "worker_deduction_kes", "worker_deduction_reason",
                "workerPaymentStatus", "workerPaidAt", "payout_status", "payout_period_id",
                "proofreader_minutes", "proofreader_amount_kes", "proofreader_gross_amount_kes", "proofreader_deduction_kes", "proofreader_deduction_reason",
                "proofreader_payout_status", "proofreader_payout_period_id", "proofreaderPaidAt", "quote",
            ):
                out.pop(key, None)
    return out


def _human_available_public_for(data, actor_uid, claimable_parts, claimable_full_job, can_claim, claim_block_reason, claim_attempt_counts=None):
    """Expose only claim-list metadata until the worker owns the job or part."""
    claim_attempt_counts = claim_attempt_counts or {}
    public_item = _human_public_for(data, "worker", actor_uid)
    audio_meta = public_item.get("audio") or {}
    public_item["audio"] = {key: audio_meta[key] for key in ("name", "content_type", "size") if key in audio_meta}
    public_item["instruction_attachments"] = []
    public_item["transcript"] = ""
    public_item["worker_notes"] = ""
    public_item["final_attachment"] = None
    public_item["proofreader_parts"] = []
    public_item.pop("worker_assignment", None)
    public_item.pop("segments", None)
    public_item.pop("assigned_worker_uids", None)
    public_item.pop("worker_uid", None)
    public_item.pop("worker_email", None)
    public_item.pop("worker_name", None)
    public_item.pop("last_auto_reassigned_worker_name", None)
    for part in claimable_parts:
        item_key = _human_claim_item_key(data.get("id") or "", part.get("id") or "")
        used = int(claim_attempt_counts.get(item_key) or 0)
        part["claim_attempt_count"] = used
        part["can_claim"] = bool(can_claim and used < HUMAN_WORKER_MAX_CLAIMS_PER_ITEM)
        part["claim_block_reason"] = (
            "You have already claimed this job part once. It cannot be claimed again."
            if used >= HUMAN_WORKER_MAX_CLAIMS_PER_ITEM else claim_block_reason
        )
    whole_key = _human_claim_item_key(data.get("id") or "", "")
    whole_used = int(claim_attempt_counts.get(whole_key) or 0)
    public_item["claimable_parts"] = claimable_parts
    public_item["claimable_full_job"] = claimable_full_job
    public_item["claim_attempt_count"] = whole_used if claimable_full_job else 0
    public_item["max_claims_per_item"] = HUMAN_WORKER_MAX_CLAIMS_PER_ITEM
    public_item["can_claim"] = bool(can_claim and (not claimable_full_job or whole_used < HUMAN_WORKER_MAX_CLAIMS_PER_ITEM))
    public_item["claim_block_reason"] = (
        "You have already claimed this job once. It cannot be claimed again."
        if claimable_full_job and whole_used >= HUMAN_WORKER_MAX_CLAIMS_PER_ITEM else claim_block_reason
    )
    return public_item


def _human_bucket():
    if not FIREBASE_ADMIN_SDK_CONFIG_BASE64:
        return None
    try:
        configured = (os.getenv("FIREBASE_STORAGE_BUCKET") or os.getenv("GCS_BUCKET_NAME") or "").strip()
        return firebase_storage.bucket(configured) if configured else firebase_storage.bucket()
    except Exception as exc:
        logger.warning("Human workflow storage is unavailable: %s", exc)
        return None


def _training_assets_bucket():
    """Use a dedicated private bucket so training files never change job storage."""
    if not FIREBASE_ADMIN_SDK_CONFIG_BASE64:
        return None
    try:
        configured = (os.getenv("TRAINING_ASSET_STORAGE_BUCKET") or "").strip()
        if not configured:
            logger.warning("Training asset storage bucket is not configured.")
            return None
        return firebase_storage.bucket(configured)
    except Exception as exc:
        logger.warning("Private training asset storage is unavailable: %s", exc)
        return None


async def _human_store_upload(job_id: str, upload: UploadFile, folder: str):
    if not upload or not upload.filename:
        return None
    raw = await upload.read()
    if not raw:
        raise HTTPException(status_code=400, detail=f"{upload.filename} is empty.")
    if len(raw) > 500 * 1024 * 1024:
        raise HTTPException(status_code=413, detail=f"{upload.filename} is larger than 500 MB.")
    safe_name = re.sub(r"[^A-Za-z0-9._-]+", "_", os.path.basename(upload.filename))[:180] or "attachment"
    path = f"human-workflow/{job_id}/{folder}/{uuid.uuid4().hex}-{safe_name}"
    bucket = _human_bucket()
    if bucket is None:
        raise HTTPException(status_code=503, detail="File storage is not ready yet. Please try again shortly.")
    blob = bucket.blob(path)
    # Run the network upload off the event loop so other requests keep flowing.
    await asyncio.to_thread(blob.upload_from_string, raw, content_type=upload.content_type or "application/octet-stream")
    return {
        "name": upload.filename,
        "storage_path": path,
        "content_type": upload.content_type or "application/octet-stream",
        "size": len(raw),
    }


def _human_store_raw_bytes(job_id: str, filename: str, raw: bytes, content_type: str, folder: str):
    if not raw:
        raise HTTPException(status_code=400, detail=f"{filename or 'The uploaded image'} is empty.")
    safe_name = re.sub(r"[^A-Za-z0-9._-]+", "_", os.path.basename(filename or "image.jpg"))[:180] or "image.jpg"
    path = f"human-workflow/{job_id}/{folder}/{uuid.uuid4().hex}-{safe_name}"
    bucket = _human_bucket()
    if bucket is None:
        raise HTTPException(status_code=503, detail="File storage is not ready yet. Please try again shortly.")
    bucket.blob(path).upload_from_string(raw, content_type=content_type or "application/octet-stream")
    return {"name": filename or safe_name, "storage_path": path, "content_type": content_type or "application/octet-stream", "size": len(raw)}


def _human_template_attachment(job):
    """Select the one job-attached DOCX template; never guess between files."""
    attachments = list((job or {}).get("instruction_attachments") or [])
    candidates = []
    explicit = []
    for index, raw_meta in enumerate(attachments):
        meta = raw_meta or {}
        name = str(meta.get("name") or "")
        content_type = str(meta.get("content_type") or "").lower()
        if not (name.lower().endswith(".docx") or "wordprocessingml.document" in content_type):
            continue
        candidates.append((index, meta))
        marker = str(meta.get("purpose") or meta.get("role") or "").strip().lower()
        if meta.get("is_template") is True or marker in {"template", "job_template", "letter_template"}:
            explicit.append((index, meta))
    if len(explicit) == 1:
        return explicit[0]
    if len(explicit) > 1 or len(candidates) > 1:
        raise ValueError("More than one Word document is attached. Mark the intended template or leave only one .docx attached so the agent cannot choose the wrong file.")
    if not candidates:
        raise ValueError("Attach the template for this job as a .docx file before assigning the template-aware agent.")
    return candidates[0]


async def _human_template_docx_bytes(job_id, job):
    try:
        _index, meta = _human_template_attachment(job)
    except ValueError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    path = str(meta.get("storage_path") or "")
    if not path or not path.startswith(f"human-workflow/{job_id}/instructions/"):
        raise HTTPException(status_code=409, detail="The attached Word template is not in this job's private reference storage.")
    if int(meta.get("size") or 0) > 25000000:
        raise HTTPException(status_code=413, detail="The attached Word template is larger than the 25 MB rendering limit.")
    bucket = _human_bucket()
    if bucket is None:
        raise HTTPException(status_code=503, detail="Private file storage is not ready yet. Please try again shortly.")
    blob = bucket.blob(path)
    if not await asyncio.to_thread(blob.exists):
        raise HTTPException(status_code=404, detail="The Word template attached to this job could not be found.")
    raw = await asyncio.to_thread(blob.download_as_bytes)
    if not raw or len(raw) > 25000000:
        raise HTTPException(status_code=413, detail="The attached Word template is empty or larger than the 25 MB rendering limit.")
    return meta, raw


def _human_template_docx_profile(raw):
    """Describe the actual job template's paragraph styles for the agent and renderer."""
    from docx.oxml.ns import qn

    document = Document(BytesIO(raw))
    if document.tables:
        raise ValueError("This Word template uses tables. The safe first release supports paragraph-based DOCX templates; no draft was assigned or changed.")
    body = document.element.body
    for child in body.iterchildren():
        if child.tag not in {qn("w:p"), qn("w:sectPr")}:
            raise ValueError("This Word template contains a layout element the renderer cannot safely preserve yet. Use a paragraph-based .docx template instead.")
    rows = []
    for index, paragraph in enumerate(document.paragraphs):
        if paragraph._p.xpath(".//w:drawing") or paragraph._p.xpath(".//w:pict") or paragraph._p.xpath(".//w:object") or paragraph._p.xpath(".//w:hyperlink") or paragraph._p.xpath(".//w:fldSimple") or paragraph._p.xpath(".//w:instrText") or paragraph._p.xpath(".//w:br"):
            raise ValueError("This Word template contains an embedded object, link, field or manual page/line break in its body. The renderer will not remove it; use a paragraph-based template without those elements.")
        if paragraph._p.pPr is not None and paragraph._p.pPr.find(qn("w:sectPr")) is not None:
            raise ValueError("This Word template has multiple section breaks. The renderer cannot preserve them safely yet.")
        text = str(paragraph.text or "")
        if not text.strip():
            continue
        fmt = paragraph.paragraph_format
        alignment = {None: "template default", 0: "left", 1: "center", 2: "right", 3: "justified"}.get(paragraph.alignment, "template default")
        def inches(value):
            return "default" if value is None else f"{float(value.inches):.2f} in"
        runs = [run for run in paragraph.runs if run.text]
        sample_run = runs[0] if runs else None
        font_name = (sample_run.font.name if sample_run else None) or "style inherited"
        font_size = sample_run.font.size.pt if sample_run and sample_run.font.size else None
        run_marks = []
        if sample_run and sample_run.bold:
            run_marks.append("bold")
        if sample_run and sample_run.italic:
            run_marks.append("italic")
        if sample_run and sample_run.underline:
            run_marks.append("underlined")
        rows.append(
            f"P{index}: style={paragraph.style.name if paragraph.style else 'Normal'}; alignment={alignment}; "
            f"left-indent={inches(fmt.left_indent)}; first-line-indent={inches(fmt.first_line_indent)}; "
            f"spacing-before={fmt.space_before.pt if fmt.space_before else 0}pt; "
            f"spacing-after={fmt.space_after.pt if fmt.space_after else 0}pt; "
            f"line-spacing={fmt.line_spacing}; font={font_name}{f' {font_size:g}pt' if font_size else ''}; "
            f"marks={','.join(run_marks) or 'plain'}; sample={text[:220]!r}"
        )
    if not rows:
        raise ValueError("The attached Word template has no readable paragraphs.")
    section = document.sections[0]
    page = section.page_width, section.page_height
    margins = section.top_margin, section.right_margin, section.bottom_margin, section.left_margin
    page_line = (
        f"Page size: {page[0].inches:.2f} x {page[1].inches:.2f} inches; "
        f"margins top/right/bottom/left: " + "/".join(f"{value.inches:.2f} in" for value in margins)
    )
    return page_line + "\n" + "\n".join(rows)


def _human_template_line_kind(text):
    value = str(text or "")
    stripped = value.strip()
    if not stripped:
        return "blank"
    if stripped.startswith("[") or stripped.lower().startswith(("client spellings:", "my spellings:", "i searched:", "research notes:")):
        return "flush"
    if re.match(r"^\s*\d+[.)]\s", value):
        return "numbered"
    if len(stripped) <= 100 and any(char.isalpha() for char in stripped) and stripped.isupper():
        return "heading"
    if re.match(r"^(date|re|dear|file no\.?|claim date|email|cc|enclosures)\b", stripped, re.IGNORECASE):
        return "label"
    return "body"


def _human_template_source_kind(paragraph):
    text = str(paragraph.text or "")
    stripped = text.strip()
    if not stripped:
        return "blank"
    if len(stripped) <= 100 and any(char.isalpha() for char in stripped) and stripped.isupper():
        return "heading"
    if re.match(r"^(date|re|dear|file no\.?|claim date|email|cc|enclosures)\b", stripped, re.IGNORECASE):
        return "label"
    fmt = paragraph.paragraph_format
    if text.startswith("\t") or (fmt.first_line_indent is not None and fmt.first_line_indent.inches > 0):
        return "body"
    return "flush"


def _human_template_render_docx(template_bytes, draft_text):
    """Replace template copy with the private draft while retaining its Word layout and styles."""
    from docx.oxml import OxmlElement
    from docx.text.paragraph import Paragraph

    _human_template_docx_profile(template_bytes)
    document = Document(BytesIO(template_bytes))
    if document.tables:
        raise ValueError("This Word template uses tables. It was not modified; use a paragraph-based .docx template.")
    body = document.element.body
    source_paragraphs = list(document.paragraphs)
    for paragraph in source_paragraphs:
        if paragraph._p.xpath(".//w:drawing") or paragraph._p.xpath(".//w:pict") or paragraph._p.xpath(".//w:object"):
            raise ValueError("This Word template contains an embedded body object and cannot be safely rewritten.")
    if not source_paragraphs:
        raise ValueError("The attached Word template has no paragraphs to format the draft.")

    source_texts = [str(paragraph.text or "") for paragraph in source_paragraphs]
    source_kinds = [_human_template_source_kind(paragraph) for paragraph in source_paragraphs]
    body_sources = [
        paragraph for paragraph, kind in zip(source_paragraphs, source_kinds)
        if kind == "body" and str(paragraph.text or "").strip()
    ]
    if not body_sources:
        body_sources = [paragraph for paragraph in source_paragraphs if str(paragraph.text or "").strip()]
    if not body_sources:
        raise ValueError("The attached Word template has no usable paragraph styles.")
    default_source = max(body_sources, key=lambda paragraph: len(paragraph.text or ""))

    def choose_source(line):
        kind = _human_template_line_kind(line)
        if kind == "blank":
            return next((paragraph for paragraph, source_kind in zip(source_paragraphs, source_kinds) if source_kind == "blank"), default_source)
        output = str(line or "").strip().casefold()
        label_match = re.match(r"^(date|re|dear|file no\.?|claim date|email|cc|enclosures)\b", output)
        best = None
        best_score = -100
        for paragraph, source_kind in zip(source_paragraphs, source_kinds):
            sample = str(paragraph.text or "").strip().casefold()
            score = 0
            if source_kind == kind:
                score += 4
            elif kind in {"label", "flush"} and source_kind == "flush":
                score += 1
            if label_match and sample.startswith(label_match.group(1)):
                score += 12
            if output and sample and (output.startswith(sample[: min(len(sample), 12)]) or sample.startswith(output[: min(len(output), 12)])):
                score += 3
            if kind == "body":
                if paragraph.paragraph_format.first_line_indent is not None and paragraph.paragraph_format.first_line_indent.inches > 0:
                    score += 2
                if str(paragraph.text or "").startswith("\t"):
                    score += 2
                score += min(len(sample), 500) / 500
            if kind == "heading" and paragraph.alignment == 1:
                score += 2
            if score > best_score:
                best, best_score = paragraph, score
        if kind == "body" and best_score < 4:
            return default_source
        return best or default_source

    def add_styled_run(paragraph, text, source_run=None):
        if not text:
            return
        run = paragraph.add_run()
        if source_run is not None and source_run._r.rPr is not None:
            run._r.insert(0, deepcopy(source_run._r.rPr))
        run.text = text

    normalized = str(draft_text or "").replace("\r\n", "\n").replace("\r", "\n").strip("\n")
    lines = normalized.split("\n") if normalized else [""]
    for paragraph in source_paragraphs:
        body.remove(paragraph._p)

    for line in lines:
        source = choose_source(line)
        rendered_line = line
        source_format = source.paragraph_format
        has_template_indent = bool(
            (source_format.left_indent is not None and source_format.left_indent.inches > 0)
            or (source_format.first_line_indent is not None and source_format.first_line_indent.inches > 0)
        )
        if _human_template_line_kind(line) == "body" and line.startswith("\t") and has_template_indent:
            rendered_line = line[1:]
        new_p = OxmlElement("w:p")
        if source._p.pPr is not None:
            new_p.append(deepcopy(source._p.pPr))
        insert_at = len(body) - (1 if body.sectPr is not None else 0)
        body.insert(insert_at, new_p)
        target = Paragraph(new_p, document._body)
        if not rendered_line:
            continue
        source_runs = [run for run in source.runs if run.text]
        source_text = "".join(run.text for run in source_runs)
        prefix_len = 0
        while prefix_len < min(len(source_text), len(rendered_line)) and source_text[prefix_len] == rendered_line[prefix_len]:
            prefix_len += 1
        if prefix_len and source_runs:
            consumed = 0
            boundary_run = source_runs[-1]
            for source_run in source_runs:
                take = min(len(source_run.text or ""), prefix_len - consumed)
                if take > 0:
                    add_styled_run(target, rendered_line[consumed:consumed + take], source_run)
                    consumed += take
                if consumed >= prefix_len:
                    boundary_run = source_run
                    break
            if prefix_len < len(rendered_line):
                add_styled_run(target, rendered_line[prefix_len:], boundary_run)
        else:
            add_styled_run(target, rendered_line, source_runs[0] if source_runs else None)

    output = BytesIO()
    document.save(output)
    return output.getvalue()


def _human_letter_template_bytes():
    """Load the user-supplied standard letter template bundled with the backend."""
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "letter_standard_indentation.docx.b64")
    try:
        with open(path, "r", encoding="ascii") as handle:
            encoded = "".join(handle.read().split())
        raw = base64.b64decode(encoded, validate=True)
        _human_template_docx_profile(raw)
        return raw
    except Exception as exc:
        raise RuntimeError("The bundled Letter Standard Indentation template could not be loaded or validated.") from exc


def _human_letter_guidelines():
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "letter_agent_guidelines.txt")
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read().strip()
    except OSError as exc:
        raise RuntimeError("The permanent Letter Agent guidelines could not be loaded.") from exc
    if not text:
        raise RuntimeError("The permanent Letter Agent guidelines are empty.")
    return text


def _human_letter_render_docx(template_bytes, draft_text):
    """Render the final letter in the supplied template and bold bracketed staff directions."""
    output = _human_template_render_docx(template_bytes, draft_text)
    document = Document(BytesIO(output))
    for paragraph in document.paragraphs:
        text = str(paragraph.text or "").strip()
        staff_instruction = text.startswith("[") and text.endswith("]")
        for run in paragraph.runs:
            # The letter guide allows bold only for bracketed instructions to staff.
            run.bold = True if staff_instruction else False
    rendered = BytesIO()
    document.save(rendered)
    return rendered.getvalue()


def _human_letter_docx_text(raw):
    """Read Word paragraph and table text for the independent letter reviewer."""
    from docx.oxml.ns import qn
    from docx.table import Table
    from docx.text.paragraph import Paragraph

    try:
        document = Document(BytesIO(raw))
    except Exception as exc:
        raise ValueError("The submitted file is not a readable Word .docx document.") from exc
    parts = []
    for child in document.element.body.iterchildren():
        if child.tag == qn("w:p"):
            parts.append(Paragraph(child, document).text)
        elif child.tag == qn("w:tbl"):
            table = Table(child, document)
            for row in table.rows:
                parts.append("	".join(cell.text for cell in row.cells))
    text = "\n".join(parts).strip()
    if not text:
        raise ValueError("The Word .docx file is empty.")
    return text


def _human_worker_audio_cache_key(storage_path, size=0, segment_id="", start_seconds=None, end_seconds=None):
    """Version worker playback caches by source object and exact assigned range."""
    fingerprint = "|".join((
        str(storage_path or ""), str(size or 0), str(segment_id or ""),
        "" if start_seconds is None else str(start_seconds),
        "" if end_seconds is None else str(end_seconds),
    ))
    return hashlib.sha256(fingerprint.encode("utf-8")).hexdigest()[:20]


def _human_deadline_event_id(job_id, role, item_id, assignment_token, qualification_cycle="initial"):
    raw = "|".join((str(job_id or ""), str(role or ""), str(item_id or ""), str(assignment_token or ""), str(qualification_cycle or "initial")))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _human_deadline_assignment_token(item):
    item = item or {}
    return _human_iso(item.get("assignedAt")) or _human_iso(item.get("deadlineAt")) or "missing-assignment-time"


def _human_worker_retraining_updates(profile, deadline_return_count, now):
    profile = profile or {}
    if deadline_return_count < HUMAN_WORKER_DEADLINE_LOCKOUT_RETURNS or profile.get("workerApproved") is not True:
        return {}
    levels = list(range(1, len(TRAINING_LEVELS) + 1))
    return {
        "role": "trainee",
        "workerApproved": False,
        "trainingRoomAccess": True,
        "trainingStatus": "active",
        "traineeStatus": "enrolled",
        "trainingLevel": 1,
        "trainingSubmissions": {str(level): "redo_requested" for level in levels},
        "trainingRedoLevels": levels,
        "trainingRedoMessage": "Your available-work access is paused after repeated missed deadlines. Please retake the six Training Room modules and typing practice; your prior training and payout history remain on record.",
        "trainingRedoInvitedAt": now,
        "worker_retraining_required": True,
        "worker_retraining_required_at": now,
        "updatedAt": firestore.SERVER_TIMESTAMP,
    }


async def _human_archive_retraining_attempts(worker_uid):
    """Move each saved module into redo mode without losing its prior attempt."""
    if not db or not worker_uid:
        return
    for level in range(1, len(TRAINING_LEVELS) + 1):
        ref = db.collection("training_submissions").document(f"{worker_uid}-{level}")
        try:
            snapshot = await asyncio.to_thread(ref.get)
            previous = snapshot.to_dict() if snapshot.exists else {}
            history = list(previous.get("previous_attempts") or [])
            if str(previous.get("status") or "").lower() == "submitted":
                history.append({
                    "transcript": previous.get("transcript") or "",
                    "notes": previous.get("notes") or "",
                    "answers": previous.get("answers") or {},
                    "archivedAt": datetime.now().isoformat(),
                })
            await asyncio.to_thread(ref.set, {
                "uid": worker_uid, "level": level, "status": "redo_requested",
                "previous_attempts": history[-10:], "redoRequestedAt": previous.get("redoRequestedAt") or datetime.now().isoformat(),
                "updatedAt": firestore.SERVER_TIMESTAMP,
            }, merge=True)
        except Exception as exc:
            logger.warning("Could not reset Training Room module %s for worker %s: %s", level, worker_uid, exc)


def _human_shift_local_now():
    return datetime.now(HUMAN_SHIFT_TIMEZONE)


def _human_shift_parse_datetime(value):
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(HUMAN_SHIFT_TIMEZONE)
    except (TypeError, ValueError):
        return None


def _human_shift_is_scheduled(now=None):
    now = now or _human_shift_local_now()
    local_now = now.astimezone(HUMAN_SHIFT_TIMEZONE)
    local_time = local_now.timetz().replace(tzinfo=None)
    return local_now.weekday() < 5 and HUMAN_SHIFT_START <= local_time < HUMAN_SHIFT_END


def _human_shift_call_in_active(profile, now=None):
    now = now or _human_shift_local_now()
    expiry = _human_shift_parse_datetime((profile or {}).get("humanShiftCallInExpiresAt"))
    return bool(expiry and expiry > now.astimezone(HUMAN_SHIFT_TIMEZONE))


def _human_shift_doc_id(uid, shift_date):
    return f"{uid}_{shift_date}"


async def _human_shift_reconcile(uid, profile=None, now=None):
    """Record each completed daily shift once and return the latest worker profile."""
    if not db or not uid:
        return dict(profile or {})
    profile = dict(profile if profile is not None else (await _load_profile(uid) or {}))
    if profile.get("workerApproved") is not True:
        return profile
    local_now = (now or _human_shift_local_now()).astimezone(HUMAN_SHIFT_TIMEZONE)
    through = local_now.date() if local_now.timetz().replace(tzinfo=None) >= HUMAN_SHIFT_END else local_now.date() - timedelta(days=1)
    last_evaluated = str(profile.get("humanShiftLastEvaluatedDate") or "").strip()
    if not last_evaluated:
        # Start attendance tracking with the first observed date; do not backdate
        # absences for shifts that happened before this feature was enabled.
        profile["humanShiftLastEvaluatedDate"] = through.isoformat()
        await asyncio.to_thread(db.collection("users").document(uid).set, {
            "humanShiftLastEvaluatedDate": through.isoformat(),
            "humanShiftTrackingStartedAt": firestore.SERVER_TIMESTAMP,
        }, merge=True)
        return profile
    try:
        first_date = datetime.strptime(last_evaluated[:10], "%Y-%m-%d").date() + timedelta(days=1)
    except ValueError:
        first_date = through
    if first_date > through:
        return profile

    user_ref = db.collection("users").document(uid)
    consecutive = max(0, int(profile.get("humanShiftMissesConsecutive") or 0))
    locked = False
    shift_ref = db.collection(HUMAN_SHIFT_COLLECTION)
    current_date = first_date
    while current_date <= through:
        if current_date.weekday() >= 5:
            # Saturday and Sunday are not scheduled shifts and must not increase
            # consecutive missed-shift counts. Still advance the checkpoint.
            profile["humanShiftLastEvaluatedDate"] = current_date.isoformat()
            current_date += timedelta(days=1)
            continue
        shift_id = _human_shift_doc_id(uid, current_date.isoformat())
        shift_snapshot = await asyncio.to_thread(shift_ref.document(shift_id).get)
        shift = shift_snapshot.to_dict() if shift_snapshot.exists else {}
        attended = bool(shift.get("clockedInAt"))
        if attended:
            consecutive = 0
            status = "attended"
        else:
            consecutive += 1
            status = "missed"
        await asyncio.to_thread(shift_ref.document(shift_id).set, {
            "uid": uid, "shift_date": current_date.isoformat(), "status": status,
            "missed_consecutive_after": consecutive,
            "evaluatedAt": firestore.SERVER_TIMESTAMP,
        }, merge=True)
        profile["humanShiftMissesConsecutive"] = consecutive
        profile["humanShiftLastEvaluatedDate"] = current_date.isoformat()
        profile["humanShiftWarning"] = consecutive >= HUMAN_SHIFT_WARNING_MISSES
        if consecutive >= HUMAN_SHIFT_LOCKOUT_MISSES:
            retraining = _human_worker_retraining_updates(profile, HUMAN_WORKER_DEADLINE_LOCKOUT_RETURNS, local_now)
            if retraining:
                retraining["trainingRedoMessage"] = (
                    "Your work access is paused after six consecutive missed shifts. Please retake the Training Room modules and typing practice. "
                    "Your earlier training and payout history are preserved, and you do not need to pay for training again."
                )
                retraining["humanShiftMissesConsecutive"] = consecutive
                retraining["humanShiftLastEvaluatedDate"] = current_date.isoformat()
                retraining["humanShiftWarning"] = True
                retraining["humanShiftLockoutAt"] = firestore.SERVER_TIMESTAMP
                await asyncio.to_thread(user_ref.set, retraining, merge=True)
                profile.update({key: value for key, value in retraining.items() if key != "updatedAt"})
                await _human_archive_retraining_attempts(uid)
                locked = True
                break
        current_date += timedelta(days=1)
    await asyncio.to_thread(user_ref.set, {
        "humanShiftMissesConsecutive": consecutive,
        "humanShiftLastEvaluatedDate": profile.get("humanShiftLastEvaluatedDate"),
        "humanShiftWarning": consecutive >= HUMAN_SHIFT_WARNING_MISSES,
        "updatedAt": firestore.SERVER_TIMESTAMP,
    }, merge=True)
    return profile


async def _human_shift_current_record(uid, now=None):
    local_now = (now or _human_shift_local_now()).astimezone(HUMAN_SHIFT_TIMEZONE)
    ref = db.collection(HUMAN_SHIFT_COLLECTION).document(_human_shift_doc_id(uid, local_now.date().isoformat()))
    snapshot = await asyncio.to_thread(ref.get)
    return ref, snapshot.to_dict() if snapshot.exists else {}


def _human_shift_status_payload(uid, profile, shift, now=None):
    local_now = (now or _human_shift_local_now()).astimezone(HUMAN_SHIFT_TIMEZONE)
    profile = profile or {}
    shift = shift or {}
    active_call_in = _human_shift_call_in_active(profile, local_now)
    scheduled = _human_shift_is_scheduled(local_now)
    clocked_in = bool(shift.get("clockedInAt") and not shift.get("clockedOutAt"))
    presence = _human_shift_parse_datetime(shift.get("lastPresenceAt"))
    presence_age = (local_now - presence).total_seconds() if presence else None
    workroom_online = bool(presence_age is not None and -5 <= presence_age <= HUMAN_SHIFT_ONLINE_TTL_SECONDS)
    available_for_work = profile.get("is_available") is True
    # The switch is only a presence signal for admins. It never grants shift
    # attendance or permission to claim; a fresh Work Room heartbeat is also
    # required before the worker is shown as online.
    is_online = bool(available_for_work and workroom_online)
    approved = profile.get("workerApproved") is True
    retraining = profile.get("worker_retraining_required") is True
    reclocking_after_call_in = bool(active_call_in and not scheduled)
    reclocking_during_shift = bool(shift.get("clockedOutAt") and scheduled)
    if shift.get("clockedOutAt") and not reclocking_after_call_in and not scheduled:
        status = "clocked_out"
    elif clocked_in:
        status = "online" if is_online else "clocked_in_idle"
    elif active_call_in:
        status = "called_in_not_clocked_in"
    elif scheduled:
        status = "not_arrived"
    elif local_now.weekday() < 5 and local_now.timetz().replace(tzinfo=None) >= HUMAN_SHIFT_END:
        status = "missed"
    else:
        status = "off_shift"
    can_clock_in = approved and not retraining and not clocked_in and (scheduled or active_call_in) and (not shift.get("clockedOutAt") or reclocking_after_call_in or scheduled)
    can_claim = bool(approved and not retraining and clocked_in and (scheduled or active_call_in))
    if retraining:
        message = "Your work access is paused. Please continue in the Training Room."
    elif status == "called_in_not_clocked_in":
        message = "An admin has called you in. Clock in before claiming or starting work."
    elif reclocking_during_shift:
        message = "You have clocked out for now. You can clock in again while today's scheduled shift is open."
    elif status == "not_arrived":
        message = "Your shift is open. Clock in before claiming work. The online toggle does not record attendance."
    elif status == "clocked_out":
        message = "You are clocked out for this shift. If admin calls you in after hours, clock in before claiming work."
    elif status == "missed":
        message = "Today's shift has ended. Contact an admin if you need to be called in; otherwise clock in during the next weekday shift."
    elif status == "off_shift":
        message = "There are no regular weekend shifts. Work outside scheduled hours requires an admin call-in and clock-in."
    elif clocked_in and not scheduled and not active_call_in:
        message = "Your regular shift has ended. Clock out when no assignment is active; an admin call-in is required before taking new overtime work."
    elif clocked_in and not available_for_work:
        message = "You are clocked in and can claim work allowed by your current shift or admin call-in. Your online toggle is off, so admins see you as offline."
    elif clocked_in and not scheduled:
        message = "You are clocked in for an admin call-in. Finish assigned work before clocking out."
    elif clocked_in:
        message = "You are clocked in and can claim available work. Finish assigned work before clocking out."
    elif is_online:
        message = "You are marked online to admins. This does not count as attendance; clock in during a shift or after an admin call-in before claiming work."
    elif available_for_work:
        message = "Your online toggle is on. Keep this Work Room open so admins can see you online. It does not count as attendance or permit claims by itself."
    else:
        message = "Your online toggle is off. Clock in during a scheduled shift or after an admin call-in before claiming work."
    return {
        "uid": uid, "date": local_now.date().isoformat(), "status": status,
        "shift_start": "15:00", "shift_end": "20:00", "timezone": "Africa/Nairobi",
        "scheduled_now": scheduled, "call_in_active": active_call_in,
        "clocked_in": clocked_in, "online": is_online, "workroom_online": workroom_online,
        "available_for_work": available_for_work,
        # Kept false for old clients during their cache lifetime. Availability
        # no longer enables off-shift self-claiming.
        "off_shift_claim_enabled": False, "off_shift_self_claim": False,
        "availability_required": False,
        "clocked_in_at": shift.get("clockedInAt") or "", "clocked_out_at": shift.get("clockedOutAt") or "",
        "last_presence_at": shift.get("lastPresenceAt") or "",
        "can_clock_in": can_clock_in, "can_claim": can_claim,
        "misses_consecutive": max(0, int(profile.get("humanShiftMissesConsecutive") or 0)),
        "warning": bool(profile.get("humanShiftWarning")),
        "message": message,
    }


async def _human_shift_assert_can_claim(actor):
    profile = await _human_shift_reconcile(actor["uid"], actor.get("profile") or {})
    if profile.get("workerApproved") is not True or profile.get("worker_retraining_required") is True:
        raise HTTPException(status_code=403, detail="Your work access is paused. Please continue in the Training Room.")
    _, shift = await _human_shift_current_record(actor["uid"])
    payload = _human_shift_status_payload(actor["uid"], profile, shift)
    if not payload["can_claim"]:
        raise HTTPException(status_code=403, detail=payload["message"])
    actor["profile"] = profile
    return payload


async def _human_shift_assert_can_start_assigned(actor, allow_after_hours_self_claim=False):
    """Let authorized workers complete assigned work after regular shift hours."""
    profile = await _human_shift_reconcile(actor["uid"], actor.get("profile") or {})
    if profile.get("workerApproved") is not True or profile.get("worker_retraining_required") is True:
        raise HTTPException(status_code=403, detail="Your work access is paused. Please continue in the Training Room.")
    _, shift = await _human_shift_current_record(actor["uid"])
    if not shift.get("clockedInAt") or shift.get("clockedOutAt"):
        if not allow_after_hours_self_claim:
            raise HTTPException(
                status_code=403,
                detail="Clock in before starting assigned work. If an admin called you in, complete the work before clocking out."
            )
        actor["profile"] = profile
        return _human_shift_status_payload(actor["uid"], profile, shift)
    actor["profile"] = profile
    return _human_shift_status_payload(actor["uid"], profile, shift)


async def _human_require_worker_online_for_overtime(worker_uid, profile=None, now=None):
    """Outside weekday shift hours, require an active call-in, clock-in, and online signal."""
    now = (now or _human_shift_local_now()).astimezone(HUMAN_SHIFT_TIMEZONE)
    profile = profile or await _load_profile(worker_uid) or {}
    if profile.get("workerApproved") is not True:
        raise HTTPException(status_code=403, detail="Approved worker access is required.")
    if _human_shift_is_scheduled(now):
        return True
    _, shift = await _human_shift_current_record(worker_uid, now)
    status = _human_shift_status_payload(worker_uid, profile, shift, now)
    if not status.get("call_in_active") or not status.get("clocked_in") or not status.get("online"):
        raise HTTPException(
            status_code=409,
            detail="Outside regular shift hours, call the worker in, have them clock in, and confirm Available for work is on before assigning overtime.",
        )
    return True


@app.get("/human-transcription/worker/shift")
async def human_worker_shift_status(request: Request):
    actor = await _human_actor(request)
    if actor["role"] != "worker":
        raise HTTPException(status_code=403, detail="Approved worker access is required to view shift status.")
    profile = await _human_shift_reconcile(actor["uid"], actor.get("profile") or {})
    _, shift = await _human_shift_current_record(actor["uid"])
    result = _human_shift_status_payload(actor["uid"], profile, shift)
    result["has_active_assignment"] = await _human_worker_has_active_assignment(actor["uid"])
    return result


@app.post("/human-transcription/worker/shift/clock-in")
async def human_worker_shift_clock_in(request: Request):
    actor = await _human_actor(request)
    if actor["role"] != "worker":
        raise HTTPException(status_code=403, detail="Approved worker access is required to clock in.")
    profile = await _human_shift_reconcile(actor["uid"], actor.get("profile") or {})
    if profile.get("workerApproved") is not True or profile.get("worker_retraining_required") is True:
        raise HTTPException(status_code=403, detail="Your work access is paused. Please continue in the Training Room.")
    local_now = _human_shift_local_now()
    active_call_in = _human_shift_call_in_active(profile, local_now)
    if not _human_shift_is_scheduled(local_now) and not active_call_in:
        raise HTTPException(status_code=403, detail="You can clock in outside regular shift hours only after an admin calls you in.")
    ref, shift = await _human_shift_current_record(actor["uid"], local_now)
    if not shift.get("clockedInAt") or shift.get("clockedOutAt"):
        updates = {
            "uid": actor["uid"], "email": actor.get("email") or "",
            "shift_date": local_now.date().isoformat(), "status": "clocked_in",
            "clockedInAt": local_now.isoformat(), "lastPresenceAt": local_now.isoformat(),
            "call_in": active_call_in, "missed_consecutive_after": None,
        }
        if shift.get("clockedOutAt"):
            # A worker may be called back after clocking out. Preserve this
            # finished session and reopen the daily record only after they
            # explicitly press Clock in following an active admin call-in.
            sessions = list(shift.get("sessions") or [])
            prior_session = {
                "clockedInAt": shift.get("clockedInAt"),
                "clockedOutAt": shift.get("clockedOutAt"),
                "call_in": bool(shift.get("call_in")),
            }
            if not any(
                item.get("clockedInAt") == prior_session["clockedInAt"]
                and item.get("clockedOutAt") == prior_session["clockedOutAt"]
                for item in sessions if isinstance(item, dict)
            ):
                sessions.append(prior_session)
            updates["sessions"] = sessions[-20:]
            updates["clockedOutAt"] = firestore.DELETE_FIELD
        await asyncio.to_thread(ref.set, updates, merge=True)
        shift.update({"clockedInAt": local_now.isoformat(), "lastPresenceAt": local_now.isoformat(), "status": "clocked_in", "call_in": active_call_in})
        shift.pop("clockedOutAt", None)
    return _human_shift_status_payload(actor["uid"], profile, shift, local_now)


@app.post("/human-transcription/worker/shift/presence")
async def human_worker_shift_presence(request: Request):
    actor = await _human_actor(request)
    if actor["role"] != "worker":
        raise HTTPException(status_code=403, detail="Approved worker access is required.")
    now = _human_shift_local_now()
    profile = await _human_shift_reconcile(actor["uid"], actor.get("profile") or {}, now)
    if profile.get("workerApproved") is not True or profile.get("worker_retraining_required") is True:
        raise HTTPException(status_code=403, detail="Your work access is paused. Please continue in the Training Room.")
    ref, shift = await _human_shift_current_record(actor["uid"], now)
    clocked_in = bool(shift.get("clockedInAt") and not shift.get("clockedOutAt"))
    online_toggle = profile.get("is_available") is True
    if not clocked_in and not online_toggle:
        raise HTTPException(status_code=409, detail="Turn on Available for work to show admins that you are online. This does not clock you in.")
    updates = {"lastPresenceAt": now.isoformat()}
    # A heartbeat is presence only; it never creates or changes attendance.
    updates["status"] = "clocked_in" if clocked_in else "online"
    await asyncio.to_thread(ref.set, updates, merge=True)
    shift.update(updates)
    return _human_shift_status_payload(actor["uid"], profile, shift, now)


@app.post("/human-transcription/worker/shift/clock-out")
async def human_worker_shift_clock_out(request: Request):
    actor = await _human_actor(request)
    if actor["role"] != "worker":
        raise HTTPException(status_code=403, detail="Approved worker access is required to clock out.")
    ref, shift = await _human_shift_current_record(actor["uid"])
    if not shift.get("clockedInAt") or shift.get("clockedOutAt"):
        raise HTTPException(status_code=409, detail="You are not clocked in for the current shift.")
    if await _human_worker_has_active_assignment(actor["uid"]):
        raise HTTPException(status_code=409, detail="Finish your active job before clocking out.")
    now = _human_shift_local_now()
    sessions = list(shift.get("sessions") or [])
    if shift.get("clockedInAt"):
        sessions.append({
            "clockedInAt": shift.get("clockedInAt"), "clockedOutAt": now.isoformat(),
            "call_in": bool(shift.get("call_in")),
        })
    await asyncio.to_thread(ref.set, {
        "status": "clocked_out", "clockedOutAt": now.isoformat(), "sessions": sessions[-20:],
    }, merge=True)
    shift.update({"status": "clocked_out", "clockedOutAt": now.isoformat(), "sessions": sessions[-20:]})
    profile = await _human_shift_reconcile(actor["uid"], actor.get("profile") or {}, now)
    return _human_shift_status_payload(actor["uid"], profile, shift, now)


@app.get("/human-transcription/admin/shifts")
async def human_admin_shift_attendance(request: Request):
    _require_human_shift_admin(request)
    snapshots = await asyncio.to_thread(lambda: list(db.collection("users").where(filter=FieldFilter("workerApproved", "==", True)).stream()))
    retraining_snapshots = await asyncio.to_thread(lambda: list(db.collection("users").where(filter=FieldFilter("worker_retraining_required", "==", True)).stream()))
    profiles_by_uid = {snapshot.id: snapshot.to_dict() or {} for snapshot in snapshots}
    for snapshot in retraining_snapshots:
        profile = snapshot.to_dict() or {}
        if profile.get("humanShiftLockoutAt"):
            profiles_by_uid.setdefault(snapshot.id, profile)
    now = _human_shift_local_now()
    workers = []
    for uid, profile in profiles_by_uid.items():
        if profile.get("workerApproved") is True:
            profile = await _human_shift_reconcile(uid, profile, now)
        profile = await _admin_fill_identity(uid, profile)
        _, shift = await _human_shift_current_record(uid, now)
        row = _human_shift_status_payload(uid, profile, shift, now)
        if profile.get("workerApproved") is not True:
            row.update({"status": "retraining", "online": False, "can_clock_in": False, "can_claim": False, "message": "This worker has returned to the Training Room for shift retraining."})
        row.update({
            "name": profile.get("name") or profile.get("displayName") or profile.get("email") or "Worker",
            "email": profile.get("email") or "", "rating": profile.get("workerRating"),
            "call_in_expires_at": profile.get("humanShiftCallInExpiresAt") or "",
        })
        workers.append(row)
    order = {"online": 0, "clocked_in_idle": 1, "called_in_not_clocked_in": 2, "not_arrived": 3, "missed": 4, "clocked_out": 5, "off_shift": 6}
    workers.sort(key=lambda item: (0 if item.get("online") else 1, order.get(item["status"], 9), item["name"].lower()))
    return {
        "workers": workers, "date": now.date().isoformat(), "timezone": "Africa/Nairobi",
        "shift_start": "15:00", "shift_end": "20:00", "working_days": ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"],
        "scheduled_now": _human_shift_is_scheduled(now), "warning_after_misses": HUMAN_SHIFT_WARNING_MISSES,
        "retraining_after_misses": HUMAN_SHIFT_LOCKOUT_MISSES,
    }


@app.post("/human-transcription/admin/workers/{uid}/shift-call-in")
async def human_admin_shift_call_in(uid: str, request: Request):
    _require_human_shift_admin(request)
    profile = await _load_profile(uid)
    if not profile or profile.get("workerApproved") is not True:
        raise HTTPException(status_code=404, detail="That approved worker was not found.")
    payload = await request.json()
    reason = str((payload or {}).get("reason") or "Admin call-in").strip()[:500]
    now = _human_shift_local_now()
    expires = now + timedelta(hours=HUMAN_SHIFT_CALL_TTL_HOURS)
    await asyncio.to_thread(db.collection("users").document(uid).set, {
        "humanShiftCallInAt": now.isoformat(), "humanShiftCallInExpiresAt": expires.isoformat(),
        "humanShiftCallInBy": (await _human_actor(request)).get("email") or "admin",
        "humanShiftCallInReason": reason, "updatedAt": firestore.SERVER_TIMESTAMP,
    }, merge=True)
    await _create_user_notification(
        uid, f"human-shift-callin:{now.date().isoformat()}:{uuid.uuid4().hex[:10]}", "shift_call_in",
        "Admin called you in", "Clock in to claim work. This call-in is available for four hours.",
        route="human_worker",
    )
    return {"status": "called_in", "uid": uid, "expires_at": expires.isoformat(), "reason": reason}


async def _human_reclaim_expired_job(job_id: str, job: dict, split_expected=None):
    """Return expired work once, count each worker deadline event once, and apply lockout at 11."""
    if not db or not job:
        return job
    now = datetime.now()
    job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
    transaction = db.transaction()

    @firestore.transactional
    def reclaim(tx):
        snapshot = job_ref.get(transaction=tx)
        if not snapshot.exists:
            return {"changed": False, "job": job, "events": [], "locked_workers": []}
        current = snapshot.to_dict() or {}
        is_split = _human_is_split_job(current)
        if split_expected is not None and bool(split_expected) != is_split:
            current["id"] = job_id
            return {"changed": False, "job": current, "events": [], "locked_workers": []}

        expired = []
        if is_split:
            segments = [dict(item or {}) for item in (current.get("segments") or [])]
            for part in segments:
                if part.get("status") not in {"assigned", "in_progress"}:
                    continue
                deadline = _as_dt(part.get("deadlineAt"))
                if deadline and now > deadline:
                    expired.append({
                        "worker_uid": str(part.get("worker_uid") or ""), "role": "transcriber",
                        "item_id": str(part.get("id") or ""), "label": str(part.get("label") or "job part"),
                        "assignment_token": _human_deadline_assignment_token(part),
                    })
            proofreader_status = current.get("proofreader_status")
            proofreader_deadline = _as_dt(current.get("proofreader_deadlineAt"))
            if proofreader_status in {"assigned", "in_progress"} and proofreader_deadline and now > proofreader_deadline:
                expired.append({
                    "worker_uid": str(current.get("proofreader_uid") or ""), "role": "proofreader",
                    "item_id": "proofreader", "label": "proofreading",
                    "assignment_token": _human_deadline_assignment_token({"assignedAt": current.get("proofreader_assignedAt"), "deadlineAt": current.get("proofreader_deadlineAt")}),
                })
        else:
            if current.get("status") not in {"assigned", "in_progress"}:
                current["id"] = job_id
                return {"changed": False, "job": current, "events": [], "locked_workers": []}
            deadline = _as_dt(current.get("deadlineAt"))
            if not deadline or now <= deadline:
                current["id"] = job_id
                return {"changed": False, "job": current, "events": [], "locked_workers": []}
            expired.append({
                "worker_uid": str(current.get("worker_uid") or ""), "role": "transcriber",
                "item_id": "main", "label": "the complete job",
                "assignment_token": _human_deadline_assignment_token(current),
            })
        if not expired:
            current["id"] = job_id
            return {"changed": False, "job": current, "events": [], "locked_workers": []}

        worker_uids = list(dict.fromkeys(entry["worker_uid"] for entry in expired if entry.get("worker_uid")))
        user_refs = {uid: db.collection("users").document(uid) for uid in worker_uids}
        user_snapshots = {uid: user_refs[uid].get(transaction=tx) for uid in worker_uids}
        profiles = {uid: (user_snapshots[uid].to_dict() if user_snapshots[uid].exists else {}) for uid in worker_uids}
        event_rows = []
        for entry in expired:
            profile = profiles.get(entry.get("worker_uid"), {})
            cycle = str(profile.get("worker_qualification_cycle") or "initial")
            event_id = _human_deadline_event_id(job_id, entry["role"], entry["item_id"], entry["assignment_token"], cycle)
            event_ref = db.collection(HUMAN_WORKER_DEADLINE_EVENT_COLLECTION).document(event_id)
            event_snapshot = event_ref.get(transaction=tx)
            event_rows.append((entry, cycle, event_id, event_ref, event_snapshot.exists))

        new_events = []
        worker_increments = {}
        for entry, cycle, event_id, event_ref, exists in event_rows:
            if exists:
                continue
            event_data = {
                "job_id": job_id, "worker_uid": entry.get("worker_uid") or "", "role": entry["role"],
                "item_id": entry["item_id"], "label": entry["label"],
                "assignment_token": entry["assignment_token"], "qualification_cycle": cycle,
                "createdAt": now,
            }
            new_events.append((entry, event_ref, event_data, event_id))
            if entry.get("worker_uid"):
                worker_increments[entry["worker_uid"]] = worker_increments.get(entry["worker_uid"], 0) + 1

        if is_split:
            segments = [dict(item or {}) for item in (current.get("segments") or [])]
            expired_lookup = {(entry["role"], entry["item_id"], entry["assignment_token"]) for entry in expired}
            for part in segments:
                token = _human_deadline_assignment_token(part)
                if ("transcriber", str(part.get("id") or ""), token) not in expired_lookup:
                    continue
                previous = part.get("worker_name") or part.get("worker_email") or "the previous worker"
                part.update({
                    "status": "available", "worker_uid": None, "worker_email": None, "worker_name": None,
                    "assignedAt": None, "deadlineAt": None, "tat_seconds": None,
                    "auto_reassigned_count": int(part.get("auto_reassigned_count") or 0) + 1,
                    "last_auto_reassigned_at": now, "last_auto_reassigned_worker_name": previous,
                })
            proofreader_expired = any(entry["role"] == "proofreader" for entry in expired)
            current.update({
                "segments": segments,
                "assigned_worker_uids": list(dict.fromkeys(
                    [str(part.get("worker_uid")) for part in segments if part.get("worker_uid")]
                    + ([str(current.get("proofreader_uid"))] if current.get("proofreader_status") in {"assigned", "in_progress"} and current.get("proofreader_uid") and not proofreader_expired else [])
                )),
            })
            if proofreader_expired:
                current.update({
                    "proofreader_status": "available", "proofreader_uid": None, "proofreader_email": None,
                    "proofreader_name": None, "proofreader_deadlineAt": None, "proofreader_tat_seconds": None,
                })
            if current.get("proofreader_status") in {"assigned", "in_progress"}:
                current["status"] = "proofreading_assigned"
            elif all(part.get("status") == "submitted" for part in segments):
                current["status"] = "proofreading_available"
            else:
                current["status"] = "split_assigned"
            updates = {
                "segments": segments, "assigned_worker_uids": current["assigned_worker_uids"],
                "status": current["status"], "updatedAt": firestore.SERVER_TIMESTAMP,
            }
            if proofreader_expired:
                updates.update({key: current.get(key) for key in (
                    "proofreader_status", "proofreader_uid", "proofreader_email", "proofreader_name",
                    "proofreader_deadlineAt", "proofreader_tat_seconds",
                )})
        else:
            previous = current.get("worker_name") or current.get("worker_email") or "the previous worker"
            current.update({
                "status": "approved", "worker_uid": None, "worker_email": None, "worker_name": None,
                "assignedAt": None, "deadlineAt": None, "tat_seconds": None,
                "auto_reassigned_count": int(current.get("auto_reassigned_count") or 0) + 1,
                "last_auto_reassigned_at": now, "last_auto_reassigned_worker_name": previous,
            })
            updates = {key: current.get(key) for key in (
                "status", "worker_uid", "worker_email", "worker_name", "assignedAt", "deadlineAt", "tat_seconds",
                "auto_reassigned_count", "last_auto_reassigned_at", "last_auto_reassigned_worker_name",
            )}
            updates["updatedAt"] = firestore.SERVER_TIMESTAMP

        tx.update(job_ref, updates)
        locked_workers = []
        for uid, increment in worker_increments.items():
            profile = profiles.get(uid) or {}
            next_count = max(0, int(profile.get("deadline_return_count") or 0)) + increment
            profile_updates = {"deadline_return_count": next_count, "updatedAt": firestore.SERVER_TIMESTAMP}
            lockout = _human_worker_retraining_updates(profile, next_count, now)
            if lockout:
                profile_updates.update(lockout)
                locked_workers.append(uid)
            tx.set(user_refs[uid], profile_updates, merge=True)
        for _entry, event_ref, event_data, _event_id in new_events:
            tx.set(event_ref, event_data)

        current["id"] = job_id
        public_events = [
            {**event_data, "event_id": event_id}
            for _entry, _event_ref, event_data, event_id in new_events
        ]
        return {"changed": True, "job": current, "events": public_events, "locked_workers": locked_workers}

    try:
        result = await asyncio.to_thread(reclaim, transaction)
    except Exception as exc:
        logger.warning("Could not transactionally return expired Human Work %s: %s", job_id, exc)
        return job
    for uid in result.get("locked_workers") or []:
        await _human_archive_retraining_attempts(uid)
    for event in result.get("events") or []:
        worker_uid = str(event.get("worker_uid") or "")
        role = str(event.get("role") or "transcriber")
        item_id = str(event.get("item_id") or "")
        assignment_token = str(event.get("assignment_token") or "")
        label = str(event.get("label") or "job part")
        if worker_uid:
            claim_role = "proofreader" if role == "proofreader" else "transcriber"
            claim_segment = "proofreader" if role == "proofreader" else ("" if item_id == "main" else item_id)
            await _human_release_worker_claim(worker_uid, job_id, claim_segment, claim_role)
            await _update_user_notification_states(worker_uid, job_id=job_id, kinds={"assignment"}, read=True, completed=True)
            notification_role = "main" if item_id == "main" else role
            await _create_user_notification(
                worker_uid, f"human-expired:{job_id}:{notification_role}:{item_id}:{assignment_token}", "assignment_taken_back",
                "A Human Work deadline passed", f"Your {label} returned to the queue after its deadline.",
                route="human_worker", job_id=job_id, target_id=job_id,
            )
        await _notify_human_admins(
            f"human-returned-to-queue:{job_id}:{role}:{item_id}:{assignment_token}", "returned_to_queue",
            "Human Work returned to the queue", f"A {label} deadline passed. Review and reassign this step.",
            route="human_ops", job_id=job_id, requires_action=True, target_id=item_id,
        )
    return result.get("job") or job


def _human_is_split_job(job):
    job = job or {}
    return str(job.get("split_mode") or "").strip().lower() in {"dual", "multi"} and bool(job.get("segments"))


def _human_whole_job_ai_takeover_allowed(job):
    job = job or {}
    segments = [item or {} for item in (job.get("segments") or [])]
    return bool(
        _human_is_split_job(job)
        and not job.get("worker_uid")
        and not job.get("proofreader_uid")
        and not list(job.get("assigned_worker_uids") or [])
        and job.get("proofreader_status") not in {"assigned", "in_progress", "submitted"}
        and segments
        and all(not item.get("worker_uid") and item.get("status") in {"available", "approved"} for item in segments)
    )


def _human_split_parent_status(job, segments=None):
    """Parent status for a split job, aware of an early proofreader.

    A proofreader may start on the submitted parts while other parts are still
    being transcribed, so the parent status must not fall back to a
    transcription status while that proofreading assignment is live.
    """
    job = job or {}
    segments = list(segments if segments is not None else (job.get("segments") or []))
    proofreader_status = job.get("proofreader_status")
    if proofreader_status == "in_progress":
        return "proofreading_in_progress"
    if proofreader_status == "assigned":
        return "proofreading_assigned"
    if proofreader_status == "submitted":
        return job.get("status") or "submitted"
    if segments and all((item or {}).get("status") == "submitted" for item in segments):
        return "proofreading_available"
    if any((item or {}).get("status") == "in_progress" for item in segments):
        return "split_in_progress"
    return "split_assigned"


def _human_ai_draft_finish_eligible(job):
    """Only finish a complete internal AI draft when no human proofreader owns it."""
    job = job or {}
    if job.get("admin_uploaded") is not True or job.get("ai_agent_status") != "submitted":
        return False
    if job.get("reviewer_choice") == "human" or job.get("proofreader_status") in {"assigned", "in_progress", "submitted"}:
        return False
    if job.get("status") not in {"submitted", "proofreading_available"}:
        return False
    segments = [item or {} for item in (job.get("segments") or [])]
    if segments:
        return all(
            item.get("status") == "submitted" and str(item.get("transcript") or "").strip()
            for item in segments
        )
    return bool(job.get("pdf_review") and str(job.get("transcript") or "").strip())


def _human_admin_finish_job_eligible(job):
    """Allow an admin to finish only complete submitted work, never live assignments."""
    job = job or {}
    if job.get("status") not in {"submitted", "proofreading_available"}:
        return False
    if job.get("proofreader_status") in {"assigned", "in_progress"}:
        return False
    if job.get("reviewer_status") in {"queued", "processing"}:
        return False
    if job.get("letter_ai_review_status") in {"queued", "processing"}:
        return False
    segments = [dict(item or {}) for item in (job.get("segments") or [])]
    if segments:
        return all(
            item.get("status") == "submitted"
            and bool(str(item.get("transcript") or item.get("transcript_html") or "").strip()
                     or (item.get("final_attachment") or {}).get("storage_path"))
            for item in segments
        )
    return bool(
        str(job.get("transcript") or job.get("transcript_html") or "").strip()
        or (job.get("final_attachment") or {}).get("storage_path")
    )


def _human_claim_is_active(job, worker_uid, claim):
    if not job or not claim:
        return False
    active = {"assigned", "in_progress"}
    if claim.get("role") == "proofreader":
        return job.get("proofreader_uid") == worker_uid and job.get("proofreader_status") in active
    segment_id = str(claim.get("segment_id") or "")
    if segment_id:
        part = next((item for item in (job.get("segments") or []) if str(item.get("id") or "") == segment_id), None)
        return bool(part and part.get("worker_uid") == worker_uid and part.get("status") in active)
    return job.get("worker_uid") == worker_uid and job.get("status") in active


def _human_job_worker_uids(job):
    job = job or {}
    worker_uids = {str(uid) for uid in (job.get("assigned_worker_uids") or []) if uid}
    for key in ("worker_uid", "proofreader_uid"):
        if job.get(key):
            worker_uids.add(str(job[key]))
    worker_uids.update(
        str((item or {}).get("worker_uid"))
        for item in (job.get("segments") or [])
        if (item or {}).get("worker_uid")
    )
    return worker_uids


def _human_worker_rating_for_job(job, worker_uid):
    job = job or {}
    worker_uid = str(worker_uid or "")
    ratings_by_worker = job.get("worker_ratings") or {}
    if worker_uid in ratings_by_worker:
        raw_rating = ratings_by_worker.get(worker_uid)
    elif worker_uid in _human_job_worker_uids(job):
        raw_rating = job.get("worker_rating")
    else:
        return None
    try:
        rating = float(raw_rating)
    except (TypeError, ValueError):
        return None
    return rating if math.isfinite(rating) and 1 <= rating <= 5 else None


def _human_worker_rating_summary_from_jobs(jobs, worker_uid):
    ratings = [
        rating for job in (jobs or [])
        if (rating := _human_worker_rating_for_job(job, worker_uid)) is not None
    ]
    return {
        "average": round(sum(ratings) / len(ratings), 2) if ratings else None,
        "count": len(ratings),
    }


async def _human_worker_job_snapshots(worker_uid, include_legacy_segments=False):
    if not db or not worker_uid:
        return []
    ref = db.collection(HUMAN_JOB_COLLECTION)
    found = {}
    for field, operator in (("worker_uid", "=="), ("assigned_worker_uids", "array_contains"), ("proofreader_uid", "==")):
        snapshots = await asyncio.to_thread(lambda field=field, operator=operator: list(ref.where(filter=FieldFilter(field, operator, worker_uid)).stream()))
        found.update({snapshot.id: snapshot for snapshot in snapshots})
    if include_legacy_segments:
        # Older split records may identify a claimant only inside segments[].
        # Backfill that history once into the worker profile; new assignments
        # already maintain assigned_worker_uids for indexed lookups.
        snapshots = await asyncio.to_thread(lambda: list(ref.stream()))
        for snapshot in snapshots:
            job = snapshot.to_dict() or {}
            if any(str((item or {}).get("worker_uid") or "") == str(worker_uid) for item in (job.get("segments") or [])):
                found[snapshot.id] = snapshot
    return list(found.values())


async def _human_worker_rating_summary(worker_uid, profile=None, force_refresh=False):
    profile = profile or {}
    if not force_refresh and "worker_rating_count" in profile:
        try:
            count = max(0, int(profile.get("worker_rating_count") or 0))
            average = float(profile.get("worker_rating_average")) if count else None
            if average is not None and not math.isfinite(average):
                average = None
            return {"average": round(average, 2) if average is not None else None, "count": count}
        except (TypeError, ValueError):
            pass
    snapshots = await _human_worker_job_snapshots(worker_uid, include_legacy_segments=True)
    summary = _human_worker_rating_summary_from_jobs(
        [(snapshot.to_dict() or {}) for snapshot in snapshots], worker_uid,
    )
    if db and worker_uid:
        await asyncio.to_thread(
            db.collection("users").document(str(worker_uid)).set,
            {"worker_rating_average": summary["average"], "worker_rating_count": summary["count"]},
            merge=True,
        )
    return summary


async def _human_worker_has_active_assignment(worker_uid):
    for snapshot in await _human_worker_job_snapshots(worker_uid):
        job = snapshot.to_dict() or {}
        job["id"] = snapshot.id
        job = await _human_check_expiry(snapshot.id, job)
        if _human_claim_is_active(job, worker_uid, {"role": "transcriber"}):
            return True
        if any(
            item.get("worker_uid") == worker_uid and item.get("status") in {"assigned", "in_progress"}
            for item in (job.get("segments") or [])
        ):
            return True
        if _human_claim_is_active(job, worker_uid, {"role": "proofreader"}):
            return True
    return False


async def _human_release_worker_claim(worker_uid, job_id, segment_id="", role="transcriber"):
    if not db or not worker_uid:
        return
    claim_ref = db.collection(HUMAN_WORKER_CLAIM_COLLECTION).document(str(worker_uid))
    transaction = db.transaction()

    @firestore.transactional
    def release_if_current(tx):
        snapshot = claim_ref.get(transaction=tx)
        current = snapshot.to_dict() if snapshot.exists else {}
        if (
            current.get("status") == "active"
            and current.get("job_id") == job_id
            and str(current.get("segment_id") or "") == str(segment_id or "")
            and current.get("role") == role
        ):
            tx.set(claim_ref, {"status": "released", "releasedAt": datetime.now(), "updatedAt": firestore.SERVER_TIMESTAMP}, merge=True)
            return True
        return False

    await asyncio.to_thread(release_if_current, transaction)


def _human_claim_item_key(job_id, segment_id=""):
    return f"{str(job_id or '').strip()}|{str(segment_id or '').strip() or 'whole'}"


def _human_claim_attempt_document_id(worker_uid, qualification_cycle, item_key):
    value = "|".join((str(worker_uid or ""), str(qualification_cycle or "initial"), str(item_key or "")))
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _human_claim_assignment_transaction(
    job_id, actor, segment_id="", allow_supervised_starter=False,
    require_availability=False, after_hours_self_claim=False,
):
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    worker_uid = str(actor.get("uid") or "")
    job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
    claim_ref = db.collection(HUMAN_WORKER_CLAIM_COLLECTION).document(worker_uid)
    worker_ref = db.collection("users").document(worker_uid)
    transaction = db.transaction()

    @firestore.transactional
    def claim(tx):
        job_snapshot = job_ref.get(transaction=tx)
        if not job_snapshot.exists:
            raise HTTPException(status_code=404, detail="This job is no longer available.")
        job = job_snapshot.to_dict() or {}
        job_type = str(job.get("job_type") or "").strip().lower()
        if job_type == "letter_job":
            raise HTTPException(status_code=403, detail="Letter Jobs are assigned by an admin as one complete job.")
        if job_type == "pdf_job" and job.get("admin_uploaded") is not True:
            raise HTTPException(status_code=403, detail="This PDF job is assigned by an admin.")
        if not allow_supervised_starter and _human_routing_blocks_workers(job):
            raise HTTPException(status_code=409, detail="This job has not been released to workers yet.")
        worker_snapshot = worker_ref.get(transaction=tx)
        worker_profile = worker_snapshot.to_dict() if worker_snapshot.exists else {}
        if worker_profile.get("workerApproved") is not True:
            raise HTTPException(status_code=403, detail="Approved worker access is required.")
        claim_now = _human_shift_local_now()
        shift_ref = db.collection(HUMAN_SHIFT_COLLECTION).document(
            _human_shift_doc_id(worker_uid, claim_now.date().isoformat())
        )
        shift_snapshot = shift_ref.get(transaction=tx)
        shift_record = shift_snapshot.to_dict() if shift_snapshot.exists else {}
        claim_status = _human_shift_status_payload(worker_uid, worker_profile, shift_record, claim_now)
        if not claim_status.get("can_claim"):
            raise HTTPException(status_code=403, detail=claim_status.get("message") or "Clock in during your scheduled shift or after an admin call-in before claiming work.")
        if not allow_supervised_starter:
            try:
                rating_count = int(worker_profile.get("worker_rating_count") or 0)
                rating_average = float(worker_profile.get("worker_rating_average")) if rating_count else None
            except (TypeError, ValueError):
                rating_count, rating_average = 0, None
            if rating_average is None or rating_average < MIN_HUMAN_WORKER_RATING:
                raise HTTPException(status_code=403, detail="A worker rating of 3.5/5 or higher is required to claim Available Jobs. Contact an admin about a supervised starter assignment.")
        claim_snapshot = claim_ref.get(transaction=tx)
        current_claim = claim_snapshot.to_dict() if claim_snapshot.exists else {}
        if current_claim.get("status") == "active":
            old_job_id = str(current_claim.get("job_id") or "")
            old_ref = db.collection(HUMAN_JOB_COLLECTION).document(old_job_id) if old_job_id else None
            old_snapshot = old_ref.get(transaction=tx) if old_ref else None
            old_job = old_snapshot.to_dict() if old_snapshot and old_snapshot.exists else None
            if _human_claim_is_active(old_job, worker_uid, current_claim):
                raise HTTPException(status_code=409, detail="Finish your current slice before claiming another.")

        now = datetime.now()
        if _human_is_split_job(job):
            if not segment_id:
                raise HTTPException(status_code=400, detail="Choose an available audio part to claim.")
            segments = [dict(item or {}) for item in (job.get("segments") or [])]
            target = next((item for item in segments if str(item.get("id") or "") == segment_id), None)
            if not target or target.get("status") not in {"available", "approved"}:
                raise HTTPException(status_code=409, detail="Another worker has already claimed that part.")
            if any(item.get("worker_uid") == worker_uid and item.get("status") in {"assigned", "in_progress"} for item in segments):
                raise HTTPException(status_code=409, detail="Finish your current part of this job before claiming another.")
            cycle_id = worker_profile.get("worker_qualification_cycle") or "initial"
            item_key = _human_claim_item_key(job_id, segment_id)
            attempt_ref = db.collection(HUMAN_WORKER_ITEM_CLAIM_COLLECTION).document(
                _human_claim_attempt_document_id(worker_uid, cycle_id, item_key)
            )
            attempt_snapshot = attempt_ref.get(transaction=tx)
            attempt_data = attempt_snapshot.to_dict() if attempt_snapshot.exists else {}
            claim_count = int(attempt_data.get("claim_count") or 0)
            if claim_count >= HUMAN_WORKER_MAX_CLAIMS_PER_ITEM:
                raise HTTPException(status_code=409, detail="You have already claimed this job part once. It cannot be claimed again. Choose another available part.")
            seconds = max(0.0, float(target.get("end_seconds") or 0) - float(target.get("start_seconds") or 0))
            tat_seconds = human_tat_seconds(seconds)
            deadline = now + timedelta(seconds=tat_seconds)
            target.update({
                "worker_uid": worker_uid,
                "worker_email": str(actor.get("email") or "").strip().lower(),
                "worker_name": str((actor.get("profile") or {}).get("name") or (actor.get("profile") or {}).get("displayName") or "").strip(),
                "status": "assigned",
                "assignedAt": now,
                "deadlineAt": deadline,
                "tat_seconds": tat_seconds,
                "after_hours_self_claim": bool(after_hours_self_claim),
            })
            updates = {
                "segments": segments,
                "after_hours_self_claim": bool(after_hours_self_claim),
                "assigned_worker_uids": list(dict.fromkeys(
                    [item.get("worker_uid") for item in segments if item.get("worker_uid")]
                    + ([job.get("proofreader_uid")] if job.get("proofreader_status") in {"assigned", "in_progress"} and job.get("proofreader_uid") else [])
                )),
                "status": _human_split_parent_status(job, segments),
                "updatedAt": firestore.SERVER_TIMESTAMP,
            }
            tx.update(job_ref, updates)
            tx.set(attempt_ref, {
                "worker_uid": worker_uid, "qualification_cycle": str(cycle_id), "item_key": item_key,
                "job_id": job_id, "segment_id": segment_id, "claim_count": claim_count + 1,
                "updatedAt": firestore.SERVER_TIMESTAMP,
            }, merge=True)
            tx.set(claim_ref, {"worker_uid": worker_uid, "job_id": job_id, "segment_id": segment_id, "role": "transcriber", "status": "active", "assignedAt": now, "deadlineAt": deadline, "updatedAt": firestore.SERVER_TIMESTAMP}, merge=True)
            return {"job_id": job_id, "segment_id": segment_id, "claim_count": claim_count + 1, "label": target.get("label") or "your assigned part", "status": "assigned", "tat_seconds": tat_seconds, "assignedAt": now}

        if segment_id:
            raise HTTPException(status_code=400, detail="This job does not have claimable parts.")
        if job.get("status") != "approved" or job.get("worker_uid"):
            raise HTTPException(status_code=409, detail="Another worker has already claimed this job.")
        cycle_id = worker_profile.get("worker_qualification_cycle") or "initial"
        item_key = _human_claim_item_key(job_id, "")
        attempt_ref = db.collection(HUMAN_WORKER_ITEM_CLAIM_COLLECTION).document(
            _human_claim_attempt_document_id(worker_uid, cycle_id, item_key)
        )
        attempt_snapshot = attempt_ref.get(transaction=tx)
        attempt_data = attempt_snapshot.to_dict() if attempt_snapshot.exists else {}
        claim_count = int(attempt_data.get("claim_count") or 0)
        if claim_count >= HUMAN_WORKER_MAX_CLAIMS_PER_ITEM:
            raise HTTPException(status_code=409, detail="You have already claimed this job once. It cannot be claimed again. Choose another available job.")
        tat_seconds = (
            human_image_tat_seconds((job.get("pdf_review") or {}).get("page_count") or 1)
            if job_type == "pdf_job"
            else human_tat_seconds(float(job.get("seconds") or 0))
        )
        deadline = now + timedelta(seconds=tat_seconds)
        tx.update(job_ref, {
            "status": "assigned", "worker_uid": worker_uid,
            "worker_email": str(actor.get("email") or "").strip().lower(),
            "worker_name": str((actor.get("profile") or {}).get("name") or (actor.get("profile") or {}).get("displayName") or "").strip(),
            "assignedAt": now, "deadlineAt": deadline, "tat_seconds": tat_seconds,
            "after_hours_self_claim": bool(after_hours_self_claim),
            "assigned_worker_uids": [worker_uid], "updatedAt": firestore.SERVER_TIMESTAMP,
        })
        tx.set(attempt_ref, {
            "worker_uid": worker_uid, "qualification_cycle": str(cycle_id), "item_key": item_key,
            "job_id": job_id, "segment_id": "", "claim_count": claim_count + 1,
            "updatedAt": firestore.SERVER_TIMESTAMP,
        }, merge=True)
        tx.set(claim_ref, {"worker_uid": worker_uid, "job_id": job_id, "segment_id": "", "role": "transcriber", "status": "active", "assignedAt": now, "deadlineAt": deadline, "updatedAt": firestore.SERVER_TIMESTAMP}, merge=True)
        return {"job_id": job_id, "segment_id": "", "claim_count": claim_count + 1, "label": "your transcription job", "status": "assigned", "tat_seconds": tat_seconds, "assignedAt": now}

    return claim(transaction)


def _human_assign_proofreader_transaction(
    job_id, worker, tat_seconds, transcript=None, transcript_html=None,
    proofreader_parts_override=None, proofreader_use_combined_transcript=False,
):
    """Assign the final proofreader while taking the same per-worker claim lock."""
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    worker_uid = str(worker.get("worker_uid") or "").strip()
    job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
    claim_ref = db.collection(HUMAN_WORKER_CLAIM_COLLECTION).document(worker_uid)
    worker_ref = db.collection("users").document(worker_uid)
    transaction = db.transaction()

    @firestore.transactional
    def assign(tx):
        job_snapshot = job_ref.get(transaction=tx)
        if not job_snapshot.exists:
            raise HTTPException(status_code=404, detail="This job is no longer available.")
        job = job_snapshot.to_dict() or {}
        worker_snapshot = worker_ref.get(transaction=tx)
        worker_profile = worker_snapshot.to_dict() if worker_snapshot.exists else {}
        if worker_profile.get("workerApproved") is not True:
            raise HTTPException(status_code=403, detail="Approved worker access is required.")
        claim_snapshot = claim_ref.get(transaction=tx)
        current_claim = claim_snapshot.to_dict() if claim_snapshot.exists else {}
        if current_claim.get("status") == "active":
            old_job_id = str(current_claim.get("job_id") or "")
            old_ref = db.collection(HUMAN_JOB_COLLECTION).document(old_job_id) if old_job_id else None
            old_snapshot = old_ref.get(transaction=tx) if old_ref else None
            old_job = old_snapshot.to_dict() if old_snapshot and old_snapshot.exists else None
            if _human_claim_is_active(old_job, worker_uid, current_claim):
                raise HTTPException(status_code=409, detail="This worker must finish their current assignment before proofreading another job.")
        if _human_is_split_job(job):
            if not any((item or {}).get("status") == "submitted" for item in (job.get("segments") or [])):
                raise HTTPException(status_code=409, detail="At least one transcription part must be submitted before assigning a proofreader.")
        else:
            is_image_review = str(job.get("job_type") or "").strip().lower() == "pdf_job" and bool(job.get("pdf_review"))
            reviewable_status = job.get("status") in {"submitted", "client_review", "client_approved"} or (is_image_review and job.get("status") == "approved")
            has_review_material = bool(str(job.get("transcript") or "").strip() or (job.get("final_attachment") or {}).get("storage_path") or is_image_review)
            if not reviewable_status or not has_review_material:
                raise HTTPException(status_code=409, detail="Submit the complete job before assigning a human proofreader.")
        if job.get("proofreader_status") in {"assigned", "in_progress"}:
            raise HTTPException(status_code=409, detail="A proofreader is already working on this job. Take back that assignment before changing it.")
        now = datetime.now()
        deadline = now + timedelta(seconds=tat_seconds)
        assigned = list(job.get("assigned_worker_uids") or [])
        if worker_uid not in assigned:
            assigned.append(worker_uid)
        updates = {
            "status": "proofreading_assigned",
            "proofreader_uid": worker_uid,
            "proofreader_email": str(worker.get("worker_email") or "").strip().lower(),
            "proofreader_name": str(worker.get("worker_name") or "").strip(),
            "proofreader_status": "assigned",
            "reviewer_choice": "human", "reviewer_status": "assigned",
            "proofreader_assignedAt": now,
            "proofreader_deadlineAt": deadline,
            "proofreader_tat_seconds": tat_seconds,
            "proofreader_tat_extension_minutes": 0,
            "assigned_worker_uids": assigned,
            "updatedAt": firestore.SERVER_TIMESTAMP,
        }
        if transcript is not None:
            updates["transcript"] = str(transcript)[:1000000]
            updates["transcript_html"] = str(transcript_html or "")[:1500000]
            updates["proofreader_parts_override"] = proofreader_parts_override or {}
            updates["proofreader_use_combined_transcript"] = bool(proofreader_use_combined_transcript)
        tx.update(job_ref, updates)
        tx.set(claim_ref, {
            "worker_uid": worker_uid, "job_id": job_id, "segment_id": "proofreader",
            "role": "proofreader", "status": "active", "assignedAt": now,
            "deadlineAt": deadline, "updatedAt": firestore.SERVER_TIMESTAMP,
        }, merge=True)
        return {"assignedAt": now, "deadlineAt": deadline, "worker_uid": worker_uid}

    return assign(transaction)


_EDITOR_HTML_TAGS = {
    "p", "br", "b", "strong", "i", "em", "u", "s", "strike", "sub", "sup", "span", "div",
    "h1", "h2", "h3", "h4", "h5", "h6", "ul", "ol", "li", "table", "thead", "tbody", "tr", "td", "th",
    "hr", "blockquote", "pre", "font",
}
_EDITOR_HTML_DROP = {"script", "style", "iframe", "object", "embed", "link", "meta", "form", "input", "button", "textarea", "select", "svg", "math", "head", "title", "xml"}
_EDITOR_STYLE_PROPS = {
    "font-weight", "font-style", "text-decoration", "text-align", "text-indent", "margin-left", "margin-right",
    "margin", "padding", "margin-top", "margin-bottom", "padding-left", "line-height", "font-family", "font-size", "color",
    "background-color", "white-space", "text-transform", "letter-spacing", "vertical-align",
}


def _sanitize_editor_html(value, limit=1500000):
    """Keep Word-style formatting from pasted text and remove anything active.

    Only a small allow-list of tags and style properties survives, every
    attribute other than a cleaned style, colspan or rowspan is dropped, and
    links, scripts, images and event handlers never reach storage.
    """
    from html.parser import HTMLParser
    from html import escape

    raw = str(value or "")[:limit]
    if not raw.strip():
        return ""

    class Cleaner(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.out = []
            self.skip = 0

        def handle_starttag(self, tag, attrs):
            tag = tag.lower()
            if tag in _EDITOR_HTML_DROP:
                self.skip += 1
                return
            if self.skip or tag not in _EDITOR_HTML_TAGS:
                return
            kept = []
            for name, val in attrs:
                name = (name or "").lower()
                val = val or ""
                if name == "style":
                    pairs = []
                    for chunk in val.split(";"):
                        if ":" not in chunk:
                            continue
                        prop, _, rest = chunk.partition(":")
                        prop = prop.strip().lower()
                        rest = rest.strip()
                        low = rest.lower()
                        if prop in _EDITOR_STYLE_PROPS and rest and not any(bad in low for bad in ("url(", "expression", "javascript", "@import", "<", ">")):
                            pairs.append(f"{prop}:{rest}")
                    if pairs:
                        kept.append(f' style="{escape("; ".join(pairs), quote=True)}"')
                elif name in {"colspan", "rowspan"} and val.isdigit():
                    kept.append(f' {name}="{val}"')
            if tag in {"br", "hr"}:
                self.out.append(f"<{tag}{''.join(kept)}>")
            else:
                self.out.append(f"<{tag}{''.join(kept)}>")

        def handle_endtag(self, tag):
            tag = tag.lower()
            if tag in _EDITOR_HTML_DROP:
                self.skip = max(0, self.skip - 1)
                return
            if self.skip or tag not in _EDITOR_HTML_TAGS or tag in {"br", "hr"}:
                return
            self.out.append(f"</{tag}>")

        def handle_data(self, data):
            if not self.skip:
                self.out.append(escape(data, quote=False))

    cleaner = Cleaner()
    try:
        cleaner.feed(raw)
        cleaner.close()
    except Exception:
        return ""
    return "".join(cleaner.out)[:limit]


def _human_assign_whole_job_transaction(job_id, actor):
    """Give an entire not-yet-started job to one worker, ignoring their rating.

    For urgent work. The job is un-split only while nothing on it has been
    claimed or submitted, and the worker's one-active-assignment lock and
    approval are still enforced.
    """
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    worker_uid = str(actor.get("uid") or "")
    job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
    claim_ref = db.collection(HUMAN_WORKER_CLAIM_COLLECTION).document(worker_uid)
    worker_ref = db.collection("users").document(worker_uid)
    transaction = db.transaction()

    @firestore.transactional
    def assign(tx):
        job_snapshot = job_ref.get(transaction=tx)
        if not job_snapshot.exists:
            raise HTTPException(status_code=404, detail="This job is no longer available.")
        job = job_snapshot.to_dict() or {}
        worker_snapshot = worker_ref.get(transaction=tx)
        worker_profile = worker_snapshot.to_dict() if worker_snapshot.exists else {}
        if worker_profile.get("workerApproved") is not True:
            raise HTTPException(status_code=403, detail="Approved worker access is required.")
        claim_snapshot = claim_ref.get(transaction=tx)
        current_claim = claim_snapshot.to_dict() if claim_snapshot.exists else {}
        if current_claim.get("status") == "active":
            old_job_id = str(current_claim.get("job_id") or "")
            old_ref = db.collection(HUMAN_JOB_COLLECTION).document(old_job_id) if old_job_id else None
            old_snapshot = old_ref.get(transaction=tx) if old_ref else None
            old_job = old_snapshot.to_dict() if old_snapshot and old_snapshot.exists else None
            if _human_claim_is_active(old_job, worker_uid, current_claim):
                raise HTTPException(status_code=409, detail="This worker must finish their current assignment before taking a whole job.")
        if _human_is_split_job(job):
            segments = job.get("segments") or []
            untouched = all((item or {}).get("status") in {"available", "approved"} and not (item or {}).get("worker_uid") for item in segments)
            if not untouched or job.get("proofreader_status") in {"assigned", "in_progress", "submitted"}:
                raise HTTPException(status_code=409, detail="A part of this job has already been claimed. Take that part back first, or assign the remaining parts individually.")
        elif job.get("status") != "approved" or job.get("worker_uid"):
            raise HTTPException(status_code=409, detail="Only an approved job that nobody has claimed can be assigned as a whole job.")
        now = datetime.now()
        if str(job.get("job_type") or "").strip().lower() == "pdf_job":
            image_count = (job.get("pdf_review") or {}).get("page_count") or 1
            tat_seconds = human_image_tat_seconds(image_count)
        else:
            tat_seconds = human_tat_seconds(float(job.get("seconds") or 0))
        deadline = now + timedelta(seconds=tat_seconds)
        updates = {
            "status": "assigned",
            "segments": [],
            "split_mode": "single",
            "worker_uid": worker_uid,
            "worker_email": str(actor.get("email") or "").strip().lower(),
            "worker_name": str((actor.get("profile") or {}).get("name") or (actor.get("profile") or {}).get("displayName") or "").strip(),
            "assignedAt": now, "deadlineAt": deadline, "tat_seconds": tat_seconds,
            "assigned_worker_uids": [worker_uid],
            "whole_job_assignment": True,
            "updatedAt": firestore.SERVER_TIMESTAMP,
        }
        if job.get("pdf_review"):
            updates.update({"reviewer_choice": "human", "reviewer_status": "assigned"})
        tx.update(job_ref, updates)
        tx.set(claim_ref, {"worker_uid": worker_uid, "job_id": job_id, "segment_id": "", "role": "transcriber", "status": "active", "assignedAt": now, "deadlineAt": deadline, "updatedAt": firestore.SERVER_TIMESTAMP}, merge=True)
        return {"job_id": job_id, "segment_id": "", "label": "your whole transcription job", "status": "assigned", "tat_seconds": tat_seconds, "assignedAt": now}

    return assign(transaction)


async def _human_check_expiry(job_id: str, job: dict):
    """Return expired work once without double-counting concurrent page reads."""
    if not db or not job:
        return job
    if _human_is_split_job(job):
        return await _human_reclaim_expired_job(job_id, job, split_expected=True)
    if job.get("status") not in ("assigned", "in_progress"):
        return job
    deadline = _as_dt(job.get("deadlineAt"))
    if not deadline or datetime.now() <= deadline:
        return job
    return await _human_reclaim_expired_job(job_id, job, split_expected=False)


async def _human_job(job_id: str):
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    snapshot = await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).get)
    if not snapshot.exists:
        raise HTTPException(status_code=404, detail="That human-transcription job was not found.")
    data = snapshot.to_dict() or {}
    data["id"] = snapshot.id
    data = await _human_check_expiry(job_id, data)
    return data


async def human_expiry_sweep():
    """Background safety net: reclaim any job whose worker TAT deadline has
    passed even if nobody happens to load it in the browser right now."""
    if not db:
        return
    try:
        snapshots = await asyncio.to_thread(
            lambda: list(db.collection(HUMAN_JOB_COLLECTION).where(filter=FieldFilter("status", "in", [
                "assigned", "in_progress", "split_assigned", "split_in_progress",
                "proofreading_assigned", "proofreading_in_progress",
            ])).stream())
        )
    except Exception as exc:
        logger.warning("Human job expiry sweep could not list jobs: %s", exc)
        return
    for snap in snapshots:
        data = snap.to_dict() or {}
        data["id"] = snap.id
        await _human_check_expiry(snap.id, data)


async def human_expiry_monitor():
    """Runs for the life of the app, checking worker TAT deadlines every
    minute so an expired job is returned to the admin queue promptly."""
    while True:
        try:
            await human_expiry_sweep()
        except Exception as exc:
            logger.warning("Human job expiry monitor iteration failed: %s", exc)
        await asyncio.sleep(60)


# ===================== Human worker bi-monthly payouts =====================
# Worker pay accrues across two halves of each calendar month: the 1st-15th
# and the 16th-end of month. When a half ends, every worker's accrued jobs in
# that half are rolled into one pending payout invoice, which an admin later
# marks as paid. The next half starts accruing immediately regardless of
# whether the previous invoice has been paid yet.
HUMAN_PAYOUT_COLLECTION = "human_worker_payouts"
HUMAN_EARNING_ARCHIVE_COLLECTION = "human_worker_earnings"
HUMAN_DEDUCTION_COLLECTION = "human_worker_payment_adjustments"
HUMAN_SUBADMIN_EARNING_COLLECTION = "human_subadmin_earnings"
HUMAN_SUBADMIN_PAYOUT_COLLECTION = "human_subadmin_payouts"
HUMAN_SUBADMIN_RATE_SETTINGS_COLLECTION = "human_subadmin_rate_settings"
HUMAN_SUBADMIN_RATE_SETTINGS_DOCUMENT = "default"


def _human_subadmin_rate_defaults():
    # Image work is priced in KES per word (human 0.2, AI agent 0.15).
    # KES is stored in milli-shillings per unit so fractions stay exact.
    return {
        "audio_human_kes_per_minute": 10,
        "audio_ai_kes_per_minute": 20,
        "image_human_kes_per_word": "0.2",
        "image_ai_kes_per_word": "0.15",
    }


def _human_subadmin_image_milli_rate(kes_per_word):
    value = Decimal(str(kes_per_word)) * Decimal("1000")
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def _human_subadmin_rate_values(raw=None):
    defaults = _human_subadmin_rate_defaults()
    raw = raw or {}
    values = {}
    for key in ("audio_human_kes_per_minute", "audio_ai_kes_per_minute"):
        values[key] = defaults[key]
        try:
            value = int(raw.get(key, defaults[key]))
            if value >= 0:
                values[key] = value
        except (TypeError, ValueError):
            pass
    for key in ("image_human_kes_per_word", "image_ai_kes_per_word"):
        values[key] = defaults[key]
        try:
            candidate = Decimal(str(raw.get(key, defaults[key])))
            if candidate.is_finite() and Decimal("0") <= candidate <= Decimal("1000"):
                values[key] = format(candidate.normalize(), "f")
        except (InvalidOperation, TypeError, ValueError):
            pass
    values["image_human_rate_milli_kes_per_word"] = _human_subadmin_image_milli_rate(values["image_human_kes_per_word"])
    values["image_ai_rate_milli_kes_per_word"] = _human_subadmin_image_milli_rate(values["image_ai_kes_per_word"])
    return values


def _human_subadmin_rate_public(raw=None):
    values = _human_subadmin_rate_values(raw)
    return {
        "audio_human_kes_per_minute": values["audio_human_kes_per_minute"],
        "audio_ai_kes_per_minute": values["audio_ai_kes_per_minute"],
        "image_human_kes_per_word": float(values["image_human_kes_per_word"]),
        "image_ai_kes_per_word": float(values["image_ai_kes_per_word"]),
        "applies_to": "future earnings; use Recalculate to correct accruing image earnings",
    }


def _human_subadmin_parse_rate_update(payload):
    payload = payload or {}
    result = {}
    for key in ("audio_human_kes_per_minute", "audio_ai_kes_per_minute"):
        try:
            decimal_value = Decimal(str(payload.get(key)))
        except (InvalidOperation, TypeError, ValueError):
            raise ValueError("Audio rates must be whole KES amounts per minute.")
        if not decimal_value.is_finite() or decimal_value != decimal_value.to_integral_value():
            raise ValueError("Audio rates must be whole KES amounts per minute.")
        value = int(decimal_value)
        if value < 0 or value > 10000:
            raise ValueError("Audio rates must be between KES 0 and KES 10,000 per minute.")
        result[key] = value
    for key in ("image_human_kes_per_word", "image_ai_kes_per_word"):
        try:
            decimal_value = Decimal(str(payload.get(key)))
        except (InvalidOperation, TypeError, ValueError):
            raise ValueError("Image rates must be numeric KES per word.")
        if not decimal_value.is_finite() or decimal_value < 0 or decimal_value > Decimal("1000") or decimal_value != decimal_value.quantize(Decimal("0.001")):
            raise ValueError("Image rates must be from 0 to 1,000 KES per word, up to three decimals.")
        result[key] = format(decimal_value.normalize(), "f")
    return result


def _human_subadmin_word_count(text):
    plain = unescape(str(text or ""))
    plain = re.sub(r"<[^>]*>", " ", plain)
    return len(re.findall(r"(?u)\b[\w]+(?:['’][\w]+)*\b", plain))


def _human_subadmin_audio_minutes(job, segment=None):
    if segment:
        try:
            minutes = int(segment.get("minutes") or 0)
            if minutes > 0:
                return minutes
        except (TypeError, ValueError):
            pass
        start = segment.get("start_seconds")
        end = segment.get("end_seconds")
        try:
            if start is not None and end is not None and float(end) > float(start):
                return max(1, int(math.ceil((float(end) - float(start)) / 60.0)))
        except (TypeError, ValueError):
            pass
    quote = job.get("quote") or {}
    for raw in (segment or {}).get("worker_minutes"), job.get("minutes"), quote.get("minutes"):
        try:
            minutes = int(raw or 0)
            if minutes > 0:
                return minutes
        except (TypeError, ValueError):
            continue
    for raw_seconds in (segment or {}).get("audio_seconds"), job.get("seconds"), job.get("audio_seconds"), quote.get("seconds"):
        try:
            seconds = float(raw_seconds or 0)
            if seconds > 0:
                return max(1, int(math.ceil(seconds / 60.0)))
        except (TypeError, ValueError):
            continue
    return 0


def _human_subadmin_ai_used(job, segment=None):
    job = job or {}
    if str(job.get("reviewer_choice") or "").lower() == "ai" or job.get("ai_review_applied") is True:
        return True
    if segment:
        segment_status = str(segment.get("ai_agent_status") or "").lower()
        if segment_status:
            return segment_status in {"submitted", "completed", "finished"}
        # A parent job's agent status may describe a different slice, so never
        # use it to classify a segment without its own AI marker.
        return False
    return any(str(job.get(key) or "").lower() in {"submitted", "completed", "finished"} for key in (
        "ai_agent_status", "letter_agent_status", "letter_ai_review_status",
    ))


def _human_subadmin_image_agent_used(job, segment=None):
    job = job or {}
    done = {"submitted", "completed", "finished"}
    if segment:
        return str(segment.get("ai_agent_status") or "").lower() in done
    return str(job.get("ai_agent_status") or "").lower() in done


def _human_subadmin_assignment_metadata(job, segment=None, ai_used=None):
    job = job or {}
    if ai_used is False:
        prefixes = ("human_work", "proofreader", "worker", "ai_agent", "letter_agent", "ai_review", "letter_ai_review")
    elif str(job.get("reviewer_choice") or "").lower() == "ai" or job.get("ai_review_applied") is True:
        prefixes = ("ai_review", "letter_ai_review", "ai_agent", "letter_agent", "human_work", "worker", "proofreader")
    elif str(job.get("letter_ai_review_status") or "").lower() == "completed":
        prefixes = ("letter_ai_review", "letter_agent", "ai_agent", "ai_review", "human_work", "worker", "proofreader")
    else:
        prefixes = ("ai_agent", "letter_agent", "letter_ai_review", "ai_review", "human_work", "worker", "proofreader")
    sources = [segment or {}, job]
    for source in sources:
        for prefix in prefixes:
            email = str(source.get(f"{prefix}_assigned_by_email") or "").strip().lower()
            if email:
                uid = str(source.get(f"{prefix}_assigned_by_uid") or source.get(f"{prefix}_assigned_by") or "").strip()
                assigned_at = source.get(f"{prefix}_assignedAt") or source.get(f"{prefix}_assigned_at")
                return email, uid, assigned_at
    if ai_used is False:
        configured = sorted({str(value or "").strip().lower() for value in HUMAN_JOB_ADMIN_EMAILS if is_human_subadmin(value)})
        approved_at = job.get("approvedAt") or job.get("approved_at")
        # Older approved jobs did not store the approver. Until they are edited
        # again, use their recorded queue-approval time as the shift-work anchor
        # only when there is exactly one configured sub-admin.
        if len(configured) == 1 and approved_at:
            return configured[0], "", approved_at
    return "", "", None


def _human_subadmin_earning_specs(job_id, job, actor, now=None, rates=None, segment_ids=None, ai_only=False):
    """Build one idempotent earning per approved Human Work job or submitted slice."""
    job = job or {}
    actor = actor or {}
    actor_email = str(actor.get("email") or "").strip().lower()
    actor_uid = str(actor.get("uid") or "").strip()
    now_local = now or _human_shift_local_now()
    if isinstance(now_local, str):
        now_local = _human_shift_parse_datetime(now_local) or _human_shift_local_now()
    if not getattr(now_local, "tzinfo", None):
        now_local = now_local.replace(tzinfo=HUMAN_SHIFT_TIMEZONE)
    else:
        now_local = now_local.astimezone(HUMAN_SHIFT_TIMEZONE)
    now_naive = now_local.replace(tzinfo=None)
    rates = _human_subadmin_rate_values(rates)
    job_type = str(job.get("job_type") or "human_transcription").strip().lower()
    is_image = job_type == "pdf_job"
    submitted_segments = [dict(part or {}) for part in (job.get("segments") or []) if str((part or {}).get("status") or "").lower() == "submitted"]
    image_review_job = is_image and bool(job.get("pdf_review"))
    items = []
    parts = [(None, job)] if image_review_job or not submitted_segments else [(part, part) for part in submitted_segments]
    if segment_ids is not None and not image_review_job:
        selected_ids = {str(value or "").strip() for value in segment_ids}
        parts = [(segment, content) for segment, content in parts if str((segment or {}).get("id") or "").strip() in selected_ids]

    for segment, content in parts:
        if ai_only and not (_human_subadmin_image_agent_used(job, segment) if is_image else _human_subadmin_ai_used(job, segment)):
            continue
        if segment is not None and not str(segment.get("transcript") or segment.get("transcript_html") or "").strip():
            if is_image or not (segment.get("final_attachment") or {}).get("storage_path"):
                continue
        ai_used = _human_subadmin_ai_used(job, segment)
        if is_image:
            # Only an AI agent that handled the image job counts as AI work;
            # AI proofreading never changes sub-admin image pay.
            ai_used = _human_subadmin_image_agent_used(job, segment)
        if not ai_used:
            has_human_submission = bool(
                (segment and (segment.get("worker_uid") or segment.get("workerCompletedAt") or segment.get("proofreader_uid")))
                or job.get("worker_uid") or job.get("workerCompletedAt") or job.get("proofreader_status") == "submitted"
            )
            if not has_human_submission:
                continue
        assigned_email, assigned_uid, assigned_at = _human_subadmin_assignment_metadata(job, segment, ai_used=ai_used)
        # A sub-admin who performed the final review is paid for that work.
        # If the main admin completes it later, preserve the sub-admin who
        # launched the AI run during their scheduled shift.
        if is_human_subadmin(actor_email):
            beneficiary_email, beneficiary_uid = actor_email, actor_uid
            assigned_shift = _human_shift_parse_datetime(assigned_at) if assigned_email == actor_email else None
            shift_action_at = assigned_shift or now_local
        elif is_human_subadmin(assigned_email):
            beneficiary_email = assigned_email
            beneficiary_uid = assigned_uid
            shift_action_at = _human_shift_parse_datetime(assigned_at) or now_local
        else:
            continue
        if not beneficiary_uid or not _human_shift_is_scheduled(shift_action_at):
            continue

        if is_image:
            if segment is not None:
                text = segment.get("transcript") or segment.get("transcript_html") or ""
            else:
                text = job.get("transcript") or job.get("transcript_html") or ""
            quantity = _human_subadmin_word_count(text)
            measure = "words"
            rate = rates["image_ai_rate_milli_kes_per_word"] if ai_used else rates["image_human_rate_milli_kes_per_word"]
            category = "image_ai" if ai_used else "image_human"
        else:
            quantity = _human_subadmin_audio_minutes(job, segment)
            measure = "minutes"
            rate = (rates["audio_ai_kes_per_minute"] if ai_used else rates["audio_human_kes_per_minute"]) * 1000
            category = "audio_ai" if ai_used else "audio_human"
        if quantity <= 0 or rate <= 0:
            continue
        segment_id = str((segment or {}).get("id") or "").strip() or None
        identity = "|".join((beneficiary_uid, str(job_id), segment_id or "job"))
        earning_id = hashlib.sha256(identity.encode("utf-8")).hexdigest()
        items.append({
            "earning_id": earning_id,
            "subadmin_uid": beneficiary_uid,
            "subadmin_email": beneficiary_email,
            "job_id": str(job_id),
            "job_name": str(job.get("job_name") or job.get("title") or "Human Work")[:240],
            "job_type": job_type,
            "job_category": str(job.get("job_category") or job.get("category") or "").strip().lower(),
            "segment_id": segment_id,
            "category": category,
            "work_source": "ai" if ai_used else "human",
            "measure": measure,
            "quantity": quantity,
            "rate_milli_kes_per_unit": rate,
            "amount_kes_milli": quantity * rate,
            "completed_at": now_naive,
            "shift_action_at": shift_action_at,
            "shift_date": shift_action_at.date().isoformat(),
            "payout_status": "accruing",
            "payout_period_id": None,
            "createdAt": firestore.SERVER_TIMESTAMP,
            "updatedAt": firestore.SERVER_TIMESTAMP,
        })
    return items


def _pay_period_bounds(dt):
    """Which half-month period does this datetime fall in, and when does it
    start/end? Returns (period_label, start_dt, end_dt_exclusive)."""
    year, month, day = dt.year, dt.month, dt.day
    last_day = calendar.monthrange(year, month)[1]
    if day <= 15:
        label = f"{year:04d}-{month:02d}-A"
        start = datetime(year, month, 1)
        end = datetime(year, month, 15, 23, 59, 59, 999999)
    else:
        label = f"{year:04d}-{month:02d}-B"
        start = datetime(year, month, 16)
        end = datetime(year, month, last_day, 23, 59, 59, 999999)
    return label, start, end


def _human_worker_earning_items(job_id, job, include_processed=False):
    """Yield normalized earnings for transcription parts and proofreading.

    With include_processed=True this also returns invoiced/paid items, allowing
    payment history and cleanup to use the same stable representation.
    """
    quote = job.get("quote") or {}
    default_rate = int(quote.get("transcriber_payout_kes_per_minute") or HUMAN_LEGACY_STANDARD_PAYOUT_KES)

    def normalize(source, raw, uid, email, name, minutes, completed_at, rate, payout_status, period_id, paid_at):
        if not uid or not completed_at:
            return None
        payout_status = str(payout_status or "").strip().lower()
        if paid_at:
            payout_status = "paid"
        elif period_id and payout_status in ("", "unassigned"):
            payout_status = "invoiced"
        if not include_processed and (payout_status not in ("", "unassigned") or period_id or paid_at):
            return None
        try:
            minutes = max(0, int(minutes or 0))
        except (TypeError, ValueError):
            minutes = 0
        try:
            gross = max(0, int(raw.get("worker_gross_amount_kes") or raw.get("gross_amount_kes") or raw.get("worker_amount_kes") or minutes * rate))
            deduction = max(0, int(raw.get("worker_deduction_kes") or raw.get("deduction_kes") or 0))
        except (TypeError, ValueError):
            gross, deduction = max(0, minutes * rate), 0
        deduction = min(deduction, gross)
        return {
            "source": source, "job_id": job_id, "segment_id": raw.get("id") if source == "segment" else None,
            "worker_uid": uid, "worker_email": email or "", "worker_name": name or "",
            "completed_at": _as_dt(completed_at), "minutes": minutes,
            "gross_amount_kes": gross, "deduction_kes": deduction,
            "deduction_reason": raw.get("worker_deduction_reason") or raw.get("deduction_reason") or "",
            "amount_kes": max(0, gross - deduction), "payout_status": payout_status or "unassigned",
            "payout_period_id": period_id, "paid_at": _as_dt(paid_at) if paid_at else None,
        }

    is_pdf_job = str(job.get("job_type") or "").strip().lower() == "pdf_job"
    single_source = "pdf" if is_pdf_job else "job"
    if is_pdf_job:
        default_rate = _human_pdf_job_pay_kes(job)
    single = normalize(single_source, job, job.get("worker_uid"), job.get("worker_email"), job.get("worker_name"), job.get("worker_minutes") or job.get("minutes"), job.get("workerCompletedAt"), default_rate, job.get("payout_status"), job.get("payout_period_id"), job.get("workerPaidAt"))
    if single:
        yield single
    for segment in (job.get("segments") or []):
        item = normalize("segment", segment, segment.get("worker_uid"), segment.get("worker_email"), segment.get("worker_name"), segment.get("worker_minutes") or segment.get("minutes"), segment.get("workerCompletedAt"), default_rate, segment.get("payout_status"), segment.get("payout_period_id"), segment.get("workerPaidAt"))
        if item:
            item["segment_id"] = segment.get("id")
            yield item
    proofreader_financials = dict(job)
    proofreader_financials.update({
        "worker_gross_amount_kes": job.get("proofreader_gross_amount_kes") or job.get("proofreader_amount_kes"),
        "worker_deduction_kes": job.get("proofreader_deduction_kes"),
        "worker_deduction_reason": job.get("proofreader_deduction_reason"),
    })
    proofreader = normalize("proofreader", proofreader_financials, job.get("proofreader_uid"), job.get("proofreader_email"), job.get("proofreader_name"), job.get("proofreader_minutes") or job.get("minutes"), job.get("proofreader_completedAt"), HUMAN_PROOFREADING_PAYOUT_KES, job.get("proofreader_payout_status"), job.get("proofreader_payout_period_id"), job.get("proofreaderPaidAt"))
    if proofreader:
        yield proofreader


async def _close_due_pay_periods():
    """Roll completed job and archived earnings into half-month invoices."""
    if not db:
        return
    now = datetime.now()
    try:
        job_snapshots = await asyncio.to_thread(lambda: list(db.collection(HUMAN_JOB_COLLECTION).stream()))
        archive_snapshots = await asyncio.to_thread(lambda: list(db.collection(HUMAN_EARNING_ARCHIVE_COLLECTION).stream()))
    except Exception as exc:
        logger.warning("Pay period close could not list earnings: %s", exc)
        return
    groups = {}

    def add_item(item, archive_doc_id=None):
        completed_at = _as_dt(item.get("completed_at")) if item.get("completed_at") else None
        if not completed_at:
            return
        label, start_dt, end_dt = _pay_period_bounds(completed_at)
        if now <= end_dt:
            return
        item = dict(item)
        item["completed_at"] = completed_at
        item["archive_doc_id"] = archive_doc_id
        key = (item.get("worker_uid"), label)
        bucket = groups.setdefault(key, {
            "worker_uid": item.get("worker_uid"), "worker_email": item.get("worker_email") or "", "worker_name": item.get("worker_name") or "",
            "period_label": label, "period_start": start_dt, "period_end": end_dt,
            "job_ids": [], "items": [], "total_minutes": 0, "total_amount_kes": 0,
        })
        identity = (item.get("job_id"), item.get("source"), item.get("segment_id"))
        if any((x.get("job_id"), x.get("source"), x.get("segment_id")) == identity for x in bucket["items"]):
            return
        bucket["job_ids"].append(item.get("job_id"))
        bucket["items"].append(item)
        bucket["total_minutes"] += int(item.get("minutes") or 0)
        bucket["total_amount_kes"] += int(item.get("amount_kes") or 0)

    for snap in job_snapshots:
        job = snap.to_dict() or {}
        for item in _human_worker_earning_items(snap.id, job):
            add_item(item)
    for snap in archive_snapshots:
        item = snap.to_dict() or {}
        if str(item.get("payout_status") or "unassigned").lower() not in ("", "unassigned") or item.get("payout_period_id") or item.get("paid_at"):
            continue
        add_item(item, snap.id)

    for (worker_uid, label), bucket in groups.items():
        if not worker_uid:
            continue
        payout_id = f"{worker_uid}_{label}"
        payout_ref = db.collection(HUMAN_PAYOUT_COLLECTION).document(payout_id)
        existing_snapshot = await asyncio.to_thread(payout_ref.get)
        new_items = [{
            "job_id": item["job_id"], "source": item["source"], "segment_id": item.get("segment_id"),
            "minutes": item["minutes"], "amount_kes": item["amount_kes"],
            "gross_amount_kes": item.get("gross_amount_kes", item["amount_kes"]),
            "deduction_kes": item.get("deduction_kes", 0), "deduction_reason": item.get("deduction_reason") or "",
            "completed_at": item.get("completed_at"), "archive_doc_id": item.get("archive_doc_id"),
        } for item in bucket["items"]]
        if existing_snapshot.exists:
            existing = existing_snapshot.to_dict() or {}
            existing_items = existing.get("items") or []
            existing_ids = {(x.get("job_id"), x.get("source"), x.get("segment_id")) for x in existing_items}
            additions = [x for x in new_items if (x.get("job_id"), x.get("source"), x.get("segment_id")) not in existing_ids]
            updates = {
                "job_ids": sorted(set((existing.get("job_ids") or []) + [x for x in bucket["job_ids"] if x])),
                "items": existing_items + additions,
                "total_minutes": int(existing.get("total_minutes") or 0) + sum(int(x["minutes"]) for x in additions),
                "total_amount_kes": int(existing.get("total_amount_kes") or 0) + sum(int(x["amount_kes"]) for x in additions),
                "updatedAt": firestore.SERVER_TIMESTAMP,
            }
            await asyncio.to_thread(payout_ref.set, updates, merge=True)
        else:
            await asyncio.to_thread(payout_ref.set, {
                "worker_uid": worker_uid, "worker_email": bucket["worker_email"], "worker_name": bucket["worker_name"],
                "period_label": bucket["period_label"], "period_start": bucket["period_start"], "period_end": bucket["period_end"],
                "job_ids": sorted(set(x for x in bucket["job_ids"] if x)), "items": new_items,
                "total_minutes": bucket["total_minutes"], "total_amount_kes": bucket["total_amount_kes"], "status": "pending",
                "createdAt": firestore.SERVER_TIMESTAMP, "updatedAt": firestore.SERVER_TIMESTAMP, "paidAt": None, "paidBy": None,
            })
        # Mark only the exact earning as invoiced, wherever its durable copy lives.
        for item in bucket["items"]:
            if item.get("archive_doc_id"):
                await asyncio.to_thread(db.collection(HUMAN_EARNING_ARCHIVE_COLLECTION).document(item["archive_doc_id"]).set, {
                    "payout_status": "invoiced", "payout_period_id": label, "updatedAt": firestore.SERVER_TIMESTAMP,
                }, merge=True)
                continue
            job_ref = db.collection(HUMAN_JOB_COLLECTION).document(item["job_id"])
            snap = await asyncio.to_thread(job_ref.get)
            job = snap.to_dict() or {}
            update = {"updatedAt": firestore.SERVER_TIMESTAMP}
            if item["source"] in {"job", "pdf"}:
                update.update({"payout_status": "invoiced", "payout_period_id": label})
            elif item["source"] == "proofreader":
                update.update({"proofreader_payout_status": "invoiced", "proofreader_payout_period_id": label})
            elif item["source"] == "segment":
                segments = [dict(x or {}) for x in (job.get("segments") or [])]
                for segment in segments:
                    if segment.get("id") == item.get("segment_id"):
                        segment["payout_status"] = "invoiced"
                        segment["payout_period_id"] = label
                update["segments"] = segments
            if snap.exists:
                await asyncio.to_thread(job_ref.update, update)


async def human_payout_monitor():
    """Runs for the life of the app, closing any half-month pay period that
    has ended so its invoice is ready for the admin without anyone having to
    open the dashboard first."""
    while True:
        try:
            await _close_due_pay_periods()
            await _human_subadmin_close_due_pay_periods()
        except Exception as exc:
            logger.warning("Human payout monitor iteration failed: %s", exc)
        await asyncio.sleep(900)


async def _human_actor(request: Request):
    decoded = _verified_user(request)
    email = (decoded.get("email") or "").strip().lower()
    uid = decoded.get("uid") or ""
    if not uid:
        raise HTTPException(status_code=401, detail="Your account could not be verified.")
    # A human-job admin (real admin, or the dedicated info@typemywordz.ai ops
    # account) gets the "admin" role here even though it is not a full
    # ADMIN_EMAILS admin elsewhere in the app.
    role = "admin" if is_human_job_admin(email) else "client"
    profile = await _load_profile(uid)
    profile = profile or {}
    profile = await _heal_profile_identity(uid, email, profile)
    # A trainee belongs in the private Training Room until an admin explicitly
    # promotes them.  Only approved workers may see assigned human jobs.
    if profile.get("workerApproved") is True:
        role = "worker"
    return {"uid": uid, "email": email, "role": role, "profile": profile}


def _human_can_edit_own_payment_profile(actor):
    if actor.get("role") == "worker":
        return True
    profile = actor.get("profile") or {}
    profile_role = str(profile.get("role") or profile.get("user_type") or "").strip().lower()
    return bool(
        profile_role == "trainee"
        and profile.get("trainingRoomAccess") is True
        and str(profile.get("trainingPaymentStatus") or "").lower() == "paid"
    )


def _normalize_mpesa_details(registered_name, raw_number):
    name = re.sub(r"\s+", " ", str(registered_name or "").strip())[:120]
    number = re.sub(r"[\s()+.-]", "", str(raw_number or ""))
    if bool(name) != bool(number):
        raise HTTPException(status_code=400, detail="Enter both the M-Pesa registered name and number, or clear both fields.")
    if not name:
        return "", ""
    if len(name) < 2:
        raise HTTPException(status_code=400, detail="Enter the M-Pesa account name as it appears in M-Pesa.")
    if not re.fullmatch(r"(?:254|0)(?:7|1)\d{8}", number):
        raise HTTPException(status_code=400, detail="Enter a valid Kenyan M-Pesa number, such as 0712 345 678 or 254712345678.")
    normalized = "254" + number[1:] if number.startswith("0") else number
    return name, normalized


async def _human_assert_access(job, actor, allow_admin=True):
    if actor["role"] == "admin" and allow_admin:
        return
    if job.get("client_uid") == actor["uid"] or job.get("worker_uid") == actor["uid"]:
        return
    if any((item or {}).get("worker_uid") == actor["uid"] for item in (job.get("segments") or [])):
        return
    if job.get("proofreader_uid") == actor["uid"]:
        return
    raise HTTPException(status_code=403, detail="You do not have access to this job.")


@app.post("/human-transcription/jobs")
async def human_create_job(
    request: Request,
    audio: UploadFile = File(None),
    attachments: List[UploadFile] = File(default=[]),
    seconds: float = Form(0),
    turnaround: str = Form("standard"),
    difficulty: str = Form("standard"),
    timestamps: bool = Form(True),
    speakers: str = Form("1-2"),
    speaker_labels: bool = Form(True),
    instructions: str = Form(""),
    service: str = Form("standard"),
    formatting: str = Form("standard"),
    source_type: str = Form("human_transcription"),
    initial_transcript: str = Form(""),
    client_request_id: str = Form(""),
):
    actor = await _human_actor(request)
    if actor["role"] != "client" and actor["role"] != "admin":
        raise HTTPException(status_code=403, detail="Only a client can request human work.")
    if seconds <= 0:
        raise HTTPException(status_code=400, detail="The recording length is required.")
    source_type = str(source_type or "human_transcription").strip().lower()
    if source_type not in {"human_transcription", "ai_proofreading"}:
        raise HTTPException(status_code=400, detail="That proofreading source is not supported.")
    if source_type == "human_transcription" and (not audio or not audio.filename):
        raise HTTPException(status_code=400, detail="An audio or video file is required for a new human transcript.")
    if source_type == "ai_proofreading" and not str(initial_transcript or "").strip():
        raise HTTPException(status_code=400, detail="The AI transcript is required for proofreading.")
    client_request_id = str(client_request_id or "").strip()[:120]
    # A timed-out browser request can still finish creating the job. Reusing
    # the same client request id makes a retry return that job instead of
    # creating a duplicate order.
    if client_request_id and db is not None:
        existing_snapshots = await asyncio.to_thread(
            lambda: list(db.collection(HUMAN_JOB_COLLECTION)
                         .where(filter=FieldFilter("client_uid", "==", actor["uid"]))
                         .limit(100).stream())
        )
        for existing_snapshot in existing_snapshots:
            existing_job = existing_snapshot.to_dict() or {}
            if str(existing_job.get("client_request_id") or "") == client_request_id:
                existing_job["id"] = existing_snapshot.id
                return {"job": _human_public(existing_job), "reservation": "not_created", "credits_deducted": 0, "already_created": True}
    transcriber_rate = await _get_human_transcriber_rate()
    quote = human_credit_quote(seconds, turnaround, difficulty, service, speakers, timestamps, formatting, transcriber_rate)
    profile = await _load_profile(actor["uid"])
    balance = read_balance(profile or {})
    # A real admin, or the dedicated human-job-admin account, never needs
    # credits for a human-transcription job it owns. Everyone else -- every
    # ordinary client, including info@typemywordz.ai's own AI-transcription
    # and Ask TypeMyworDz usage elsewhere in the app -- still pays normally.
    exempt = credits_exempt(actor["email"]) or human_job_credits_exempt(actor["email"])
    if not exempt and balance["spendable"] < quote["credits"]:
        raise HTTPException(status_code=409, detail=f"You need {quote['credits'] - balance['spendable']} more credits before human work can begin.")
    job_id = uuid.uuid4().hex
    audio_meta = await _human_store_upload(job_id, audio, "audio") if audio and audio.filename else None
    attachment_meta = []
    for item in attachments or []:
        attachment_meta.append(await _human_store_upload(job_id, item, "instructions"))
    now = firestore.SERVER_TIMESTAMP
    job = {
        "client_uid": actor["uid"],
        "client_email": actor["email"],
        "client_request_id": client_request_id,
        "status": "pending_admin",
        "createdAt": now,
        "updatedAt": now,
        "seconds": float(seconds),
        "minutes": quote["minutes"],
        "turnaround": turnaround,
        "difficulty": difficulty,
        "service": service,
        "formatting": formatting,
        "timestamps": bool(timestamps),
        "speakers": speakers,
        "speaker_labels": bool(speaker_labels),
        "source_type": source_type,
        "instructions": (instructions or "").strip()[:12000],
        "audio": audio_meta,
        "instruction_attachments": attachment_meta,
        "quote_credits": int(quote["credits"]),
        "quote": quote,
        "worker_uid": None,
        "worker_email": None,
        "worker_name": None,
        "transcript": str(initial_transcript or "")[:1000000] if source_type == "ai_proofreading" else "",
        "worker_notes": "",
        "final_attachment": None,
        "admin_feedback": "",
        "worker_rating": None,
        "credits_charged": 0,
        "releasedAt": None,
        # TAT/deadline tracking (set when the job is assigned to a worker).
        "assignedAt": None,
        "deadlineAt": None,
        "tat_seconds": None,
        "auto_reassigned_count": 0,
        "last_auto_reassigned_at": None,
        "last_auto_reassigned_worker_name": None,
        # Worker pay/payout tracking.
        "workerCompletedAt": None,
        "worker_minutes": None,
        "worker_amount_kes": None,
        "payout_status": None,
        "payout_period_id": None,
        "workerPaymentStatus": None,
        "workerPaidAt": None,
        # Optional two-worker workflow. The parent job remains the client-facing
        # record; each segment carries its own worker, deadline and submission.
        "split_mode": "single",
        "segments": [],
        "assigned_worker_uids": [],
        "proofreader_uid": None,
        "proofreader_email": None,
        "proofreader_name": None,
        "proofreader_status": None,
        "proofreader_deadlineAt": None,
        "proofreader_tat_seconds": None,
        "proofreader_completedAt": None,
        "proofreader_minutes": None,
        "proofreader_amount_kes": None,
        "proofreader_payout_status": None,
        "proofreader_payout_period_id": None,
    }
    if db is None:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
    await asyncio.to_thread(job_ref.set, job)
    await _notify_human_admins(
        f"human-new-request:{job_id}", "job_request", "A new Human Work request",
        "Review the new request in the Human Work queue.", route="human_ops", job_id=job_id, requires_action=True,
    )
    # Resolve Firestore server timestamps before returning the created job.
    # Otherwise a successful upload can look like a failed request in the browser.
    saved_snapshot = await asyncio.to_thread(job_ref.get)
    saved_job = saved_snapshot.to_dict() or job
    saved_job["id"] = job_id
    return {"job": _human_public(saved_job), "reservation": "not_created", "credits_deducted": 0}


def _human_job_dashboard_archived(job, now=None):
    """Hide jobs older than three days from active admin queues, without deleting them."""
    created_at = _as_dt((job or {}).get("createdAt") or (job or {}).get("created_at"))
    if not created_at:
        return False
    current = now or datetime.now(timezone.utc).replace(tzinfo=None)
    if getattr(current, "tzinfo", None):
        current = current.astimezone(timezone.utc).replace(tzinfo=None)
    if getattr(created_at, "tzinfo", None):
        created_at = created_at.astimezone(timezone.utc).replace(tzinfo=None)
    return current - created_at >= timedelta(days=HUMAN_JOB_DASHBOARD_RETENTION_DAYS)


_HUMAN_LIST_CACHE_TTL_SECONDS = 2.0
_human_list_cache = {}
_human_list_cache_epoch = 0


def _human_list_cache_bump():
    global _human_list_cache_epoch
    _human_list_cache_epoch += 1


@app.middleware("http")
async def _human_list_cache_invalidation_middleware(request: Request, call_next):
    mutating = request.method not in {"GET", "HEAD", "OPTIONS"} and (
        request.url.path.startswith("/human-transcription") or request.url.path.startswith("/api/admin")
        or request.url.path.startswith("/api/messaging") or request.url.path.startswith("/api/notifications")
    )
    if mutating:
        _human_list_cache_bump()
    try:
        return await call_next(request)
    finally:
        if mutating:
            _human_list_cache_bump()


async def _human_cached_query(key, loader):
    """Share one Firestore read between overlapping polls for ~2 seconds.

    Any write to Human Work routes bumps the epoch, so a cached list is never
    reused after a change made through this server.
    """
    now = time.monotonic()
    entry = _human_list_cache.get(key)
    if entry and entry["epoch"] == _human_list_cache_epoch:
        if entry.get("task") is not None and not entry["task"].done():
            return await asyncio.shield(entry["task"])
        if entry.get("rows") is not None and now - entry["at"] < _HUMAN_LIST_CACHE_TTL_SECONDS:
            return entry["rows"]
    epoch = _human_list_cache_epoch
    task = asyncio.ensure_future(asyncio.to_thread(loader))
    _human_list_cache[key] = {"epoch": epoch, "task": task, "rows": None, "at": now}
    try:
        rows = await asyncio.shield(task)
    except Exception:
        _human_list_cache.pop(key, None)
        raise
    if epoch == _human_list_cache_epoch:
        _human_list_cache[key] = {"epoch": epoch, "task": None, "rows": rows, "at": time.monotonic()}
    else:
        _human_list_cache.pop(key, None)
    if len(_human_list_cache) > 200:
        _human_list_cache.clear()
    return rows


_ttl_cache = {}


async def _ttl_single_flight(key, ttl, factory):
    """Compute an async result once and share it between overlapping or near-simultaneous requests.

    Any write that bumps the Human Work epoch (including messaging and notification
    writes) discards the stored result, so people never see stale data after a change.
    """
    now = time.monotonic()
    entry = _ttl_cache.get(key)
    if entry and entry["epoch"] == _human_list_cache_epoch:
        if entry["task"] is not None and not entry["task"].done():
            return await asyncio.shield(entry["task"])
        if entry["task"] is None and now - entry["at"] < ttl:
            return entry["value"]
    epoch = _human_list_cache_epoch
    task = asyncio.ensure_future(factory())
    _ttl_cache[key] = {"epoch": epoch, "task": task, "value": None, "at": now}
    try:
        value = await asyncio.shield(task)
    except BaseException:
        if (_ttl_cache.get(key) or {}).get("task") is task:
            _ttl_cache.pop(key, None)
        raise
    if epoch == _human_list_cache_epoch:
        _ttl_cache[key] = {"epoch": epoch, "task": None, "value": value, "at": time.monotonic()}
    elif (_ttl_cache.get(key) or {}).get("task") is task:
        _ttl_cache.pop(key, None)
    if len(_ttl_cache) > 500:
        _ttl_cache.clear()
    return value


# ---------------------------------------------------------------------------
# Sub-admin isolation. A sub-admin only reaches jobs they uploaded, and never
# sees which real worker did the work: workers appear as "Human Worker N" and AI
# agents as "Agent Worker N". The main admin is exempt from all of this.
# ---------------------------------------------------------------------------
_HUMAN_JOB_PATH_RE = re.compile(r"^/human-transcription/(?:admin/)?jobs/([^/]+)")
_HUMAN_SCOPED_PREFIXES = ("/human-transcription", "/api/notifications")
_human_alias_lock = asyncio.Lock()
_human_alias_cache = {"loaded_at": 0.0, "by_uid": {}, "needles": []}


def _human_token_identity(request):
    """Read uid and email from the bearer token without trusting it for access.

    It only decides whether extra restrictions apply; the route itself still
    verifies the token, so a forged token gains nothing."""
    header = request.headers.get("authorization") or ""
    if not header.lower().startswith("bearer "):
        return "", ""
    try:
        payload = header[7:].strip().split(".")[1]
        payload += "=" * (-len(payload) % 4)
        claims = json.loads(base64.urlsafe_b64decode(payload.encode()))
        return str(claims.get("user_id") or claims.get("uid") or claims.get("sub") or ""), str(claims.get("email") or "").strip().lower()
    except Exception:
        return "", ""


async def _human_worker_aliases(extra_uids=()):
    """Stable labels: each real worker keeps the same "Human Worker N" forever."""
    async with _human_alias_lock:
        cache = _human_alias_cache
        now = time.monotonic()
        stale = now - cache["loaded_at"] > 120
        if stale:
            try:
                alias_rows = await asyncio.to_thread(lambda: list(db.collection("human_worker_aliases").stream()))
                worker_rows = await asyncio.to_thread(lambda: list(db.collection("users").where(filter=FieldFilter("workerApproved", "==", True)).stream()))
            except Exception as exc:
                logger.warning("Could not load worker aliases: %s", exc)
                return cache["by_uid"], cache["needles"]
            by_uid = {row.id: int((row.to_dict() or {}).get("number") or 0) for row in alias_rows}
            people = {row.id: row.to_dict() or {} for row in worker_rows}
            for row in alias_rows:
                data = row.to_dict() or {}
                people.setdefault(row.id, {"name": data.get("name"), "email": data.get("email")})
            cache["_numbers"] = by_uid
            cache["_people"] = people
            cache["loaded_at"] = now
        numbers = cache.setdefault("_numbers", {})
        people = cache.setdefault("_people", {})
        wanted = set(str(uid) for uid in extra_uids if uid) | set(people)
        missing = sorted(uid for uid in wanted if not numbers.get(uid))
        next_number = max(numbers.values() or [0]) + 1
        for uid in missing:
            numbers[uid] = next_number
            person = people.get(uid) or {}
            try:
                await asyncio.to_thread(
                    db.collection("human_worker_aliases").document(uid).set,
                    {"number": next_number, "name": str(person.get("name") or person.get("displayName") or ""), "email": str(person.get("email") or "").lower(), "createdAt": firestore.SERVER_TIMESTAMP},
                )
            except Exception as exc:
                logger.warning("Could not save worker alias %s: %s", uid, exc)
            next_number += 1
        by_uid = {uid: f"Human Worker {number}" for uid, number in numbers.items()}
        needles = []
        for uid, person in people.items():
            label = by_uid.get(uid)
            if not label:
                continue
            for value in (person.get("name"), person.get("displayName"), person.get("full_name"), person.get("email")):
                value = str(value or "").strip()
                if len(value) >= 4:
                    needles.append((value.casefold(), label))
        needles.sort(key=lambda pair: len(pair[0]), reverse=True)
        cache["by_uid"], cache["needles"] = by_uid, needles
        return by_uid, needles


def _human_collect_worker_uids(node, found):
    if isinstance(node, dict):
        for key in ("worker_uid", "proofreader_uid"):
            if node.get(key):
                found.add(str(node[key]))
        if node.get("uid") and ("online" in node or "shift_status" in node):
            found.add(str(node["uid"]))
        for value in node.values():
            _human_collect_worker_uids(value, found)
    elif isinstance(node, list):
        for value in node:
            _human_collect_worker_uids(value, found)


_NAME_SWAP_MAX_CHARS = 20000


def _human_swap_names(value, needles):
    """Replace every worker name or email in a short string with its stable label, in one pass."""
    if not needles or not isinstance(value, str) or len(value) < 4 or len(value) > _NAME_SWAP_MAX_CHARS:
        return value
    pattern, mapping = _human_needle_regex(tuple(needles))
    return pattern.sub(lambda match: mapping.get(match.group(0).casefold(), match.group(0)), value)


@functools.lru_cache(maxsize=4)
def _human_needle_regex(needles):
    mapping = {}
    for needle, label in needles:
        mapping.setdefault(needle, label)
    pattern = re.compile("|".join(re.escape(needle) for needle in mapping), re.IGNORECASE)
    return pattern, mapping


def _human_anonymize_node(node, by_uid, needles):
    agent_ids = list(HUMAN_AI_AGENTS)
    if isinstance(node, dict):
        agent_id = node.get("ai_agent_id")
        if agent_id and "worker_name" in node and not node.get("worker_uid"):
            number = agent_ids.index(agent_id) + 1 if agent_id in agent_ids else 1
            node["worker_name"] = f"Agent Worker {number}"
            if "worker_email" in node:
                node["worker_email"] = ""
        for uid_key, name_key, email_key in (("worker_uid", "worker_name", "worker_email"), ("proofreader_uid", "proofreader_name", "proofreader_email")):
            uid = node.get(uid_key)
            if uid and str(uid) in by_uid:
                if name_key in node:
                    node[name_key] = by_uid[str(uid)]
                if email_key in node:
                    node[email_key] = ""
        if node.get("uid") and str(node["uid"]) in by_uid and ("online" in node or "shift_status" in node):
            node["name"] = by_uid[str(node["uid"])]
            for key in ("email", "phone", "displayName", "full_name"):
                if key in node:
                    node[key] = ""
        for key in ("last_auto_reassigned_worker_name", "last_assignment_takeback_worker_name"):
            if node.get(key):
                node[key] = "a human worker"
        for key, value in list(node.items()):
            if isinstance(value, str):
                node[key] = _human_swap_names(value, needles)
            else:
                node[key] = _human_anonymize_node(value, by_uid, needles)
        return node
    if isinstance(node, list):
        return [_human_anonymize_node(item, by_uid, needles) for item in node]
    if isinstance(node, str):
        return _human_swap_names(node, needles)
    return node


@app.middleware("http")
async def _human_subadmin_scope_middleware(request: Request, call_next):
    path = request.url.path
    if request.method == "OPTIONS" or not path.startswith(_HUMAN_SCOPED_PREFIXES):
        return await call_next(request)
    uid, email = _human_token_identity(request)
    if not email or not is_human_subadmin(email):
        return await call_next(request)
    match = _HUMAN_JOB_PATH_RE.match(path)
    if match:
        owner_uid, owner_email, found = await _human_job_owner_lookup(match.group(1))
        mine = (owner_uid and owner_uid == uid) or (not owner_uid and owner_email and owner_email == email)
        if found and not mine:
            headers = {}
            origin = request.headers.get("origin")
            if origin:
                headers = {"Access-Control-Allow-Origin": origin, "Vary": "Origin"}
            return JSONResponse({"detail": "This job was not found in your uploads."}, status_code=404, headers=headers)
    response = await call_next(request)
    if "application/json" not in str(response.headers.get("content-type") or "").lower():
        return response
    chunks = []
    async for chunk in response.body_iterator:
        chunks.append(chunk)
    body = b"".join(chunks)

    def _parse(raw):
        return json.loads(raw.decode("utf-8"))
    try:
        data = await asyncio.to_thread(_parse, body)
    except Exception:
        return Response(content=body, status_code=response.status_code, headers=dict(response.headers), media_type=response.media_type)
    try:
        uids = set()
        await asyncio.to_thread(_human_collect_worker_uids, data, uids)
        by_uid, needles = await _human_worker_aliases(uids)
        data = await asyncio.to_thread(_human_anonymize_node, data, by_uid, needles)
    except Exception:
        logger.exception("Sub-admin worker anonymisation failed; withholding the response")
        return JSONResponse({"detail": "This page could not be prepared. Please retry."}, status_code=503)
    headers = {key: value for key, value in response.headers.items() if key.lower() not in {"content-length", "content-type"}}
    return JSONResponse(data, status_code=response.status_code, headers=headers)


@app.get("/human-transcription/jobs")
async def human_list_jobs(request: Request, scope: str = "mine", owner: str = ""):
    actor = await _human_actor(request)
    owner_all = str(owner or "").strip().lower() == "all" and is_admin_user(actor.get("email") or "")
    if not db:
        return {"jobs": []}
    ref = db.collection(HUMAN_JOB_COLLECTION)
    available_scope = actor["role"] == "worker" and scope == "available"
    archived_scope = scope == "archived"
    if archived_scope and actor["role"] != "admin":
        raise HTTPException(status_code=403, detail="Admin access is required to view archived Human Work jobs.")
    worker_can_claim = False
    claim_block_reason = ""
    worker_active_assignment = False
    worker_available = (actor.get("profile") or {}).get("is_available") is True
    worker_rating_summary = {"average": None, "count": 0}
    worker_meets_rating = False
    worker_deadline_return_count = 0
    worker_claim_attempt_counts = {}
    worker_shift_status = None
    if actor["role"] == "worker":
        profile = actor.get("profile") or {}
        worker_deadline_return_count = max(0, int(profile.get("deadline_return_count") or 0))
        worker_rating_summary = await _human_worker_rating_summary(actor["uid"], profile)
        worker_meets_rating = (
            worker_rating_summary["average"] is not None
            and worker_rating_summary["average"] >= MIN_HUMAN_WORKER_RATING
        )
    if available_scope:
        qualification_cycle = str((actor.get("profile") or {}).get("worker_qualification_cycle") or "initial")
        attempt_rows = await asyncio.to_thread(lambda: list(
            db.collection(HUMAN_WORKER_ITEM_CLAIM_COLLECTION)
            .where(filter=FieldFilter("worker_uid", "==", actor["uid"]))
            .stream()
        ))
        for attempt in attempt_rows:
            attempt_data = attempt.to_dict() or {}
            if str(attempt_data.get("qualification_cycle") or "initial") != qualification_cycle:
                continue
            item_key = str(attempt_data.get("item_key") or "")
            if item_key:
                worker_claim_attempt_counts[item_key] = max(0, int(attempt_data.get("claim_count") or 0))
        snapshots_by_id = {}
        status_rows = await asyncio.gather(*[
            _human_cached_query(f"status:{status}", lambda status=status: list(ref.where(filter=FieldFilter("status", "==", status)).stream()))
            for status in ("approved", "split_assigned", "split_in_progress", "proofreading_assigned", "proofreading_in_progress")
        ])
        for rows in status_rows:
            snapshots_by_id.update({snapshot.id: snapshot for snapshot in rows})
        snapshots = list(snapshots_by_id.values())
        worker_active_assignment = await _human_worker_has_active_assignment(actor["uid"])
        # Expiry processing above can itself trigger the eleventh missed-deadline
        # return. Re-read the profile before exposing any Available Jobs rows.
        refreshed_profile = await _load_profile(actor["uid"])
        refreshed_profile = refreshed_profile or {}
        if refreshed_profile.get("workerApproved") is not True:
            raise HTTPException(
                status_code=403,
                detail="Your available-work access is paused. Please continue in the Training Room.",
            )
        refreshed_profile = await _human_shift_reconcile(actor["uid"], refreshed_profile)
        actor["profile"] = refreshed_profile
        worker_available = refreshed_profile.get("is_available") is True
        worker_deadline_return_count = max(0, int(refreshed_profile.get("deadline_return_count") or 0))
        _, current_shift = await _human_shift_current_record(actor["uid"])
        worker_shift_status = _human_shift_status_payload(actor["uid"], refreshed_profile, current_shift)
        worker_can_claim = worker_meets_rating and not worker_active_assignment and worker_shift_status["can_claim"]
        if not worker_meets_rating:
            average = worker_rating_summary["average"]
            claim_block_reason = (
                f"Your current average is {average:.2f}/5; a rating of at least 3.5/5 is required to see Available Jobs."
                if average is not None else
                "A rating of at least 3.5/5 is required to see Available Jobs. Ask an admin about a supervised starter assignment."
            )
        elif worker_active_assignment:
            claim_block_reason = "Finish your current assignment before claiming another."
        elif worker_shift_status and not worker_shift_status.get("can_claim"):
            claim_block_reason = worker_shift_status.get("message") or "Clock in during your scheduled shift or after an admin call-in."
    elif scope == "available":
        if (actor.get("profile") or {}).get("worker_retraining_required") is True:
            raise HTTPException(
                status_code=403,
                detail="Your available-work access is paused. Please continue in the Training Room.",
            )
        raise HTTPException(status_code=403, detail="Only approved workers can view available Human Work.")
    elif scope == "admin" and actor["role"] != "admin":
        raise HTTPException(status_code=403, detail="Admin access is required to view the Human Work queue.")
    elif archived_scope and actor["role"] == "admin":
        # Archived work is everything older than the dashboard window. Read only
        # that slice, newest first, instead of the whole collection.
        archive_cutoff = datetime.now(timezone.utc) - timedelta(days=HUMAN_JOB_DASHBOARD_RETENTION_DAYS)
        snapshots = await _human_cached_query("archived_jobs", lambda: list(
            ref.where(filter=FieldFilter("createdAt", "<", archive_cutoff - timedelta(hours=1)))
            .order_by("createdAt", direction=firestore.Query.DESCENDING).limit(400).stream()
        ))
    elif scope == "admin" and actor["role"] == "admin":
        # The live queue only shows work from the last few days. Reading just
        # that window keeps every poll fast no matter how much history exists.
        recent_cutoff = datetime.now(timezone.utc) - timedelta(days=HUMAN_JOB_DASHBOARD_RETENTION_DAYS, hours=1)
        snapshots = await _human_cached_query("recent_jobs", lambda: list(
            ref.where(filter=FieldFilter("createdAt", ">=", recent_cutoff))
            .order_by("createdAt", direction=firestore.Query.DESCENDING).stream()
        ))
    elif actor["role"] == "admin":
        snapshots = await _human_cached_query("all_jobs", lambda: list(ref.order_by("createdAt", direction=firestore.Query.DESCENDING).stream()))
    elif scope in {"assigned", "finished"} and actor["role"] != "worker":
        raise HTTPException(status_code=403, detail="Approved worker access is required to view assigned or finished jobs.")
    elif actor["role"] == "worker":
        # Keep the original single-worker query and add the split parent query.
        found = {}
        uid = actor["uid"]
        worker_rows = await asyncio.gather(
            _human_cached_query(f"w:{uid}", lambda: list(ref.where(filter=FieldFilter("worker_uid", "==", uid)).stream())),
            _human_cached_query(f"a:{uid}", lambda: list(ref.where(filter=FieldFilter("assigned_worker_uids", "array_contains", uid)).stream())),
            _human_cached_query(f"p:{uid}", lambda: list(ref.where(filter=FieldFilter("proofreader_uid", "==", uid)).stream())),
        )
        for rows in worker_rows:
            for snap in rows:
                found[snap.id] = snap
        snapshots = list(found.values())
    else:
        snapshots = await asyncio.to_thread(lambda: list(ref.where(filter=FieldFilter("client_uid", "==", actor["uid"])).stream()))
    jobs = []
    view_role = "human_ops_admin" if actor["role"] == "admin" and not is_admin_user(actor.get("email") or "") else actor["role"]
    for snap in snapshots:
        if available_scope and not worker_meets_rating:
            continue
        item = snap.to_dict() or {}
        item["id"] = snap.id
        if actor["role"] == "admin" and not _human_admin_can_see_job(actor, item, owner_all):
            continue
        is_archived = _human_job_dashboard_archived(item)
        if actor["role"] == "admin" and scope in {"admin", "archived"} and is_archived != archived_scope:
            continue
        item = await _human_check_expiry(snap.id, item)
        if available_scope:
            item_type = str(item.get("job_type") or "").strip().lower()
            if item_type == "letter_job":
                continue
            if _human_routing_blocks_workers(item):
                continue
            if item_type == "pdf_job" and (item.get("admin_uploaded") is not True or item.get("pdf_review")):
                continue
            if _human_is_split_job(item):
                if item.get("status") not in {"split_assigned", "split_in_progress", "proofreading_assigned", "proofreading_in_progress"}:
                    continue
                claimable_parts = [
                    {key: part.get(key) for key in ("id", "label", "index", "minutes", "start_seconds", "end_seconds")}
                    for part in (item.get("segments") or [])
                    if part.get("status") in {"available", "approved"}
                ]
                if not claimable_parts:
                    continue
                claimable_full_job = False
            else:
                if item.get("status") != "approved":
                    continue
                claimable_parts = []
                claimable_full_job = True
            # A worker can assess the listing but cannot read client files or
            # the AI draft until the claim transaction assigns the work.
            public_item = _human_available_public_for(
                item, actor.get("uid") or "", claimable_parts, claimable_full_job,
                worker_can_claim, claim_block_reason, worker_claim_attempt_counts,
            )
            jobs.append(public_item)
            continue
        if actor["role"] == "worker" and scope in {"assigned", "finished"}:
            assignment = _human_worker_segment(item.get("segments") or [], actor["uid"])
            is_proofreader = item.get("proofreader_uid") == actor["uid"]
            current_status = item.get("proofreader_status") if is_proofreader else (assignment.get("status") if assignment else item.get("status"))
            finished = {"submitted", "client_review", "client_approved", "released"}
            active = {"assigned", "in_progress"}
            if scope == "finished" and current_status not in finished:
                continue
            if scope != "finished" and current_status not in active:
                continue
        public_item = _human_public_for(item, view_role, actor.get("uid") or "")
        if actor["role"] == "admin":
            public_item["dashboard_archived"] = is_archived
        jobs.append(public_item)
    if actor["role"] == "worker":
        # The assigned/finished views also run expiry checks while serializing
        # jobs. Do not return a worker board if one of those checks caused lockout.
        latest_profile = await _load_profile(actor["uid"])
        latest_profile = await _human_shift_reconcile(actor["uid"], latest_profile or {})
        if latest_profile.get("workerApproved") is not True:
            raise HTTPException(
                status_code=403,
                detail="Your available-work access is paused. Please continue in the Training Room.",
            )
        worker_deadline_return_count = max(0, int(latest_profile.get("deadline_return_count") or 0))
        if worker_shift_status is None:
            _, current_shift = await _human_shift_current_record(actor["uid"])
            worker_shift_status = _human_shift_status_payload(actor["uid"], latest_profile, current_shift)
    jobs.sort(key=lambda item: str(item.get("createdAt") or ""), reverse=True)
    response = {"jobs": jobs}
    if actor["role"] == "worker":
        response["worker_rating_summary"] = worker_rating_summary
        response["worker_can_view_available"] = worker_meets_rating
        response["worker_active_assignment"] = worker_active_assignment
        response["worker_available"] = worker_available
        response["worker_can_claim"] = worker_can_claim
        response["worker_claim_block_reason"] = claim_block_reason
        response["worker_deadline_return_count"] = worker_deadline_return_count
        response["worker_deadline_warning"] = worker_deadline_return_count >= HUMAN_WORKER_DEADLINE_WARNING_RETURNS
        response["worker_shift_status"] = worker_shift_status
    return response


def _pdf_job_jpeg_bytes(image):
    image = ImageOps.exif_transpose(image).convert("RGB")
    max_pixels = 18_000_000
    if image.width * image.height > max_pixels:
        scale = (max_pixels / float(image.width * image.height)) ** 0.5
        image = image.resize((max(1, int(image.width * scale)), max(1, int(image.height * scale))), Image.Resampling.LANCZOS)
    output = BytesIO()
    image.save(output, format="JPEG", quality=90, optimize=True)
    return output.getvalue()


def _pdf_job_images_from_upload(filename, raw):
    original_name = os.path.basename(filename or "uploaded-image")[:180]
    safe_stem = re.sub(r"[^A-Za-z0-9._-]+", "_", os.path.splitext(original_name)[0])[:120] or "image"
    if original_name.lower().endswith(PDF_JOB_WORD_EXTENSIONS):
        try:
            raw = doc_tools.office_to_pdf_bytes(raw, original_name)
        except doc_tools.ConversionError as exc:
            raise HTTPException(status_code=400, detail=f"{original_name}: {exc}") from exc
        original_name = os.path.splitext(original_name)[0] + ".pdf"
    is_pdf = original_name.lower().endswith(".pdf") or raw[:5] == b"%PDF-"
    images = []
    if is_pdf:
        document = None
        try:
            document = pdfium.PdfDocument(raw)
            page_count = len(document)
            if page_count < 1:
                raise HTTPException(status_code=400, detail=f"{original_name} has no pages.")
            if page_count > PDF_JOB_MAX_PAGES_PER_FILE:
                raise HTTPException(status_code=413, detail=f"{original_name} has more than {PDF_JOB_MAX_PAGES_PER_FILE} pages.")
            for index in range(page_count):
                page = document[index]
                width, height = page.get_size()
                scale = min(1.75, (18_000_000 / max(float(width * height), 1.0)) ** 0.5)
                rendered = page.render(scale=max(0.5, scale)).to_pil()
                page_name = f"{safe_stem}-page-{index + 1:03d}.jpg"
                images.append({"name": page_name, "raw": _pdf_job_jpeg_bytes(rendered), "source_filename": original_name, "page_number": index + 1, "page_count": page_count})
        except HTTPException:
            raise
        except Exception as exc:
            logger.info("PDF Job upload could not be rendered (%s): %s", original_name, exc)
            raise HTTPException(status_code=400, detail=f"{original_name} could not be read as a PDF.") from exc
        finally:
            if document is not None:
                try:
                    document.close()
                except Exception:
                    logger.debug("PDFium document cleanup failed for %s", original_name)
        return images
    try:
        image = Image.open(BytesIO(raw))
        image.load()
        if image.width * image.height > 100_000_000:
            raise HTTPException(status_code=413, detail=f"{original_name} has too many image pixels.")
        images.append({"name": f"{safe_stem}.jpg", "raw": _pdf_job_jpeg_bytes(image), "source_filename": original_name, "page_number": 1, "page_count": 1})
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"{original_name} is not a supported PDF or image file.") from exc
    return images


@app.post("/human-transcription/admin/pdf-jobs")
async def human_admin_create_pdf_jobs(request: Request, files: List[UploadFile] = File(...), attachments: List[UploadFile] = File(default=[]), instructions: str = Form(""), category: str = Form("pdf")):
    actor = await _human_actor(request)
    if str(actor.get("email") or "").lower() not in PDF_JOB_ADMIN_EMAILS:
        raise HTTPException(status_code=403, detail="PDF Jobs and Text Messages upload is available only to the admin team.")
    is_text_messages = str(category or "pdf").strip().lower() == "text_messages"
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    if not files:
        raise HTTPException(status_code=400, detail="Choose at least one PDF or image file.")
    if len(files) > 50:
        raise HTTPException(status_code=413, detail="Upload no more than 50 source files at once.")
    created_jobs, stored_paths = [], []
    extra_files = []
    for extra in [item for item in (attachments or []) if getattr(item, "filename", "")][:6]:
        extra_name = os.path.basename(extra.filename or "reference")[:180]
        if doc_tools.file_extension(extra_name) not in PDF_JOB_ATTACHMENT_EXTENSIONS:
            raise HTTPException(status_code=400, detail=f"{extra_name} is not a supported reference file. Use PDF, Word, text, image or audio files.")
        extra_raw = await extra.read(PDF_JOB_MAX_UPLOAD_BYTES + 1)
        if not extra_raw:
            raise HTTPException(status_code=400, detail=f"{extra_name} is empty.")
        if len(extra_raw) > PDF_JOB_MAX_UPLOAD_BYTES:
            raise HTTPException(status_code=413, detail=f"{extra_name} is larger than 25 MB.")
        extra_files.append((extra_name, extra_raw, extra.content_type or "application/octet-stream"))
    admin_note = str(instructions or "").strip()[:4000]
    job_instructions = (TEXT_MESSAGES_DEFAULT_INSTRUCTION if is_text_messages else PDF_JOB_DEFAULT_INSTRUCTION) + (f"\n\n{admin_note}" if admin_note else "")
    source_filenames = [os.path.basename(str(getattr(item, "filename", "") or "image"))[:180] for item in files]
    first_source_name = source_filenames[0] if source_filenames else "images"
    first_source_stem = os.path.splitext(first_source_name)[0] or "images"
    upload_batch_id = uuid.uuid4().hex
    upload_batch_name = first_source_name if len(source_filenames) == 1 else f"{first_source_name} + {len(source_filenames) - 1} more"
    upload_download_name = first_source_stem if len(source_filenames) == 1 else f"{first_source_stem}-combined"
    upload_page_number = 0

    async def rollback():
        bucket = _human_bucket()
        for path in stored_paths:
            if bucket:
                try:
                    await asyncio.to_thread(bucket.blob(path).delete)
                except Exception:
                    logger.warning("Could not remove failed PDF Job upload file %s", path)
        for job_id in created_jobs:
            try:
                await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).delete)
            except Exception:
                logger.warning("Could not remove failed PDF Job record %s", job_id)

    images_per_job = TEXT_MESSAGES_IMAGES_PER_JOB if is_text_messages else 1
    pending_group = []

    async def create_group(group):
        """Create one worker job from one image (PDF jobs) or up to two images (Text Messages)."""
        nonlocal upload_page_number
        upload_page_number += 1
        job_id = uuid.uuid4().hex
        batch_id = group[0][0]
        image_metas = []
        for position, (_, rendered) in enumerate(group, start=1):
            meta = await asyncio.to_thread(_human_store_raw_bytes, job_id, rendered["name"], rendered["raw"], "image/jpeg", "pdf")
            stored_paths.append(meta["storage_path"])
            meta.update({key: rendered[key] for key in ("source_filename", "page_number", "page_count")})
            image_metas.append(meta)
        image_meta = image_metas[0]
        reference_meta = []
        for extra_name, extra_raw, extra_type in extra_files:
            meta = await asyncio.to_thread(_human_store_raw_bytes, job_id, extra_name, extra_raw, extra_type, "instructions")
            stored_paths.append(meta["storage_path"])
            reference_meta.append(meta)
        now = firestore.SERVER_TIMESTAMP
        job = {
            "job_type": "pdf_job", "source_type": "text_messages" if is_text_messages else "pdf_job", "job_category": "text_messages" if is_text_messages else "pdf",
            "pdf_batch_id": batch_id, "pdf_upload_batch_id": upload_batch_id,
            "pdf_upload_batch_name": upload_batch_name, "pdf_upload_download_name": upload_download_name,
            "pdf_upload_page_number": upload_page_number, "status": "approved", "admin_uploaded": True, "routing_status": "pending",
            "tat_seconds": human_image_tat_seconds(len(group)), "instruction_attachments": reference_meta,
            "createdAt": now, "updatedAt": now,
            "seconds": 180, "minutes": 1,
            "turnaround": "standard", "difficulty": "standard", "service": "text_messages_transcription" if is_text_messages else "pdf_transcription", "formatting": "standard",
            "timestamps": False, "speakers": "1", "speaker_labels": False,
            "instructions": job_instructions,
            "pdf_image": image_meta, "audio": None,
            "quote_credits": 0,
            "quote": {"credits": 0, "minutes": 1, "transcriber_payout_kes_per_minute": TEXT_MESSAGES_WORKER_PAY_KES if is_text_messages else PDF_JOB_WORKER_PAY_KES, "worker_fixed_amount_kes": TEXT_MESSAGES_WORKER_PAY_KES if is_text_messages else PDF_JOB_WORKER_PAY_KES},
            "worker_uid": None, "worker_email": None, "worker_name": None,
            "worker_minutes": 1, "worker_amount_kes": None, "worker_gross_amount_kes": None,
            "worker_deduction_kes": 0, "worker_deduction_reason": "",
            "payout_status": None, "payout_period_id": None, "workerPaymentStatus": None,
            "assigned_worker_uids": [], "transcript": "", "worker_notes": "", "final_attachment": None,
            "client_uid": None, "client_email": "",
            "created_by_uid": actor["uid"], "created_by_email": str(actor.get("email") or "").strip().lower(),
        }
        if len(image_metas) > 1:
            job["pdf_images"] = image_metas
            job["pdf_image_count"] = len(image_metas)
        await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).set, job)
        created_jobs.append(job_id)

    try:
        image_count = 0
        for upload in files:
            raw = await upload.read(PDF_JOB_MAX_UPLOAD_BYTES + 1)
            if not raw:
                raise HTTPException(status_code=400, detail=f"{upload.filename or 'A selected file'} is empty.")
            if len(raw) > PDF_JOB_MAX_UPLOAD_BYTES:
                raise HTTPException(status_code=413, detail=f"{upload.filename} is larger than 25 MB.")
            rendered_images = await asyncio.to_thread(_pdf_job_images_from_upload, upload.filename, raw)
            batch_id = uuid.uuid4().hex
            image_count += len(rendered_images)
            if image_count > PDF_JOB_MAX_IMAGES_PER_BATCH:
                raise HTTPException(status_code=413, detail=f"A single upload batch can contain up to {PDF_JOB_MAX_IMAGES_PER_BATCH} image pages.")
            for rendered in rendered_images:
                pending_group.append((batch_id, rendered))
                if len(pending_group) >= images_per_job:
                    await create_group(pending_group)
                    pending_group = []
        if pending_group:
            await create_group(pending_group)
        return {"created_count": len(created_jobs), "jobs": created_jobs, "upload_batch_id": upload_batch_id, "worker_pay_kes_per_image": TEXT_MESSAGES_WORKER_PAY_KES if is_text_messages else PDF_JOB_WORKER_PAY_KES, "tat_minutes": PDF_JOB_TAT_SECONDS // 60}
    except HTTPException:
        await rollback()
        raise
    except Exception as exc:
        await rollback()
        logger.exception("PDF Jobs batch upload failed for %s", actor.get("email"))
        raise HTTPException(status_code=500, detail="The PDF Jobs upload could not be completed. Please retry the batch.") from exc


def _human_pdf_job_image_metas(job):
    """Every source image of one image job: one for PDF jobs, up to two for Text Messages."""
    metas = [meta for meta in (job.get("pdf_images") or []) if (meta or {}).get("storage_path")]
    if metas:
        return metas
    single = job.get("pdf_image") or {}
    return [single] if single.get("storage_path") else []


def _pdf_page_has_text(item):
    for part in (item.get("segments") or []):
        if (part or {}).get("status") == "submitted" and str((part or {}).get("transcript") or "").strip():
            return True
    return bool(str(item.get("transcript") or "").strip() or (item.get("final_attachment") or {}).get("storage_path"))


def _human_pdf_upload_order_key(job, job_id=""):
    """Return the original upload order, falling back to legacy source-page order."""
    image = job.get("pdf_image") or {}
    for value in (job.get("pdf_upload_page_number"), image.get("page_number")):
        try:
            number = int(value or 0)
        except (TypeError, ValueError):
            continue
        if number > 0:
            return number, str(job_id)
    return 0, str(job_id)


def _human_pdf_same_upload_batch(first, other):
    first_id = str(first.get("pdf_upload_batch_id") or "").strip()
    other_id = str(other.get("pdf_upload_batch_id") or "").strip()
    return bool(first_id) and first_id == other_id


def _human_pdf_same_source_file(first, other):
    first_id = str(first.get("pdf_batch_id") or "").strip()
    other_id = str(other.get("pdf_batch_id") or "").strip()
    if first_id or other_id:
        return bool(first_id) and first_id == other_id
    first_name = str((first.get("pdf_image") or {}).get("source_filename") or "")
    other_name = str((other.get("pdf_image") or {}).get("source_filename") or "")
    return bool(first_name) and first_name == other_name


async def _pdf_page_draft_text(item):
    """The best typed text for one page job: AI/worker segment, typed transcript, then the attached Word file."""
    texts = [str((part or {}).get("transcript") or "").strip() for part in (item.get("segments") or []) if (part or {}).get("status") == "submitted"]
    texts = [text for text in texts if text]
    if texts:
        return "\n\n".join(texts)
    typed = str(item.get("transcript") or "").strip()
    if typed:
        return typed
    attachment = item.get("final_attachment") or {}
    bucket = _human_bucket()
    if attachment.get("storage_path") and bucket is not None:
        try:
            raw = await asyncio.to_thread(bucket.blob(attachment["storage_path"]).download_as_bytes)
            read = read_attachment(str(attachment.get("name") or "file"), raw)
            if read.get("kind") == "text":
                return str(read.get("text") or "").strip()
        except Exception as exc:
            logger.warning("Could not read an attached page file for a whole-file review: %s", exc)
    return ""


@app.post("/human-transcription/admin/pdf-jobs/file-review")
async def human_admin_create_file_review(request: Request):
    """Combine every finished page of one PDF/Text Messages file into one whole-file review job."""
    actor = await _human_actor(request)
    if str(actor.get("email") or "").lower() not in PDF_JOB_ADMIN_EMAILS:
        raise HTTPException(status_code=403, detail="Whole-file review is available only to the admin team.")
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    payload = await request.json()
    ids = list(dict.fromkeys(str(item) for item in ((payload or {}).get("job_ids") or [])))
    if not ids:
        raise HTTPException(status_code=400, detail="Choose at least one completed image job for review.")
    if len(ids) > 60:
        raise HTTPException(status_code=413, detail="Whole-image review currently supports up to 60 images at a time.")
    requested_upload_batch_id = str((payload or {}).get("upload_batch_id") or "").strip()[:120]
    pages = []
    for job_id in ids:
        pages.append((job_id, await _human_job(job_id)))
    first = pages[0][1]
    category = str(first.get("job_category") or "pdf")
    for job_id, item in pages:
        same_group = (
            _human_pdf_same_upload_batch(first, item)
            and str(first.get("pdf_upload_batch_id") or "").strip() == requested_upload_batch_id
            if requested_upload_batch_id
            else _human_pdf_same_source_file(first, item)
        )
        if str(item.get("job_type") or "").lower() != "pdf_job" or item.get("pdf_review") or not same_group or str(item.get("job_category") or "pdf") != category:
            raise HTTPException(status_code=409, detail="Every page must come from the same upload batch or source file.")
    pages.sort(key=lambda entry: _human_pdf_upload_order_key(entry[1], entry[0]))
    review_key = ",".join(job_id for job_id, _ in pages)
    existing = await asyncio.to_thread(lambda: list(db.collection(HUMAN_JOB_COLLECTION).where(filter=FieldFilter("pdf_review_key", "==", review_key)).limit(1).stream()))
    if existing:
        raise HTTPException(status_code=409, detail="A whole-file review job already exists for this file.")
    page_texts, missing = [], []
    for job_id, item in pages:
        text = await _pdf_page_draft_text(item)
        if not text:
            missing.append(str(((item.get("pdf_image") or {}).get("page_number")) or "?"))
        page_texts.append(text)
    if missing:
        raise HTTPException(status_code=409, detail="These pages have no transcript yet: " + ", ".join(missing) + ". Finish every page before starting the whole-file review.")
    source_image = first.get("pdf_image") or {}
    source_name = str(
        (first.get("pdf_upload_batch_name") if requested_upload_batch_id else "")
        or source_image.get("source_filename") or "file"
    )
    new_id = uuid.uuid4().hex
    bucket = _human_bucket()
    stored_paths = []
    try:
        page_metas = []
        page_image_hashes = []
        review_page_texts = []
        total_images = sum(len(_human_pdf_job_image_metas(item)) or 1 for _, item in pages)
        index = 0
        for (job_id, item), job_text in zip(pages, page_texts):
            for position, image in enumerate(_human_pdf_job_image_metas(item) or [item.get("pdf_image") or {}]):
                index += 1
                raw = await asyncio.to_thread(bucket.blob(image["storage_path"]).download_as_bytes)
                page_image_hashes.append(hashlib.sha256(raw).hexdigest())
                meta = await asyncio.to_thread(_human_store_raw_bytes, new_id, image.get("name") or f"page-{index}.jpg", raw, image.get("content_type") or "image/jpeg", "pdf")
                stored_paths.append(meta["storage_path"])
                meta.update({"source_filename": source_name, "page_number": index, "page_count": total_images})
                page_metas.append(meta)
                # A two-image job has one draft; it sits on the first image's page.
                review_page_texts.append(job_text if position == 0 else "")
        page_texts = review_page_texts
        reference_meta = []
        for ref_meta in (first.get("instruction_attachments") or []):
            ref_raw = await asyncio.to_thread(bucket.blob(ref_meta["storage_path"]).download_as_bytes)
            copy = await asyncio.to_thread(_human_store_raw_bytes, new_id, ref_meta.get("name") or "reference", ref_raw, ref_meta.get("content_type") or "application/octet-stream", "instructions")
            stored_paths.append(copy["storage_path"])
            reference_meta.append(copy)
        is_text_messages = category == "text_messages"
        combined = "\n\n".join(text for text in page_texts if text)
        combined = _human_collapse_duplicate_image_page_blocks(combined, page_image_hashes, page_texts)
        pay = PDF_JOB_REVIEW_PAY_KES_PER_PAGE * len(page_metas)
        tat_seconds = human_image_tat_seconds(len(page_metas))
        now = firestore.SERVER_TIMESTAMP
        job = {
            "job_type": "pdf_job", "source_type": "text_messages" if is_text_messages else "pdf_job",
            "job_category": category,
            "pdf_batch_id": "review-" + (requested_upload_batch_id or str(first.get("pdf_batch_id") or "") or new_id),
            "status": "approved",
            "pdf_review": {
                "source_job_ids": [job_id for job_id, _ in pages], "page_count": len(page_metas),
                "page_texts": page_texts, "source_filename": source_name,
                "source_upload_batch_id": requested_upload_batch_id,
            },
            "pdf_review_key": review_key,
            "tat_seconds": tat_seconds, "instruction_attachments": reference_meta, "createdAt": now, "updatedAt": now,
            "seconds": 180, "minutes": 1, "turnaround": "standard", "difficulty": "standard",
            "service": "text_messages_review" if is_text_messages else "pdf_review", "formatting": "standard",
            "timestamps": False, "speakers": "1", "speaker_labels": False,
            "instructions": str(first.get("instructions") or "") + "\n\nWHOLE-FILE REVIEW: the text below was assembled from the finished pages. Check it against every page image and all guidelines and instructions, correct any errors, make names, labels and formatting consistent across the whole file, then submit the complete final transcript.",
            "pdf_image": {**page_metas[0], "name": f"Whole-file review - {source_name}"}, "pdf_images": page_metas, "audio": None,
            "quote_credits": 0,
            "quote": {"credits": 0, "minutes": 1, "transcriber_payout_kes_per_minute": pay, "worker_fixed_amount_kes": pay},
            "worker_uid": None, "worker_email": None, "worker_name": None, "worker_minutes": 1, "worker_amount_kes": None,
            "worker_gross_amount_kes": None, "worker_deduction_kes": 0, "worker_deduction_reason": "",
            "payout_status": None, "payout_period_id": None, "workerPaymentStatus": None,
            "assigned_worker_uids": [], "transcript": combined[:1000000], "transcript_html": _sanitize_editor_html(_review_text_to_html(combined[:1000000])),
            "worker_notes": "", "final_attachment": None, "client_uid": None, "client_email": "",
        }
        await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(new_id).set, job)
    except HTTPException:
        raise
    except Exception as exc:
        for path in stored_paths:
            try:
                await asyncio.to_thread(bucket.blob(path).delete)
            except Exception:
                pass
        logger.exception("Whole-file review could not be created")
        raise HTTPException(status_code=500, detail="The whole-file review could not be created. Please try again.") from exc
    return {"job_id": new_id, "pages": len(page_metas), "worker_pay_kes": pay, "tat_minutes": tat_seconds // 60}


@app.get("/human-transcription/admin/pdf-jobs")
async def human_admin_list_pdf_jobs(request: Request):
    actor = await _human_actor(request)
    if str(actor.get("email") or "").lower() not in PDF_JOB_ADMIN_EMAILS:
        raise HTTPException(status_code=403, detail="PDF Jobs and Text Messages are available only to the admin team.")
    if not db:
        return {"jobs": []}
    snapshots = await asyncio.to_thread(lambda: list(db.collection(HUMAN_JOB_COLLECTION).where(filter=FieldFilter("job_type", "==", "pdf_job")).stream()))
    jobs = []
    for snapshot in snapshots:
        item = snapshot.to_dict() or {}
        if _human_job_dashboard_archived(item) or not _human_admin_can_see_job(actor, item):
            continue
        image = item.get("pdf_image") or {}
        jobs.append({
            "id": snapshot.id, "name": image.get("name") or image.get("source_filename") or "Image job",
            "source_filename": image.get("source_filename") or "", "page_number": image.get("page_number") or 1,
            "page_count": image.get("page_count") or 1, "image_count": max(1, len(_human_pdf_job_image_metas(item))), "status": item.get("status") or "approved",
            "worker_name": item.get("worker_name") or "", "worker_email": item.get("worker_email") or "",
            "worker_uid": item.get("worker_uid") or "",
            "ai_agent_status": item.get("ai_agent_status") or "",
            "ai_agent_name": item.get("ai_agent_name") or "",
            "ai_agent_error": item.get("ai_agent_error") or "",
            "ai_agent_segment_id": next((str(part.get("id") or "") for part in (item.get("segments") or []) if part.get("ai_agent_id") in HUMAN_IMAGE_AGENT_IDS), ""),
            "category": item.get("job_category") or "pdf", "batch_id": item.get("pdf_batch_id") or "",
            "upload_batch_id": item.get("pdf_upload_batch_id") or "",
            "upload_batch_name": item.get("pdf_upload_batch_name") or image.get("source_filename") or image.get("name") or "Image upload",
            "upload_download_name": item.get("pdf_upload_download_name") or image.get("source_filename") or image.get("name") or "image-upload",
            "upload_page_number": item.get("pdf_upload_page_number") or image.get("page_number") or 1,
            "has_text": bool(_pdf_page_has_text(item)), "is_review": bool(item.get("pdf_review")),
            "review_of": list((item.get("pdf_review") or {}).get("source_job_ids") or []),
            "review_upload_batch_id": str((item.get("pdf_review") or {}).get("source_upload_batch_id") or ""),
            "ai_agent_model_ids": item.get("ai_agent_model_ids") or [],
            "reference_files": len(item.get("instruction_attachments") or []),
            "deadline_at": _human_iso(item.get("deadlineAt")),
            "worker_amount_kes": int(item.get("worker_amount_kes") or 0),
            "created_at": _human_iso(item.get("createdAt")), "submitted_at": _human_iso(item.get("workerCompletedAt")),
        })
    jobs.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    return {"jobs": jobs[:500], "worker_pay_kes_per_image": PDF_JOB_WORKER_PAY_KES, "tat_minutes": PDF_JOB_TAT_SECONDS // 60}


@app.get("/human-transcription/admin/pdf-jobs/recent-batches")
async def human_admin_recent_pdf_batches(request: Request, category: str = ""):
    """Small list of recent image uploads so the upload tabs can offer the combined PDF download."""
    actor = await _human_actor(request)
    if str(actor.get("email") or "").strip().lower() not in PDF_JOB_ADMIN_EMAILS:
        raise HTTPException(status_code=403, detail="Image batch downloads are available only to the admin team.")
    if not db:
        return {"batches": []}
    wanted = "text_messages" if str(category or "").strip().lower() in {"text_messages", "text"} else ("pdf" if str(category or "").strip().lower() == "pdf" else "")
    snapshots = await asyncio.to_thread(lambda: list(db.collection(HUMAN_JOB_COLLECTION).where(filter=FieldFilter("job_type", "==", "pdf_job")).stream()))
    batches = {}
    for snapshot in snapshots:
        item = snapshot.to_dict() or {}
        if item.get("pdf_review") or _human_job_dashboard_archived(item) or not _human_admin_can_see_job(actor, item):
            continue
        job_category = item.get("job_category") or "pdf"
        if wanted and job_category != wanted:
            continue
        key = str(item.get("pdf_upload_batch_id") or item.get("pdf_batch_id") or "")
        if not key:
            continue
        image = item.get("pdf_image") or {}
        entry = batches.setdefault(key, {
            "batch_id": key, "category": job_category, "image_count": 0, "job_count": 0,
            "name": item.get("pdf_upload_batch_name") or image.get("source_filename") or "Image upload",
            "download_name": item.get("pdf_upload_download_name") or image.get("source_filename") or "image-upload",
            "created_at": "",
        })
        entry["image_count"] += max(1, len(_human_pdf_job_image_metas(item)))
        entry["job_count"] += 1
        created = _human_iso(item.get("createdAt")) or ""
        if created > entry["created_at"]:
            entry["created_at"] = created
    ordered = sorted(batches.values(), key=lambda entry: entry["created_at"], reverse=True)
    return {"batches": ordered[:15]}


@app.get("/human-transcription/admin/pdf-jobs/batches/{batch_id}/download")
async def human_admin_download_pdf_batch(batch_id: str, request: Request):
    """Build one ordered PDF from the privately stored source pages in an upload batch."""
    actor = await _human_actor(request)
    if str(actor.get("email") or "").strip().lower() not in PDF_JOB_ADMIN_EMAILS:
        raise HTTPException(status_code=403, detail="PDF batch downloads are available only to the admin team.")
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    batch_key = str(batch_id)[:120]
    snapshots = await asyncio.to_thread(lambda: list(
        db.collection(HUMAN_JOB_COLLECTION)
        .where(filter=FieldFilter("pdf_upload_batch_id", "==", batch_key))
        .stream()
    ))
    # Older jobs used one batch ID per original PDF/image file. Keep their
    # existing download links working while new uploads share one ID across
    # every image selected in the same admin submission.
    if not snapshots:
        snapshots = await asyncio.to_thread(lambda: list(
            db.collection(HUMAN_JOB_COLLECTION)
            .where(filter=FieldFilter("pdf_batch_id", "==", batch_key))
            .stream()
        ))
    pages = [(snap.id, snap.to_dict() or {}) for snap in snapshots]
    pages = [(job_id, job) for job_id, job in pages if job.get("job_type") == "pdf_job" and not job.get("pdf_review")]
    if not pages:
        raise HTTPException(status_code=404, detail="The uploaded image batch was not found.")
    pages.sort(key=lambda item: _human_pdf_upload_order_key(item[1], item[0]))
    if len(pages) > 100:
        raise HTTPException(status_code=409, detail="The upload contains too many images to safely combine into one PDF.")
    source_names = list(dict.fromkeys(
        str((job.get("pdf_image") or {}).get("source_filename") or "") for _, job in pages
        if str((job.get("pdf_image") or {}).get("source_filename") or "").strip()
    ))
    bucket = _human_bucket()
    if bucket is None:
        raise HTTPException(status_code=503, detail="Private file storage is not ready yet.")
    page_images = []
    try:
        for job_id, job in pages:
            for meta in (_human_pdf_job_image_metas(job) or [job.get("pdf_image") or {}]):
                path = str((meta or {}).get("storage_path") or "")
                if not path.startswith(f"human-workflow/{job_id}/pdf/"):
                    raise HTTPException(status_code=403, detail="A source image does not belong to this upload batch.")
                raw = await asyncio.to_thread(bucket.blob(path).download_as_bytes)
                with Image.open(BytesIO(raw)) as image:
                    image.load()
                    page_images.append(image.convert("RGB"))
        if not page_images:
            raise HTTPException(status_code=404, detail="No source pages were available to combine.")
        output = BytesIO()
        page_images[0].save(output, format="PDF", save_all=True, append_images=page_images[1:], resolution=150)
        filename = next((
            str(job.get("pdf_upload_download_name") or "").strip()
            for _, job in pages if str(job.get("pdf_upload_download_name") or "").strip()
        ), "")
        if not filename:
            filename = os.path.splitext(source_names[0])[0] if len(source_names) == 1 else "combined-images"
        filename = os.path.splitext(os.path.basename(filename))[0] or "combined-images"
        safe_name = re.sub(r"[^A-Za-z0-9._-]+", "_", filename).strip("._-") or "combined-images"
        return Response(
            content=output.getvalue(), media_type="application/pdf",
            headers={"Content-Disposition": f'attachment; filename="{safe_name}.pdf"', "Cache-Control": "private, no-store"},
        )
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("Could not create admin PDF download for batch %s", batch_id)
        raise HTTPException(status_code=500, detail="The source pages could not be combined into a PDF.") from exc
    finally:
        for image in page_images:
            try:
                image.close()
            except Exception:
                pass


@app.post("/human-transcription/admin/letter-jobs")
async def human_admin_create_letter_job(
    request: Request,
    audio: UploadFile = File(...),
    attachments: List[UploadFile] = File(default=[]),
    instructions: str = Form(""),
    title: str = Form(""),
    seconds: float = Form(0),
):
    actor = await _human_actor(request)
    email = str(actor.get("email") or "").strip().lower()
    if email not in LETTER_JOB_ADMIN_EMAILS:
        raise HTTPException(status_code=403, detail="Letter Jobs are available only to the admin team.")
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    if not audio or not audio.filename:
        raise HTTPException(status_code=400, detail="Choose the complete dictated letter recording.")
    if os.path.splitext(audio.filename)[1].lower().lstrip(".") not in LETTER_AUDIO_EXTENSIONS:
        raise HTTPException(status_code=400, detail="Use a supported audio/video recording such as MP3, WAV, M4A, MP4, or WebM.")
    try:
        duration = float(seconds or 0)
    except (TypeError, ValueError):
        duration = 0
    if not math.isfinite(duration) or duration <= 0:
        raise HTTPException(status_code=400, detail="The recording duration could not be read. Enter its length in seconds.")
    if len([item for item in (attachments or []) if getattr(item, "filename", "")]) > 6:
        raise HTTPException(status_code=413, detail="Attach no more than six letter reference files.")
    admin_note = str(instructions or "").strip()
    if len(admin_note) > 12000:
        raise HTTPException(status_code=413, detail="Letter instructions must be 12,000 characters or fewer.")
    job_id = uuid.uuid4().hex
    stored_paths = []
    try:
        audio_meta = await _human_store_upload(job_id, audio, "audio")
        if audio_meta and audio_meta.get("storage_path"):
            stored_paths.append(audio_meta["storage_path"])
        attachment_meta = []
        total_reference_bytes = 0
        for item in [upload for upload in (attachments or []) if getattr(upload, "filename", "")]:
            name = os.path.basename(item.filename or "reference")[:180]
            extension = os.path.splitext(name)[1].lower().lstrip(".")
            if extension not in PDF_JOB_ATTACHMENT_EXTENSIONS:
                raise HTTPException(status_code=400, detail=f"{name} is not a supported reference file. Use PDF, Word, text, image, or audio files.")
            raw = await item.read(MAX_ATTACHMENT_BYTES + 1)
            if not raw:
                raise HTTPException(status_code=400, detail=f"{name} is empty.")
            if len(raw) > MAX_ATTACHMENT_BYTES:
                raise HTTPException(status_code=413, detail=f"{name} is larger than 20 MB.")
            total_reference_bytes += len(raw)
            if total_reference_bytes > 50000000:
                raise HTTPException(status_code=413, detail="Letter reference files may total no more than 50 MB.")
            await item.seek(0)
            meta = await _human_store_upload(job_id, item, "instructions")
            attachment_meta.append(meta)
            if meta and meta.get("storage_path"):
                stored_paths.append(meta["storage_path"])
        rate = await _get_human_transcriber_rate()
        quote = human_credit_quote(duration, transcriber_rate_kes=rate)
        safe_title = str(title or "").strip()[:180] or os.path.basename(audio.filename or "Letter Job")
        now = firestore.SERVER_TIMESTAMP
        job = {
            "client_uid": actor["uid"], "client_email": email,
            "created_by_uid": actor["uid"], "created_by_email": str(email or "").strip().lower(),
            "status": "approved", "createdAt": now, "updatedAt": now, "admin_uploaded": True,
            "job_name": safe_title, "job_type": "letter_job", "source_type": "letter_job", "job_category": "letter",
            "seconds": duration, "minutes": quote["minutes"], "turnaround": "standard", "difficulty": "standard",
            "service": "standard", "formatting": "standard", "timestamps": False, "speakers": "1-2",
            "speaker_labels": False,
            "instructions": admin_note,
            "audio": audio_meta, "instruction_attachments": attachment_meta,
            "quote": quote, "quote_credits": 0, "credits_charged": 0,
            "worker_uid": None, "worker_email": None, "worker_name": None,
            "transcript": "", "transcript_html": "", "worker_notes": "", "final_attachment": None,
            "admin_feedback": "", "worker_rating": None, "releasedAt": None,
            "assignedAt": None, "deadlineAt": None, "tat_seconds": None,
            "workerCompletedAt": None, "worker_minutes": None, "worker_amount_kes": None,
            "payout_status": None, "payout_period_id": None, "workerPaymentStatus": None, "workerPaidAt": None,
            "split_mode": "single", "segments": [], "assigned_worker_uids": [],
            "proofreader_uid": None, "proofreader_email": None, "proofreader_name": None, "proofreader_status": None,
            "letter_guidelines": _human_letter_guidelines(),
            "letter_agent_status": "available", "letter_agent_id": None, "letter_agent_name": None,
            "letter_agent_model_ids": [], "letter_agent_run_id": None, "letter_agent_error": "",
            "letter_ai_review_status": "not_started", "letter_ai_review_error": "",
            "letter_ai_review_attachment": None,
        }
        job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
        await asyncio.to_thread(job_ref.set, job)
        saved = await asyncio.to_thread(job_ref.get)
        result = saved.to_dict() or job
        result["id"] = job_id
        await _notify_human_admins(
            f"letter-job-created:{job_id}", "job_request", "A new Letter Job is ready",
            "Assign the complete letter to one worker or the Letter Agent.", route="human_ops", job_id=job_id, requires_action=True,
        )
        return {"job": _human_public_for(result, "admin", actor.get("uid") or "")}
    except Exception:
        bucket = _human_bucket()
        if bucket:
            for path in stored_paths:
                try:
                    await asyncio.to_thread(bucket.blob(path).delete)
                except Exception:
                    logger.warning("Could not clean up failed Letter Job upload %s", path)
        raise


@app.post("/human-transcription/admin/audio-jobs")
async def human_admin_create_audio_job(
    request: Request,
    audio: UploadFile = File(...),
    attachments: List[UploadFile] = File(default=[]),
    template_file: Optional[UploadFile] = File(default=None),
    instructions: str = Form(""),
    title: str = Form(""),
    seconds: float = Form(0),
    category: str = Form("general"),
):
    """Create internal General or Template work, immediately available to eligible workers."""
    actor = await _human_actor(request)
    if str(actor.get("email") or "").strip().lower() not in LETTER_JOB_ADMIN_EMAILS:
        raise HTTPException(status_code=403, detail="General Jobs and Template Jobs are available only to the admin team.")
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    job_category = str(category or "general").strip().lower()
    if job_category not in {"general", "template"}:
        raise HTTPException(status_code=400, detail="Choose General Jobs or Template Jobs.")
    template_name = os.path.basename(getattr(template_file, "filename", "") or "")
    template_raw = b""
    if job_category == "template":
        if not template_name or os.path.splitext(template_name)[1].lower() != ".docx":
            raise HTTPException(status_code=400, detail="A Template Job requires exactly one job-specific .docx template.")
        template_raw = await template_file.read(MAX_ATTACHMENT_BYTES + 1)
        if not template_raw:
            raise HTTPException(status_code=400, detail="The job-specific .docx template is empty.")
        if len(template_raw) > MAX_ATTACHMENT_BYTES:
            raise HTTPException(status_code=413, detail="The job-specific .docx template is larger than 20 MB.")
        try:
            await asyncio.to_thread(_human_template_docx_profile, template_raw)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
    elif template_name:
        raise HTTPException(status_code=400, detail="Only Template Jobs accept a job-specific .docx template.")
    if not audio or not audio.filename:
        raise HTTPException(status_code=400, detail="Choose the complete recording for this job.")
    if os.path.splitext(audio.filename)[1].lower().lstrip(".") not in LETTER_AUDIO_EXTENSIONS:
        raise HTTPException(status_code=400, detail="Use a supported audio/video recording such as MP3, WAV, M4A, MP4, or WebM.")
    try:
        duration = float(seconds or 0)
    except (TypeError, ValueError):
        duration = 0
    if not math.isfinite(duration) or duration <= 0:
        raise HTTPException(status_code=400, detail="Enter the recording length in seconds.")
    max_reference_count = 5 if job_category == "template" else 6
    if len([item for item in (attachments or []) if getattr(item, "filename", "")]) > max_reference_count:
        raise HTTPException(status_code=413, detail=f"Attach no more than {max_reference_count} supporting reference files.")

    note = str(instructions or "").strip()
    if len(note) > 12000:
        raise HTTPException(status_code=413, detail="Job-specific instructions must be 12,000 characters or fewer.")
    default_instruction = GENERAL_JOB_DEFAULT_INSTRUCTION if job_category == "general" else TEMPLATE_JOB_DEFAULT_INSTRUCTION
    job_instructions = default_instruction + (f"\n\nADMIN JOB NOTES:\n{note}" if note else "")
    raw_references = []
    total_reference_bytes = len(template_raw)
    for upload in [item for item in (attachments or []) if getattr(item, "filename", "")]:
        name = os.path.basename(upload.filename or "reference")[:180]
        if doc_tools.file_extension(name) not in PDF_JOB_ATTACHMENT_EXTENSIONS:
            raise HTTPException(status_code=400, detail=f"{name} is not a supported reference file. Use PDF, Word, text, image or audio files.")
        raw = await upload.read(MAX_ATTACHMENT_BYTES + 1)
        if not raw:
            raise HTTPException(status_code=400, detail=f"{name} is empty.")
        if len(raw) > MAX_ATTACHMENT_BYTES:
            raise HTTPException(status_code=413, detail=f"{name} is larger than 20 MB.")
        total_reference_bytes += len(raw)
        if total_reference_bytes > 50000000:
            raise HTTPException(status_code=413, detail="Job reference files may total no more than 50 MB.")
        raw_references.append((upload, name, raw))
    transcriber_rate = await _get_human_transcriber_rate()
    quote = human_credit_quote(duration, transcriber_rate_kes=transcriber_rate)
    quote = {
        "credits": 0,
        "minutes": int(quote.get("minutes") or max(1, math.ceil(duration / 60))),
        "transcriber_payout_kes_per_minute": int(quote.get("transcriber_payout_kes_per_minute") or transcriber_rate),
    }
    job_id = uuid.uuid4().hex
    stored_paths = []
    try:
        audio_meta = await _human_store_upload(job_id, audio, "audio")
        stored_paths.append(audio_meta["storage_path"])
        attachment_meta = []
        if template_file and template_name:
            await template_file.seek(0)
            template_meta = await _human_store_upload(job_id, template_file, "instructions")
            template_meta.update({"is_template": True, "purpose": "template"})
            attachment_meta.append(template_meta)
            if template_meta.get("storage_path"):
                stored_paths.append(template_meta["storage_path"])
        for upload, _name, _raw in raw_references:
            await upload.seek(0)
            meta = await _human_store_upload(job_id, upload, "instructions")
            attachment_meta.append(meta)
            if meta and meta.get("storage_path"):
                stored_paths.append(meta["storage_path"])
        now = firestore.SERVER_TIMESTAMP
        base_job = {
            "client_uid": None, "client_email": "", "created_by_uid": actor["uid"],
            "created_by_email": str(actor.get("email") or "").strip().lower(),
            "admin_uploaded": True, "routing_status": "pending", "source_type": "admin_upload", "job_category": job_category,
            "job_type": "general_job" if job_category == "general" else "template_job",
            "job_name": str(title or "").strip()[:180] or os.path.basename(audio.filename or f"{job_category.title()} Job"),
            "status": "approved", "createdAt": now, "approvedAt": now, "updatedAt": now,
            "seconds": duration, "minutes": quote["minutes"], "turnaround": "standard", "difficulty": "standard",
            "service": f"{job_category}_transcription", "formatting": "template" if job_category == "template" else "standard",
            "timestamps": False, "speakers": "1-2", "speaker_labels": False,
            "instructions": job_instructions, "audio": audio_meta, "instruction_attachments": attachment_meta,
            "quote_credits": 0, "credits_charged": 0, "quote": quote,
            "worker_uid": None, "worker_email": None, "worker_name": None,
            "transcript": "", "transcript_html": "", "worker_notes": "", "final_attachment": None,
            "admin_feedback": "", "worker_rating": None, "releasedAt": None,
            "assignedAt": None, "deadlineAt": None, "tat_seconds": None,
            "auto_reassigned_count": 0, "last_auto_reassigned_at": None, "last_auto_reassigned_worker_name": None,
            "workerCompletedAt": None, "worker_minutes": None, "worker_amount_kes": None,
            "payout_status": None, "payout_period_id": None, "workerPaymentStatus": None, "workerPaidAt": None,
            "split_mode": "single", "segments": [], "assigned_worker_uids": [],
            "proofreader_uid": None, "proofreader_email": None, "proofreader_name": None, "proofreader_status": None,
            "proofreader_deadlineAt": None, "proofreader_tat_seconds": None,
            "proofreader_completedAt": None, "proofreader_minutes": None, "proofreader_amount_kes": None,
            "proofreader_payout_status": None, "proofreader_payout_period_id": None,
        }
        try:
            segments = _human_build_available_segments(base_job, datetime.now())
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        base_job["segments"] = segments
        base_job["split_mode"] = "multi" if segments else "single"
        base_job["status"] = "split_assigned" if segments else "approved"
        job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
        await asyncio.to_thread(job_ref.set, base_job)
        saved_snapshot = await asyncio.to_thread(job_ref.get)
        saved_job = saved_snapshot.to_dict() or base_job
        saved_job["id"] = job_id
        return {"job": _human_public_for(saved_job, "admin", actor.get("uid") or ""), "parts_count": len(segments), "worker_pay_kes_per_minute": quote["transcriber_payout_kes_per_minute"]}
    except Exception:
        bucket = _human_bucket()
        if bucket:
            for path in stored_paths:
                try:
                    await asyncio.to_thread(bucket.blob(path).delete)
                except Exception:
                    logger.warning("Could not clean up failed admin audio upload %s", path)
        try:
            await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).delete)
        except Exception:
            pass
        raise


@app.get("/human-transcription/admin/letter-jobs")
async def human_admin_list_letter_jobs(request: Request):
    actor = await _human_actor(request)
    if str(actor.get("email") or "").strip().lower() not in LETTER_JOB_ADMIN_EMAILS:
        raise HTTPException(status_code=403, detail="Letter Jobs are available only to the admin team.")
    if not db:
        return {"jobs": []}
    snapshots = await asyncio.to_thread(
        lambda: list(db.collection(HUMAN_JOB_COLLECTION).where(filter=FieldFilter("job_type", "==", "letter_job")).stream())
    )
    jobs = []
    for snapshot in snapshots:
        item = snapshot.to_dict() or {}
        if _human_job_dashboard_archived(item) or not _human_admin_can_see_job(actor, item):
            continue
        item["id"] = snapshot.id
        jobs.append(_human_public_for(item, "admin", actor.get("uid") or ""))
    jobs.sort(key=lambda item: str(item.get("createdAt") or ""), reverse=True)
    return {"jobs": jobs[:500]}


@app.get("/human-transcription/notifications")
async def human_workflow_notifications(request: Request, since: str = ""):
    """Return small, role-filtered human-work events for app-wide alerts."""
    actor = await _human_actor(request)
    if not db:
        return {"events": [], "server_time": datetime.now().astimezone().isoformat()}
    try:
        since_dt = _as_dt(datetime.fromisoformat(str(since).replace("Z", "+00:00"))) if since else None
    except Exception:
        since_dt = None
    if not since_dt:
        since_dt = datetime.now() - timedelta(seconds=10)
    ref = db.collection(HUMAN_JOB_COLLECTION)
    found = {}
    if actor["role"] == "admin":
        snapshots = await asyncio.to_thread(lambda: list(ref.where(filter=FieldFilter("updatedAt", ">=", since_dt)).stream()))
        found.update({snap.id: snap for snap in snapshots if _human_admin_can_see_job(actor, snap.to_dict() or {})})
    elif actor["role"] == "worker":
        for field, op in (("worker_uid", "=="), ("assigned_worker_uids", "array_contains"), ("proofreader_uid", "==")):
            snapshots = await asyncio.to_thread(lambda field=field, op=op: list(ref.where(filter=FieldFilter(field, op, actor["uid"])).stream()))
            found.update({snap.id: snap for snap in snapshots})
        takebacks = await asyncio.to_thread(lambda: list(ref.where(filter=FieldFilter("last_assignment_takeback_at", ">=", since_dt)).stream()))
        found.update({snap.id: snap for snap in takebacks})
    else:
        snapshots = await asyncio.to_thread(lambda: list(ref.where(filter=FieldFilter("client_uid", "==", actor["uid"])).stream()))
        found.update({snap.id: snap for snap in snapshots})

    def recent(value):
        moment = _as_dt(value) if value else None
        return bool(moment and moment >= since_dt)

    events = []
    for snap in found.values():
        job = snap.to_dict() or {}
        job_id = snap.id
        audio = job.get("audio") or {}
        job_name = str(audio.get("name") or job.get("audio_name") or f"Human job {job_id[:8]}")[:180]
        status = str(job.get("status") or "")
        if actor["role"] == "admin":
            if status == "pending_admin" and recent(job.get("createdAt")):
                events.append({"type": "new_request", "job_id": job_id, "job_name": job_name, "status": status, "updated_at": _human_iso(job.get("createdAt"))})
            if recent(job.get("last_auto_reassigned_at")):
                events.append({"type": "returned_to_queue", "job_id": job_id, "job_name": job_name, "updated_at": _human_iso(job.get("last_auto_reassigned_at"))})
            for part in (job.get("segments") or []):
                if recent(part.get("last_auto_reassigned_at")):
                    events.append({"type": "returned_to_queue", "job_id": job_id, "job_name": job_name, "label": part.get("label") or "A job part", "updated_at": _human_iso(part.get("last_auto_reassigned_at")), "event_id": part.get("id")})
                if part.get("status") == "submitted" and recent(part.get("workerCompletedAt")):
                    events.append({"type": "submission", "job_id": job_id, "job_name": job_name, "label": part.get("label") or "A job part", "updated_at": _human_iso(part.get("workerCompletedAt")), "event_id": part.get("id")})
            if job.get("proofreader_status") == "submitted" and recent(job.get("proofreader_completedAt")):
                events.append({"type": "submission", "job_id": job_id, "job_name": job_name, "label": "Final proofreading", "updated_at": _human_iso(job.get("proofreader_completedAt")), "event_id": "proofreader"})
            if not job.get("split_mode") and status in {"submitted", "client_review"} and recent(job.get("workerCompletedAt")):
                events.append({"type": "submission", "job_id": job_id, "job_name": job_name, "label": "Transcript", "updated_at": _human_iso(job.get("workerCompletedAt")), "event_id": "job"})
        elif actor["role"] == "client":
            if status == "client_review" and recent(job.get("reviewedAt")):
                events.append({"type": "review", "job_id": job_id, "job_name": job_name, "status": status, "updated_at": _human_iso(job.get("reviewedAt"))})
            if status == "released" and recent(job.get("releasedAt")):
                events.append({"type": "released", "job_id": job_id, "job_name": job_name, "status": status, "updated_at": _human_iso(job.get("releasedAt"))})
        else:
            assignments = []
            if job.get("worker_uid") == actor["uid"] and job.get("status") in {"assigned", "in_progress"}:
                assignments.append(("transcriber", job.get("assignedAt")))
            for part in (job.get("segments") or []):
                if part.get("worker_uid") == actor["uid"] and part.get("status") in {"assigned", "in_progress"}:
                    assignments.append((part.get("label") or "transcriber", part.get("assignedAt")))
            if job.get("proofreader_uid") == actor["uid"] and job.get("proofreader_status") in {"assigned", "in_progress"}:
                assignments.append(("proofreader", job.get("proofreader_assignedAt")))
            for role, assigned_at in assignments:
                if recent(assigned_at):
                    events.append({"type": "assignment", "job_id": job_id, "job_name": job_name, "label": role, "updated_at": _human_iso(assigned_at)})
            takeback_at = job.get("last_assignment_takeback_at")
            if job.get("last_assignment_takeback_worker_uid") == actor["uid"] and recent(takeback_at):
                events.append({
                    "type": "assignment_taken_back", "job_id": job_id, "job_name": job_name,
                    "label": job.get("last_assignment_takeback_label") or "Your assignment",
                    "updated_at": _human_iso(takeback_at), "event_id": _human_iso(takeback_at),
                })
        message_summaries = job.get("last_message_by_thread") or {}
        if not message_summaries and job.get("last_message"):
            legacy = job.get("last_message") or {}
            message_summaries = {legacy.get("thread") or "client": legacy}
        visible_threads = ("worker",) if actor["role"] in {"admin", "worker"} else ()
        for message_thread in visible_threads:
            last_message = message_summaries.get(message_thread) or {}
            if last_message.get("sender_uid") != actor["uid"] and recent(last_message.get("createdAt")):
                events.append({"type": "message", "job_id": job_id, "job_name": job_name, "sender_role": last_message.get("sender_role"), "thread": message_thread, "message_id": last_message.get("id"), "updated_at": _human_iso(last_message.get("createdAt"))})
    events.sort(key=lambda event: str(event.get("updated_at") or ""))
    return {"events": events, "server_time": datetime.now().astimezone().isoformat()}


def _human_subadmin_kes(milli_kes):
    try:
        return round(int(milli_kes or 0) / 1000.0, 3)
    except (TypeError, ValueError):
        return 0.0


def _human_subadmin_public_earning(raw, doc_id=None):
    item = dict(raw or {})
    amount_milli = int(item.get("amount_kes_milli") or 0)
    rate_milli = int(item.get("rate_milli_kes_per_unit") or 0)
    completed_at = _as_dt(item.get("completed_at")) if item.get("completed_at") else None
    return {
        "earning_id": item.get("earning_id") or doc_id,
        "subadmin_uid": item.get("subadmin_uid"),
        "subadmin_email": item.get("subadmin_email") or "",
        "job_id": item.get("job_id"),
        "job_name": item.get("job_name") or "Human Work",
        "job_type": item.get("job_type"),
        "job_category": item.get("job_category") or "",
        "segment_id": item.get("segment_id"),
        "category": item.get("category"),
        "work_source": item.get("work_source"),
        "measure": item.get("measure"),
        "quantity": int(item.get("quantity") or 0),
        "rate_milli_kes_per_unit": rate_milli,
        "rate_kes_per_unit": _human_subadmin_kes(rate_milli),
        "amount_kes_milli": amount_milli,
        "amount_kes": _human_subadmin_kes(amount_milli),
        "payout_status": item.get("payout_status") or "accruing",
        "payout_period_id": item.get("payout_period_id"),
        "shift_date": item.get("shift_date") or (completed_at.date().isoformat() if completed_at else ""),
        "completed_at": _human_iso(completed_at),
    }


async def _human_subadmin_close_due_pay_periods(now=None):
    """Create idempotent half-month invoices from ended accrual periods."""
    if not db:
        return
    local_now = (now or _human_shift_local_now()).astimezone(HUMAN_SHIFT_TIMEZONE)
    now_naive = local_now.replace(tzinfo=None)
    try:
        snapshots = await asyncio.to_thread(lambda: list(db.collection(HUMAN_SUBADMIN_EARNING_COLLECTION).stream()))
    except Exception as exc:
        logger.warning("Sub-admin pay period close could not list earnings: %s", exc)
        return
    groups = {}
    for snap in snapshots:
        item = snap.to_dict() or {}
        if str(item.get("payout_status") or "accruing").lower() != "accruing":
            continue
        completed_at = _as_dt(item.get("completed_at")) if item.get("completed_at") else None
        if not completed_at:
            continue
        # Earnings are saved with Nairobi-local wall time for calendar-period
        # grouping; normalize aware values to that same local calendar first.
        if getattr(completed_at, "tzinfo", None):
            completed_at = completed_at.astimezone(HUMAN_SHIFT_TIMEZONE).replace(tzinfo=None)
        label, start_dt, end_dt = _pay_period_bounds(completed_at)
        if now_naive <= end_dt:
            continue
        uid = str(item.get("subadmin_uid") or "").strip()
        if not uid:
            continue
        key = (uid, label)
        group = groups.setdefault(key, {
            "subadmin_uid": uid,
            "subadmin_email": item.get("subadmin_email") or "",
            "period_label": label,
            "period_start": start_dt,
            "period_end": end_dt,
            "items": [],
        })
        group["items"].append({
            "earning_id": item.get("earning_id") or snap.id,
            "job_id": item.get("job_id"),
            "job_name": item.get("job_name") or "Human Work",
            "segment_id": item.get("segment_id"),
            "category": item.get("category"),
            "work_source": item.get("work_source"),
            "measure": item.get("measure"),
            "quantity": int(item.get("quantity") or 0),
            "rate_milli_kes_per_unit": int(item.get("rate_milli_kes_per_unit") or 0),
            "amount_kes_milli": int(item.get("amount_kes_milli") or 0),
            "completed_at": completed_at,
        })

    for (uid, label), group in groups.items():
        payout_id = f"{uid}_{label}"
        payout_ref = db.collection(HUMAN_SUBADMIN_PAYOUT_COLLECTION).document(payout_id)
        new_items = group["items"]

        @firestore.transactional
        def merge_invoice(transaction):
            snapshot = payout_ref.get(transaction=transaction)
            existing = snapshot.to_dict() if snapshot.exists else {}
            items = list(existing.get("items") or [])
            existing_ids = {str(value.get("earning_id") or "") for value in items}
            items.extend(value for value in new_items if str(value.get("earning_id") or "") not in existing_ids)
            total_milli = sum(int(value.get("amount_kes_milli") or 0) for value in items)
            categories = {}
            for value in items:
                key = str(value.get("category") or "other")
                categories[key] = categories.get(key, 0) + int(value.get("amount_kes_milli") or 0)
            transaction.set(payout_ref, {
                "subadmin_uid": uid,
                "subadmin_email": group["subadmin_email"] or existing.get("subadmin_email") or "",
                "period_label": label,
                "period_start": group["period_start"],
                "period_end": group["period_end"],
                "items": items,
                "earning_ids": sorted({str(value.get("earning_id") or "") for value in items if value.get("earning_id")}),
                "job_ids": sorted({str(value.get("job_id") or "") for value in items if value.get("job_id")}),
                "category_totals_milli_kes": categories,
                "total_amount_kes_milli": total_milli,
                "status": existing.get("status") or "pending",
                "createdAt": existing.get("createdAt") or firestore.SERVER_TIMESTAMP,
                "updatedAt": firestore.SERVER_TIMESTAMP,
                "paidAt": existing.get("paidAt"),
                "paidBy": existing.get("paidBy"),
            }, merge=True)

        try:
            await asyncio.to_thread(lambda: merge_invoice(db.transaction()))
            for item in new_items:
                earning_id = item.get("earning_id")
                if earning_id:
                    await asyncio.to_thread(
                        db.collection(HUMAN_SUBADMIN_EARNING_COLLECTION).document(earning_id).set,
                        {"payout_status": "invoiced", "payout_period_id": label, "updatedAt": firestore.SERVER_TIMESTAMP},
                        merge=True,
                    )
        except Exception as exc:
            logger.warning("Could not close sub-admin pay period %s: %s", payout_id, exc)


def _human_subadmin_submission_actor(job, segment=None):
    """Choose the assigned sub-admin, or the sole configured sub-admin on duty."""
    email, uid, _assigned_at = _human_subadmin_assignment_metadata(job or {}, segment, ai_used=False)
    email = str(email or "").strip().lower()
    uid = str(uid or "").strip()
    if is_human_subadmin(email):
        return {"uid": uid, "email": email}
    if email:
        # A recorded main-admin action must not silently be reassigned to the
        # only sub-admin merely because the latter is the sole configured one.
        return {}
    configured = sorted({str(value or "").strip().lower() for value in HUMAN_JOB_ADMIN_EMAILS if is_human_subadmin(value)})
    if len(configured) == 1:
        return {"uid": "", "email": configured[0]}
    return {}


async def _human_subadmin_accrue_job_earnings(job_id, job, actor, segment_ids=None, ai_only=False):
    if not db:
        return 0
    actor = dict(actor or {})
    actor_email = str(actor.get("email") or "").strip().lower()
    if is_human_subadmin(actor_email) and not str(actor.get("uid") or "").strip():
        try:
            actor["uid"] = await get_user_profile_by_email_firestore(actor_email) or ""
        except Exception:
            actor["uid"] = ""
    job = dict(job or {})
    assignment_records = [job] + [dict(item or {}) for item in (job.get("segments") or [])]
    resolved_uids = {}
    for record in assignment_records:
        for prefix in ("ai_agent", "ai_review", "letter_agent", "letter_ai_review", "human_work", "worker", "proofreader"):
            email = str(record.get(f"{prefix}_assigned_by_email") or "").strip().lower()
            uid = str(record.get(f"{prefix}_assigned_by_uid") or "").strip()
            if not is_human_subadmin(email) or uid:
                continue
            if email not in resolved_uids:
                try:
                    resolved_uids[email] = await get_user_profile_by_email_firestore(email) or ""
                except Exception:
                    resolved_uids[email] = ""
            if resolved_uids[email]:
                record[f"{prefix}_assigned_by_uid"] = str(resolved_uids[email])
    if len(assignment_records) > 1:
        job["segments"] = assignment_records[1:]
    settings_ref = db.collection(HUMAN_SUBADMIN_RATE_SETTINGS_COLLECTION).document(HUMAN_SUBADMIN_RATE_SETTINGS_DOCUMENT)
    try:
        settings_snapshot = await asyncio.to_thread(settings_ref.get)
        rate_values = _human_subadmin_rate_values(settings_snapshot.to_dict() if settings_snapshot.exists else None)
    except Exception as exc:
        logger.warning("Could not load sub-admin pay rates; using defaults: %s", exc)
        rate_values = _human_subadmin_rate_defaults()
    specs = _human_subadmin_earning_specs(
        job_id, job, actor, rates=rate_values, segment_ids=segment_ids, ai_only=ai_only,
    )
    created = 0
    for item in specs:
        ref = db.collection(HUMAN_SUBADMIN_EARNING_COLLECTION).document(item["earning_id"])
        try:
            await asyncio.to_thread(ref.create, item)
            created += 1
        except Exception:
            # A deterministic document ID makes repeated approvals harmless;
            # only treat the write as a duplicate if the original now exists.
            try:
                existing = await asyncio.to_thread(ref.get)
                if not existing.exists:
                    logger.exception("Could not save sub-admin earning %s", item["earning_id"])
            except Exception:
                logger.exception("Could not verify sub-admin earning %s", item["earning_id"])
    return created


@app.get("/human-transcription/subadmin/payment-history")
async def human_subadmin_payment_history(request: Request):
    actor = _require_human_subadmin(request)
    if not db:
        return {"earnings": [], "payouts": [], "totals": {"accruing_kes": 0, "pending_kes": 0, "paid_kes": 0}}
    await _human_subadmin_close_due_pay_periods()
    uid = str(actor.get("uid") or "")
    earning_query = db.collection(HUMAN_SUBADMIN_EARNING_COLLECTION).where(filter=FieldFilter("subadmin_uid", "==", uid))
    payout_query = db.collection(HUMAN_SUBADMIN_PAYOUT_COLLECTION).where(filter=FieldFilter("subadmin_uid", "==", uid))
    earnings, payouts = await asyncio.gather(
        asyncio.to_thread(lambda: list(earning_query.stream())),
        asyncio.to_thread(lambda: list(payout_query.stream())),
    )
    earning_rows = [_human_subadmin_public_earning(snap.to_dict(), snap.id) for snap in earnings]
    payout_rows = [{
        "payout_id": snap.id,
        "period_label": (snap.to_dict() or {}).get("period_label"),
        "status": (snap.to_dict() or {}).get("status") or "pending",
        "total_amount_kes": _human_subadmin_kes((snap.to_dict() or {}).get("total_amount_kes_milli")),
        "category_totals_kes": {key: _human_subadmin_kes(value) for key, value in ((snap.to_dict() or {}).get("category_totals_milli_kes") or {}).items()},
        "paid_at": _human_iso((snap.to_dict() or {}).get("paidAt")),
        "items": (snap.to_dict() or {}).get("items") or [],
    } for snap in payouts]
    return {
        "earnings": sorted(earning_rows, key=lambda item: item.get("completed_at") or "", reverse=True),
        "payouts": sorted(payout_rows, key=lambda item: item.get("period_label") or "", reverse=True),
        "totals": {
            "accruing_kes": _human_subadmin_kes(sum(int((snap.to_dict() or {}).get("amount_kes_milli") or 0) for snap in earnings if (snap.to_dict() or {}).get("payout_status") == "accruing")),
            "pending_kes": sum(item["total_amount_kes"] for item in payout_rows if item["status"] != "paid"),
            "paid_kes": sum(item["total_amount_kes"] for item in payout_rows if item["status"] == "paid"),
        },
    }


