@app.get("/api/admin/worker-payments/search")
async def admin_worker_payments_search(request: Request, worker_uid: str = "", start_date: str = "", end_date: str = "", status: str = "all"):
    _require_admin(request)
    if not db:
        return {"jobs": [], "total_minutes": 0, "total_amount_kes": 0}
    await _close_due_pay_periods()
    def _parse_day(value, end_of_day=False):
        if not value:
            return None
        try:
            d = datetime.fromisoformat(value[:10])
        except Exception:
            return None
        return d.replace(hour=23, minute=59, second=59, microsecond=999999) if end_of_day else d
    start_bound = _parse_day(start_date)
    end_bound = _parse_day(end_date, end_of_day=True)
    status = (status or "all").strip().lower()
    rows, seen = [], set()

    def append_admin_payment(item, job_status=None):
        if worker_uid and item.get("worker_uid") != worker_uid:
            return
        identity = (item.get("job_id"), item.get("source"), item.get("segment_id"))
        if identity in seen:
            return
        completed_at = _as_dt(item.get("completed_at")) if item.get("completed_at") else None
        if start_bound and (not completed_at or completed_at < start_bound):
            return
        if end_bound and (not completed_at or completed_at > end_bound):
            return
        payout_status = item.get("payout_status") or "accruing"
        if payout_status == "unassigned":
            payout_status = "accruing"
        if item.get("paid_at"):
            payout_status = "paid"
        if status != "all" and payout_status != status:
            return
        role = "Proofreader" if item.get("source") == "proofreader" else ("PDF Transcriber" if item.get("source") == "pdf" else ("Part " + str(item.get("segment_id")).split("_")[-1] if item.get("source") == "segment" and item.get("segment_id") else "Transcriber"))
        amount = int(item.get("amount_kes") or 0)
        seen.add(identity)
        rows.append({
            "job_id": item.get("job_id"), "source": item.get("source"), "segment_id": item.get("segment_id"),
            "role": role, "worker_uid": item.get("worker_uid"),
            "worker_email": item.get("worker_email") or "", "worker_name": item.get("worker_name") or "",
            "minutes": int(item.get("minutes") or 0), "amount_kes": amount,
            "gross_amount_kes": int(item.get("gross_amount_kes") or amount), "deduction_kes": int(item.get("deduction_kes") or 0),
            "deduction_reason": item.get("deduction_reason") or "", "payout_status": payout_status,
            "payout_period_id": item.get("payout_period_id"), "completed_at": _human_iso(completed_at),
            "paid_at": _human_iso(item.get("paid_at")), "job_status": job_status or item.get("job_status"),
        })

    for snap in await asyncio.to_thread(lambda: list(db.collection(HUMAN_JOB_COLLECTION).stream())):
        job = snap.to_dict() or {}
        for item in _human_worker_earning_items(snap.id, job, include_processed=True):
            append_admin_payment(item, job.get("status"))
    archive_query = db.collection(HUMAN_EARNING_ARCHIVE_COLLECTION)
    archive_snapshots = await asyncio.to_thread(lambda: list(archive_query.where(filter=FieldFilter("worker_uid", "==", worker_uid)).stream())) if worker_uid else await asyncio.to_thread(lambda: list(archive_query.stream()))
    for snap in archive_snapshots:
        item = snap.to_dict() or {}
        append_admin_payment(item, item.get("job_status"))
    rows.sort(key=lambda item: str(item.get("completed_at") or ""), reverse=True)
    transcription_rows = [item for item in rows if item["role"] not in {"Proofreader", "PDF Transcriber"}]
    proofreading_rows = [item for item in rows if item["role"] == "Proofreader"]
    pdf_rows = [item for item in rows if item["role"] == "PDF Transcriber"]
    return {
        "jobs": rows,
        "total_minutes": sum(item["minutes"] for item in rows),
        "total_amount_kes": sum(item["amount_kes"] for item in rows),
        "total_deduction_kes": sum(item["deduction_kes"] for item in rows),
        "gross_total_kes": sum(item["gross_amount_kes"] for item in rows),
        "transcription_amount_kes": sum(item["amount_kes"] for item in transcription_rows),
        "proofreading_amount_kes": sum(item["amount_kes"] for item in proofreading_rows),
        "pdf_amount_kes": sum(item["amount_kes"] for item in pdf_rows),
        "transcription_minutes": sum(item["minutes"] for item in transcription_rows),
        "proofreading_minutes": sum(item["minutes"] for item in proofreading_rows),
        "job_count": len(rows),
    }


@app.get("/api/admin/worker-payouts")
async def admin_worker_payouts(request: Request, worker_uid: str = "", status: str = "all"):
    """List worker payment invoices; only the main admin may view them."""
    _require_admin(request)
    if not db:
        return {"payouts": [], "totals": {"pending_kes": 0, "paid_kes": 0}}
    await _close_due_pay_periods()
    ref = db.collection(HUMAN_PAYOUT_COLLECTION)
    if worker_uid:
        snapshots = await asyncio.to_thread(lambda: list(ref.where(filter=FieldFilter("worker_uid", "==", worker_uid)).stream()))
    else:
        snapshots = await asyncio.to_thread(lambda: list(ref.stream()))
    status = (status or "all").strip().lower()
    payouts = []
    pending_total, paid_total = 0, 0
    for snap in snapshots:
        payout = snap.to_dict() or {}
        payout_status = payout.get("status") or "pending"
        amount = int(payout.get("total_amount_kes") or 0)
        if payout_status == "paid":
            paid_total += amount
        else:
            pending_total += amount
        if status != "all" and payout_status != status:
            continue
        invoice_items = payout.get("items") or []
        transcription_items = [item for item in invoice_items if item.get("source") not in {"proofreader", "pdf"}]
        proofreading_items = [item for item in invoice_items if item.get("source") == "proofreader"]
        pdf_items = [item for item in invoice_items if item.get("source") == "pdf"]
        payouts.append({
            "payout_id": snap.id,
            "worker_uid": payout.get("worker_uid"),
            "worker_email": payout.get("worker_email") or "",
            "worker_name": payout.get("worker_name") or "",
            "period_label": payout.get("period_label"),
            "period_start": _human_iso(payout.get("period_start")),
            "period_end": _human_iso(payout.get("period_end")),
            "total_minutes": int(payout.get("total_minutes") or 0),
            "total_amount_kes": amount,
            "total_deduction_kes": sum(int(item.get("deduction_kes") or 0) for item in invoice_items),
            "gross_total_kes": amount + sum(int(item.get("deduction_kes") or 0) for item in invoice_items),
            "transcription_minutes": sum(int(item.get("minutes") or 0) for item in transcription_items),
            "transcription_amount_kes": sum(int(item.get("amount_kes") or 0) for item in transcription_items),
            "proofreading_minutes": sum(int(item.get("minutes") or 0) for item in proofreading_items),
            "proofreading_amount_kes": sum(int(item.get("amount_kes") or 0) for item in proofreading_items),
            "pdf_amount_kes": sum(int(item.get("amount_kes") or 0) for item in pdf_items),
            "status": payout_status,
            "job_ids": payout.get("job_ids") or [],
            "paid_at": _human_iso(payout.get("paidAt")),
            "paid_by": payout.get("paidBy"),
        })
        if not invoice_items:
            payouts[-1]["transcription_minutes"] = int(payout.get("total_minutes") or 0)
            payouts[-1]["transcription_amount_kes"] = amount
    payouts.sort(key=lambda item: str(item.get("period_label") or ""), reverse=True)
    return {"payouts": payouts, "totals": {"pending_kes": pending_total, "paid_kes": paid_total}}


@app.post("/api/admin/worker-payouts/{payout_id}/mark-paid")
async def admin_mark_payout_paid(payout_id: str, request: Request):
    """Main admin confirms a half-month invoice has actually been paid out."""
    admin = _require_admin(request)
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    payout_ref = db.collection(HUMAN_PAYOUT_COLLECTION).document(payout_id)
    snapshot = await asyncio.to_thread(payout_ref.get)
    if not snapshot.exists:
        raise HTTPException(status_code=404, detail="That payout invoice was not found.")
    payout = snapshot.to_dict() or {}
    if payout.get("status") == "paid":
        raise HTTPException(status_code=409, detail="This payout has already been marked as paid.")
    now = datetime.now()
    await asyncio.to_thread(payout_ref.set, {"status": "paid", "paidAt": now, "paidBy": (admin.get("email") or "").lower(), "updatedAt": firestore.SERVER_TIMESTAMP}, merge=True)
    items = payout.get("items") or []
    job_ids = payout.get("job_ids") or []
    if items:
        for item in items:
            job_id = item.get("job_id")
            source = item.get("source") or "job"
            segment_id = item.get("segment_id")
            archive_id = item.get("archive_doc_id") or _human_archive_id(job_id, source, segment_id)
            archive_ref = db.collection(HUMAN_EARNING_ARCHIVE_COLLECTION).document(archive_id)
            archive_snapshot = await asyncio.to_thread(archive_ref.get)
            if item.get("archive_doc_id") or archive_snapshot.exists:
                await asyncio.to_thread(archive_ref.set, {"payout_status": "paid", "paid_at": now, "updatedAt": firestore.SERVER_TIMESTAMP}, merge=True)
                continue
            job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
            snap = await asyncio.to_thread(job_ref.get)
            if not snap.exists:
                continue
            job = snap.to_dict() or {}
            update = {"updatedAt": firestore.SERVER_TIMESTAMP}
            if source in {"job", "pdf"}:
                update.update({"payout_status": "paid", "workerPaymentStatus": "paid", "workerPaidAt": now})
            elif source == "proofreader":
                update.update({"proofreader_payout_status": "paid", "proofreaderPaidAt": now})
            elif source == "segment":
                segments = [dict(x or {}) for x in (job.get("segments") or [])]
                for segment in segments:
                    if segment.get("id") == segment_id:
                        segment.update({"payout_status": "paid", "workerPaymentStatus": "paid", "workerPaidAt": now})
                update["segments"] = segments
            await asyncio.to_thread(job_ref.update, update)
    elif job_ids:
        batch = db.batch()
        for job_id in job_ids:
            batch.update(db.collection(HUMAN_JOB_COLLECTION).document(job_id), {"payout_status": "paid", "workerPaymentStatus": "paid", "workerPaidAt": now, "updatedAt": firestore.SERVER_TIMESTAMP})
        await asyncio.to_thread(batch.commit)
    return {"status": "paid", "payout_id": payout_id, "jobs_marked_paid": len(items) or len(job_ids)}


@app.post("/api/admin/human-jobs/{job_id}/payment-deduction")
async def admin_deduct_worker_job_payment(job_id: str, request: Request):
    admin = _require_admin(request)
    if not db:
        raise HTTPException(status_code=503, detail="The workflow database is unavailable.")
    payload = await request.json()
    source = str(payload.get("source") or "job").strip().lower()
    segment_id = str(payload.get("segment_id") or "").strip() or None
    try:
        deduction_amount = int(payload.get("amount_kes") or 0)
    except (TypeError, ValueError):
        deduction_amount = 0
    reason = re.sub(r"\s+", " ", str(payload.get("reason") or "").strip())[:500]
    if source not in {"job", "segment", "proofreader", "pdf"}:
        raise HTTPException(status_code=400, detail="Choose a valid worker payment item.")
    if source == "segment" and not segment_id:
        raise HTTPException(status_code=400, detail="Choose the submitted segment to adjust.")
    if deduction_amount <= 0 or not reason:
        raise HTTPException(status_code=400, detail="Enter a positive deduction and a reason for the record.")
    job_ref = db.collection(HUMAN_JOB_COLLECTION).document(job_id)
    job_snapshot = await asyncio.to_thread(job_ref.get)
    job = job_snapshot.to_dict() or {}
    archive_snapshot = None
    if job_snapshot.exists:
        matches = [item for item in _human_worker_earning_items(job_id, job, include_processed=True) if item.get("source") == source and (source != "segment" or item.get("segment_id") == segment_id)]
        item = matches[0] if matches else None
    else:
        archive_query = db.collection(HUMAN_EARNING_ARCHIVE_COLLECTION).where(filter=FieldFilter("job_id", "==", job_id))
        archive_snapshots = await asyncio.to_thread(lambda: list(archive_query.stream()))
        archive_snapshot = next((snap for snap in archive_snapshots if (snap.to_dict() or {}).get("source") == source and (source != "segment" or (snap.to_dict() or {}).get("segment_id") == segment_id)), None)
        item = archive_snapshot.to_dict() if archive_snapshot else None
    if not item:
        raise HTTPException(status_code=404, detail="That worker earning was not found.")
    if item.get("payout_status") == "paid" or item.get("paid_at"):
        raise HTTPException(status_code=409, detail="Already-paid earnings cannot be adjusted.")
    gross = int(item.get("gross_amount_kes") or item.get("amount_kes") or 0)
    previous_deduction = int(item.get("deduction_kes") or 0)
    new_deduction = previous_deduction + deduction_amount
    if new_deduction > gross:
        raise HTTPException(status_code=400, detail=f"The deduction cannot exceed the unpaid gross amount of KES {gross - previous_deduction}.")
    new_amount = gross - new_deduction
    payout_period_id = item.get("payout_period_id")
    payout_ref = None
    payout_update = None
    if payout_period_id:
        payout_ref = db.collection(HUMAN_PAYOUT_COLLECTION).document(f"{item.get('worker_uid')}_{payout_period_id}")
        payout_snapshot = await asyncio.to_thread(payout_ref.get)
        if payout_snapshot.exists:
            payout = payout_snapshot.to_dict() or {}
            if payout.get("status") == "paid":
                raise HTTPException(status_code=409, detail="Already-paid earnings cannot be adjusted.")
            invoice_items = [dict(x or {}) for x in (payout.get("items") or [])]
            invoice_item = next((x for x in invoice_items if x.get("job_id") == job_id and x.get("source") == source and (source != "segment" or x.get("segment_id") == segment_id)), None)
            if not invoice_item:
                raise HTTPException(status_code=409, detail="The payout invoice could not be reconciled, so no deduction was saved.")
            previous_amount = int(invoice_item.get("amount_kes") or 0)
            invoice_item.update({"amount_kes": new_amount, "gross_amount_kes": gross, "deduction_kes": new_deduction, "deduction_reason": reason})
            payout_update = {
                "items": invoice_items,
                "total_amount_kes": max(0, int(payout.get("total_amount_kes") or 0) - previous_amount + new_amount),
                "updatedAt": firestore.SERVER_TIMESTAMP,
            }
        elif item.get("payout_status") == "invoiced":
            raise HTTPException(status_code=409, detail="The pending payout invoice could not be found, so no deduction was saved.")
    batch = db.batch()
    if archive_snapshot is not None:
        archive_ref = archive_snapshot.reference
        batch.set(archive_ref, {"gross_amount_kes": gross, "deduction_kes": new_deduction, "deduction_reason": reason, "amount_kes": new_amount, "updated_at": datetime.now()}, merge=True)
    elif source in {"job", "pdf"}:
        batch.update(job_ref, {"worker_gross_amount_kes": gross, "worker_deduction_kes": new_deduction, "worker_deduction_reason": reason, "worker_amount_kes": new_amount, "updatedAt": firestore.SERVER_TIMESTAMP})
    elif source == "proofreader":
        batch.update(job_ref, {"proofreader_gross_amount_kes": gross, "proofreader_deduction_kes": new_deduction, "proofreader_deduction_reason": reason, "proofreader_amount_kes": new_amount, "updatedAt": firestore.SERVER_TIMESTAMP})
    else:
        segments = [dict(x or {}) for x in (job.get("segments") or [])]
        found_segment = False
        for segment in segments:
            if segment.get("id") == segment_id:
                segment.update({"worker_gross_amount_kes": gross, "worker_deduction_kes": new_deduction, "worker_deduction_reason": reason, "worker_amount_kes": new_amount})
                found_segment = True
        if not found_segment:
            raise HTTPException(status_code=404, detail="That worker segment was not found.")
        batch.update(job_ref, {"segments": segments, "updatedAt": firestore.SERVER_TIMESTAMP})
    if payout_ref is not None and payout_update is not None:
        batch.set(payout_ref, payout_update, merge=True)
    audit_ref = db.collection(HUMAN_DEDUCTION_COLLECTION).document(uuid.uuid4().hex)
    batch.set(audit_ref, {
        "job_id": job_id, "source": source, "segment_id": segment_id, "worker_uid": item.get("worker_uid"),
        "worker_email": item.get("worker_email") or "", "worker_name": item.get("worker_name") or "",
        "amount_kes": deduction_amount, "previous_deduction_kes": previous_deduction, "total_deduction_kes": new_deduction,
        "gross_amount_kes": gross, "remaining_amount_kes": new_amount, "reason": reason,
        "admin_email": (admin.get("email") or "").lower(), "created_at": datetime.now(),
    })
    await asyncio.to_thread(batch.commit)
    logger.info("Main admin %s deducted KES %s from %s earning for job %s: %s", (admin.get("email") or "").lower(), deduction_amount, source, job_id, reason)
    return {"job_id": job_id, "source": source, "deduction_kes": deduction_amount, "total_deduction_kes": new_deduction, "gross_amount_kes": gross, "amount_kes": new_amount, "reason": reason}


@app.post("/human-transcription/jobs/{job_id}/approve")
async def human_admin_approve(job_id: str, request: Request):
    admin = _require_human_job_admin(request)
    job = await _human_job(job_id)
    if job.get("status") != "pending_admin":
        raise HTTPException(status_code=409, detail="This job is not waiting for admin approval.")
    now = _human_shift_local_now()
    try:
        segments = _human_build_available_segments(job, now)
    except ValueError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    next_status = "split_assigned" if segments else "approved"
    updates = {
        "status": next_status,
        "split_mode": "multi" if segments else "single",
        "segments": segments,
        "assigned_worker_uids": [],
        "approvedAt": now,
        "human_work_assigned_by_uid": str(admin.get("uid") or "").strip(),
        "human_work_assigned_by_email": str(admin.get("email") or "").strip().lower(),
        "human_work_assignedAt": now,
        "updatedAt": firestore.SERVER_TIMESTAMP,
    }
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, updates)
    await _complete_human_admin_notifications(job_id, {"job_request"})
    if job.get("client_uid"):
        await _create_user_notification(
            str(job["client_uid"]), f"human-approved:{job_id}", "job_approved", "Your Human Work request is approved",
            "Approved work is now being picked up by an available transcriber.", route="human_job", job_id=job_id, target_id=job_id,
        )
    available_body = (
        f"{len(segments)} parts are open to claim on the Available Jobs board."
        if segments else "A new job is open to claim on the Available Jobs board."
    )
    asyncio.create_task(_notify_available_workers(job_id, "New work is available", available_body))
    return {"status": next_status, "job_id": job_id, "parts_count": len(segments)}


@app.post("/human-transcription/jobs/{job_id}/claim")
async def human_worker_claim(job_id: str, request: Request):
    actor = await _human_actor(request)
    if actor["role"] != "worker":
        raise HTTPException(status_code=403, detail="Only approved workers can claim Human Work.")
    rating_summary = await _human_worker_rating_summary(actor["uid"], actor.get("profile") or {})
    if rating_summary["average"] is None or rating_summary["average"] < MIN_HUMAN_WORKER_RATING:
        raise HTTPException(status_code=403, detail="A worker rating of 3.5/5 or higher is required to claim Available Jobs. Contact an admin about a supervised starter assignment.")
    claim_window = await _human_shift_assert_can_claim(actor)
    payload = await request.json()
    segment_id = str(payload.get("segment_id") or "").strip()
    await _human_job(job_id)
    if await _human_worker_has_active_assignment(actor["uid"]):
        raise HTTPException(status_code=409, detail="Finish your current assignment before claiming another.")
    try:
        assignment = await asyncio.to_thread(
            _human_claim_assignment_transaction, job_id, actor, segment_id,
            require_availability=False, after_hours_self_claim=False,
        )
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("Could not claim Human Work %s for %s", job_id, actor["uid"])
        raise HTTPException(status_code=409, detail="That work could not be claimed. Refresh the board and try again.") from exc
    await _complete_human_admin_notifications(job_id, {"returned_to_queue"}, target_id=segment_id or job_id)
    if not segment_id:
        asyncio.create_task(_complete_available_notifications(job_id))
    # A worker who claims work for themselves is already looking at it, so no
    # notification is sent. Notifications are kept for things that happen TO
    # a worker: direct assignments, proofreading jobs, deadline changes.
    return assignment


def _human_build_available_segments(job, now):
    """Split approved long recordings into open, approximately five-minute slices."""
    try:
        total_seconds = float(job.get("seconds") or 0)
        total_minutes = max(1, int(job.get("minutes") or math.ceil(total_seconds / 60.0)))
    except (TypeError, ValueError):
        raise ValueError("The audio length could not be read. Please review the job before approving it.")
    if total_seconds <= 0:
        raise ValueError("The audio length is missing. Please review the job before approving it.")
    count = int(math.ceil(total_minutes / float(HUMAN_AVAILABLE_SLICE_MINUTES)))
    if count <= 1:
        return []
    minutes_per_part, extra_minutes = divmod(total_minutes, count)
    segments = []
    for index in range(count):
        start_seconds = total_seconds * index / count
        end_seconds = total_seconds * (index + 1) / count
        segments.append({
            "id": f"part_{index + 1}",
            "label": f"Part {index + 1} of {count}",
            "index": index + 1,
            "start_seconds": round(start_seconds, 2),
            "end_seconds": round(end_seconds, 2),
            "minutes": minutes_per_part + (1 if index < extra_minutes else 0),
            "worker_uid": None,
            "worker_email": "",
            "worker_name": "",
            "status": "available",
            "assignedAt": None,
            "deadlineAt": None,
            "tat_seconds": None,
            "tat_extension_minutes": 0,
            "transcript": "",
            "worker_notes": "",
            "final_attachment": None,
            "workerCompletedAt": None,
            "worker_minutes": None,
            "worker_amount_kes": None,
            "payout_status": None,
            "payout_period_id": None,
            "auto_reassigned_count": 0,
            "last_auto_reassigned_at": None,
            "last_auto_reassigned_worker_name": None,
        })
    return segments


@app.post("/human-transcription/jobs/{job_id}/assign")
async def human_admin_assign(job_id: str, request: Request):
    _require_human_job_admin(request)
    payload = await request.json()
    job = await _human_job(job_id)
    if payload.get("supervised_starter") is not True:
        raise HTTPException(status_code=409, detail="Workers who meet the rating standard claim open work themselves. Admin assignment is reserved for a supervised starter assessment.")
    assignment_mode = str(payload.get("assignment_mode") or "single").strip().lower()
    requested_workers = payload.get("workers") if isinstance(payload.get("workers"), list) else []
    if not requested_workers and payload.get("worker_uid"):
        requested_workers = [{
            "worker_uid": payload.get("worker_uid"),
            "worker_email": payload.get("worker_email"),
            "worker_name": payload.get("worker_name"),
        }]
    requested_workers = [
        item for item in requested_workers
        if isinstance(item, dict) and str(item.get("worker_uid") or "").strip()
    ]
    split_requested = assignment_mode in {"dual", "multi", "split"} or len(requested_workers) > 1
    if split_requested:
        raise HTTPException(status_code=409, detail="New jobs are split automatically when approved. Assign one supervised starter part at a time.")
    if len(requested_workers) != 1:
        raise HTTPException(status_code=400, detail="Choose one approved worker for the supervised starter assignment.")

    worker = requested_workers[0]
    worker_uid = str(worker.get("worker_uid") or "").strip()
    if not worker_uid:
        raise HTTPException(status_code=400, detail="Choose one approved worker for the supervised starter assignment.")
    worker_profile = await _load_profile(worker_uid)
    if not worker_profile or worker_profile.get("workerApproved") is not True:
        raise HTTPException(status_code=403, detail="Approved worker access is required.")
    await _human_require_worker_online_for_overtime(worker_uid, worker_profile)
    worker_rating = await _human_worker_rating_summary(worker_uid, worker_profile)
    if worker_rating["average"] is not None and worker_rating["average"] >= MIN_HUMAN_WORKER_RATING:
        raise HTTPException(status_code=409, detail="This worker already meets the rating standard and should claim open work from the Available Jobs board.")

    segment_id = str(payload.get("segment_id") or "").strip()
    if _human_is_split_job(job):
        if not segment_id:
            raise HTTPException(status_code=400, detail="Choose an available part for the supervised starter assignment.")
    elif segment_id or job.get("status") != "approved":
        raise HTTPException(status_code=409, detail="Choose an approved job or an available part for the supervised starter assignment.")

    verified_actor = {
        "uid": worker_uid,
        "email": str(worker_profile.get("email") or worker.get("worker_email") or "").strip().lower(),
        "profile": worker_profile,
    }
    try:
        assignment = await asyncio.to_thread(
            _human_claim_assignment_transaction, job_id, verified_actor, segment_id, True,
            require_availability=False,
        )
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("Could not create a supervised Human Work starter assignment for %s", worker_uid)
        raise HTTPException(status_code=409, detail="The supervised starter assignment could not be saved. Refresh and try again.") from exc
    await _complete_human_admin_notifications(job_id, {"job_request", "job_approved"})
    await _complete_human_admin_notifications(job_id, {"returned_to_queue"}, target_id=segment_id or job_id)
    await _notify_worker_assignment(
        job_id, worker_uid, assignment.get("label") or "your supervised starter assignment",
        assignment.get("assignedAt"), segment_id=segment_id,
    )
    return {"status": "supervised_starter_assigned", "job_id": job_id, "segment_id": segment_id}

@app.post("/human-transcription/jobs/{job_id}/assign-whole")
async def human_admin_assign_whole(job_id: str, request: Request):
    """Urgent work: one worker takes the entire job, whatever their rating."""
    _require_human_job_admin(request)
    payload = await request.json()
    worker_uid = str(payload.get("worker_uid") or "").strip()
    if not worker_uid:
        raise HTTPException(status_code=400, detail="Choose an approved worker for this urgent job.")
    job = await _human_job(job_id)
    worker_profile = await _load_profile(worker_uid)
    if not worker_profile or worker_profile.get("workerApproved") is not True:
        raise HTTPException(status_code=403, detail="Approved worker access is required.")
    await _human_require_worker_online_for_overtime(worker_uid, worker_profile)
    if job.get("pdf_review"):
        reviewer_rating = await _human_worker_rating_summary(worker_uid, worker_profile)
        if reviewer_rating["average"] is None or reviewer_rating["average"] < MIN_PROOFREADER_RATING:
            raise HTTPException(status_code=409, detail="A whole-file human proofreader must be rated at least 4.5/5.")
    verified_actor = {
        "uid": worker_uid,
        "email": str(worker_profile.get("email") or payload.get("worker_email") or "").strip().lower(),
        "profile": worker_profile,
    }
    try:
        assignment = await asyncio.to_thread(_human_assign_whole_job_transaction, job_id, verified_actor)
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("Could not assign whole Human Work job %s to %s", job_id, worker_uid)
        raise HTTPException(status_code=409, detail="The whole-job assignment could not be saved. Refresh and try again.") from exc
    await _complete_human_admin_notifications(job_id, {"job_request", "job_approved"})
    await _notify_worker_assignment(job_id, worker_uid, assignment.get("label") or "your whole transcription job", assignment.get("assignedAt"), segment_id="")
    return {"status": "whole_job_assigned", "job_id": job_id, "worker_uid": worker_uid}


@app.post("/human-transcription/jobs/{job_id}/rate-part")
async def human_admin_rate_part(job_id: str, request: Request):
    """Rate one worker's submitted part (or the proofreader) on its own.

    Available as soon as that part is submitted, and still available after the
    job has been proofread or released.
    """
    _require_human_job_admin(request)
    payload = await request.json()
    job = await _human_job(job_id)
    target_id = str(payload.get("segment_id") or "").strip()
    try:
        rating = int(payload.get("rating"))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="Choose a rating from 1 to 5.")
    if rating < 1 or rating > 5:
        raise HTTPException(status_code=400, detail="Choose a rating from 1 to 5.")
    note = str(payload.get("note") or "").strip()[:2000]
    if target_id == "proofreader":
        if job.get("proofreader_status") != "submitted" or not job.get("proofreader_uid"):
            raise HTTPException(status_code=409, detail="The proofreader has not submitted yet.")
        worker_uid = str(job.get("proofreader_uid"))
    elif _human_is_split_job(job):
        part = next((item for item in (job.get("segments") or []) if str((item or {}).get("id") or "") == target_id), None)
        if not part or part.get("status") != "submitted" or not part.get("worker_uid"):
            raise HTTPException(status_code=409, detail="That part has not been submitted yet.")
        worker_uid = str(part.get("worker_uid"))
    else:
        if job.get("status") not in {"submitted", "client_review", "client_approved", "released"} or not job.get("worker_uid"):
            raise HTTPException(status_code=409, detail="This job has not been submitted yet.")
        worker_uid = str(job.get("worker_uid"))
        target_id = "main"
    part_ratings = dict(job.get("part_ratings") or {})
    part_ratings[target_id] = {"rating": rating, "note": note, "worker_uid": worker_uid, "source": str(payload.get("source") or "admin")[:20]}
    # A worker's score on this job is the average of the parts they did.
    own = [float(item["rating"]) for item in part_ratings.values() if str(item.get("worker_uid")) == worker_uid]
    ratings_by_worker = dict(job.get("worker_ratings") or {})
    ratings_by_worker[worker_uid] = round(sum(own) / len(own), 2)
    rating_update = {
        "part_ratings": part_ratings,
        "worker_ratings": ratings_by_worker,
        "updatedAt": firestore.SERVER_TIMESTAMP,
    }
    if target_id in (job.get("proofreader_suggested_ratings") or {}):
        rating_update[f"proofreader_suggested_ratings.{target_id}"] = firestore.DELETE_FIELD
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, rating_update)
    await _human_worker_rating_summary(worker_uid, force_refresh=True)
    return {"status": "rated", "job_id": job_id, "segment_id": target_id, "rating": rating, "worker_average_on_job": ratings_by_worker[worker_uid]}


@app.post("/human-transcription/jobs/{job_id}/assign-proofreader")
async def human_admin_assign_proofreader(job_id: str, request: Request):
    admin = _require_human_job_admin(request)
    payload = await request.json()
    transcript_override = None
    transcript_html_override = None
    if "transcript" in payload:
        transcript_override = str(payload.get("transcript") or "").strip()
        if len(transcript_override) > 1000000:
            raise HTTPException(status_code=413, detail="The transcript is too long to save.")
        transcript_html_override = _sanitize_editor_html(payload.get("transcript_html") or "")
    worker_uid = str(payload.get("worker_uid") or "").strip()
    if not worker_uid:
        raise HTTPException(status_code=400, detail="Choose an approved proofreader first.")
    proofreader_profile = await _load_profile(worker_uid) or {}
    await _human_require_worker_online_for_overtime(worker_uid, proofreader_profile)
    proofreader_rating = await _human_worker_rating_summary(worker_uid, proofreader_profile)
    if proofreader_rating["average"] is None or proofreader_rating["average"] < MIN_PROOFREADER_RATING:
        raise HTTPException(status_code=409, detail="Only workers rated 4.5/5 or higher can proofread.")
    if await _human_worker_has_active_assignment(worker_uid):
        raise HTTPException(status_code=409, detail="This worker must finish their current assignment before taking proofreading work.")
    job = await _human_job(job_id)
    is_split = _human_is_split_job(job)
    job_type = str(job.get("job_type") or "").strip().lower()
    is_image_review = job_type == "pdf_job" and bool(job.get("pdf_review"))
    if is_split:
        if not any((item or {}).get("status") == "submitted" for item in (job.get("segments") or [])):
            raise HTTPException(status_code=409, detail="At least one transcription part must be submitted before assigning a proofreader.")
    else:
        reviewable_status = job.get("status") in {"submitted", "client_review", "client_approved"} or (is_image_review and job.get("status") == "approved")
        has_review_material = bool(str(job.get("transcript") or "").strip() or (job.get("final_attachment") or {}).get("storage_path") or is_image_review)
        if not reviewable_status or not has_review_material:
            raise HTTPException(status_code=409, detail="Submit the complete job before assigning a human proofreader.")
    submitted_segment_ids = {
        str((item or {}).get("id") or "")
        for item in (job.get("segments") or [])
        if (item or {}).get("status") == "submitted"
    }
    raw_overrides = payload.get("proofreader_parts_override")
    proofreader_parts_override = {}
    total_override_chars = 0
    if isinstance(raw_overrides, list):
        if len(raw_overrides) > 100:
            raise HTTPException(status_code=413, detail="Too many transcript parts were included.")
        for item in raw_overrides:
            if not isinstance(item, dict):
                continue
            segment_id = str(item.get("id") or "")
            if segment_id not in submitted_segment_ids:
                raise HTTPException(status_code=400, detail="An edited transcript part is no longer available.")
            part_text = str(item.get("transcript") or "")[:1000000]
            part_html = _sanitize_editor_html(item.get("transcript_html") or "")
            total_override_chars += len(part_text) + len(part_html)
            if total_override_chars > 1500000:
                raise HTTPException(status_code=413, detail="The edited transcript parts are too large to save.")
            proofreader_parts_override[segment_id] = {"transcript": part_text, "transcript_html": part_html}
    proofreader_use_combined_transcript = bool(payload.get("proofreader_use_combined_transcript")) and not proofreader_parts_override
    if job_type == "pdf_job":
        image_count = (job.get("pdf_review") or {}).get("page_count") or 1
        tat_seconds = human_image_tat_seconds(image_count)
    elif job_type == "letter_job":
        tat_seconds = human_tat_seconds(float(job.get("seconds") or 0))
    else:
        tat_seconds = human_proofreading_tat_seconds(float(job.get("seconds") or 0))
    worker = {
        "worker_uid": worker_uid,
        "worker_email": payload.get("worker_email"),
        "worker_name": payload.get("worker_name"),
    }
    try:
        assignment = await asyncio.to_thread(
            _human_assign_proofreader_transaction, job_id, worker, tat_seconds,
            transcript_override, transcript_html_override, proofreader_parts_override,
            proofreader_use_combined_transcript,
        )
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("Could not assign proofreader %s to Human Work %s", worker_uid, job_id)
        raise HTTPException(status_code=409, detail="The proofreader assignment could not be saved. Refresh the job and try again.") from exc
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {
        "proofreader_assigned_by_uid": str(admin.get("uid") or "").strip(),
        "proofreader_assigned_by_email": str(admin.get("email") or "").strip().lower(),
        "updatedAt": firestore.SERVER_TIMESTAMP,
    })
    now = assignment["assignedAt"]
    await _complete_human_admin_notifications(job_id, {"job_request", "job_approved"})
    await _complete_human_admin_notifications(job_id, {"returned_to_queue"}, target_id="proofreader")
    await _notify_worker_assignment(job_id, worker_uid, "your proofreading assignment", now, segment_id="proofreader")
    return {"status": "proofreading_assigned", "job_id": job_id, "worker_uid": worker_uid, "tat_seconds": tat_seconds}


@app.put("/human-transcription/jobs/{job_id}/transcript")
async def human_save_shared_transcript(job_id: str, request: Request):
    actor = await _human_actor(request)
    job = await _human_job(job_id)
    await _human_assert_access(job, actor)
    if actor["role"] == "worker" and job.get("client_uid") != actor["uid"]:
        raise HTTPException(status_code=403, detail="Workers submit edits through their assigned work editor.")
    payload = await request.json()
    transcript = str((payload or {}).get("transcript") or "").strip()
    if len(transcript) > 1000000:
        raise HTTPException(status_code=413, detail="The transcript is too long to save.")
    transcript_html = _sanitize_editor_html((payload or {}).get("transcript_html") or "")
    await asyncio.to_thread(
        db.collection(HUMAN_JOB_COLLECTION).document(job_id).update,
        {
            "transcript": transcript,
            "transcript_html": transcript_html,
            "transcriptEditedAt": firestore.SERVER_TIMESTAMP,
            "transcriptEditedByRole": actor["role"],
            "updatedAt": firestore.SERVER_TIMESTAMP,
        },
    )
    return {"status": "saved", "job_id": job_id}


@app.post("/human-transcription/jobs/{job_id}/take-back")
async def human_admin_take_back(job_id: str, request: Request):
    """Return an active worker assignment to its queue without undoing submitted work."""
    admin = _require_human_job_admin(request)
    payload = await request.json()
    role = str(payload.get("role") or "transcriber").strip().lower()
    if role not in {"transcriber", "proofreader"}:
        raise HTTPException(status_code=400, detail="Choose a transcription part or proofreading assignment.")
    job = await _human_job(job_id)
    now = datetime.now()
    active_statuses = {"assigned", "in_progress"}
    worker_uid = ""
    worker_name = ""
    label = "Transcription"
    updates = {"updatedAt": firestore.SERVER_TIMESTAMP}

    if role == "proofreader":
        if job.get("proofreader_status") not in active_statuses or not job.get("proofreader_uid"):
            raise HTTPException(status_code=409, detail="Only an active proofreading assignment can be taken back.")
        worker_uid = str(job.get("proofreader_uid") or "")
        worker_name = str(job.get("proofreader_name") or job.get("proofreader_email") or "")
        label = "Final proofreading"
        segments = [dict(item or {}) for item in (job.get("segments") or [])]
        updates.update({
            "proofreader_status": "available", "proofreader_uid": None, "proofreader_email": None,
            "proofreader_name": None, "proofreader_assignedAt": None, "proofreader_deadlineAt": None,
            "proofreader_tat_seconds": None, "proofreader_tat_extension_minutes": 0,
            "assigned_worker_uids": list(dict.fromkeys(item.get("worker_uid") for item in segments if item.get("worker_uid"))),
            "status": _human_split_parent_status({**job, "proofreader_status": "available"}, segments) if _human_is_split_job(job) else "approved",
        })
    elif _human_is_split_job(job):
        segment_id = str(payload.get("segment_id") or "").strip()
        if not segment_id:
            raise HTTPException(status_code=400, detail="Choose the active part to take back.")
        segments = [dict(item or {}) for item in (job.get("segments") or [])]
        target = next((item for item in segments if str(item.get("id") or "") == segment_id), None)
        if not target or target.get("status") not in active_statuses or not target.get("worker_uid"):
            raise HTTPException(status_code=409, detail="Only an active part can be taken back.")
        worker_uid = str(target.get("worker_uid") or "")
        worker_name = str(target.get("worker_name") or target.get("worker_email") or "")
        label = str(target.get("label") or "Transcription part")
        # Keep any draft text or attachments on the part. Only clear the live
        # assignment; previously submitted sibling parts are left untouched.
        target.update({
            "status": "available", "worker_uid": None, "worker_email": None, "worker_name": None,
            "assignedAt": None, "deadlineAt": None, "tat_seconds": None, "tat_extension_minutes": 0,
        })
        proofreader_uid = job.get("proofreader_uid") if job.get("proofreader_status") in active_statuses | {"submitted"} else None
        assigned_uids = [item.get("worker_uid") for item in segments if item.get("worker_uid")]
        if proofreader_uid:
            assigned_uids.append(proofreader_uid)
        if job.get("proofreader_status") in active_statuses:
            next_status = "proofreading_in_progress" if job.get("proofreader_status") == "in_progress" else "proofreading_assigned"
        elif all(item.get("status") == "submitted" for item in segments):
            next_status = "proofreading_available"
        elif any(item.get("status") == "in_progress" for item in segments):
            next_status = "split_in_progress"
        else:
            next_status = "split_assigned"
        updates.update({"segments": segments, "assigned_worker_uids": list(dict.fromkeys(assigned_uids)), "status": next_status})
    else:
        if job.get("status") not in active_statuses or not job.get("worker_uid"):
            raise HTTPException(status_code=409, detail="Only an active transcription assignment can be taken back.")
        worker_uid = str(job.get("worker_uid") or "")
        worker_name = str(job.get("worker_name") or job.get("worker_email") or "")
        updates.update({
            "status": "approved", "worker_uid": None, "worker_email": None, "worker_name": None,
            "assignedAt": None, "deadlineAt": None, "tat_seconds": None,
            "tat_extension_minutes": 0, "assigned_worker_uids": [],
        })

    updates.update({
        "last_assignment_takeback_at": now,
        "last_assignment_takeback_worker_uid": worker_uid,
        "last_assignment_takeback_worker_name": worker_name,
        "last_assignment_takeback_role": role,
        "last_assignment_takeback_label": label,
        "last_assignment_takeback_by_uid": str(admin.get("uid") or ""),
        "last_assignment_takeback_by_email": str(admin.get("email") or "").strip().lower(),
    })
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, updates)
    if worker_uid:
        claim_role = "proofreader" if role == "proofreader" else "transcriber"
        claim_segment = "proofreader" if role == "proofreader" else str(payload.get("segment_id") or "")
        await _human_release_worker_claim(worker_uid, job_id, claim_segment, claim_role)
        await _update_user_notification_states(worker_uid, job_id=job_id, kinds={"assignment"}, read=True, completed=True)
        await _create_user_notification(
            str(worker_uid), f"human-takeback:{job_id}:{role}:{now.isoformat()}", "assignment_taken_back",
            "A Human Work assignment changed", f"An admin returned {label.lower()} to the work queue.",
            route="human_worker", job_id=job_id, target_id=job_id,
        )
    return {"status": updates.get("status"), "job_id": job_id, "role": role, "label": label, "worker_uid": worker_uid}


@app.post("/human-transcription/jobs/{job_id}/extend-tat")
async def human_admin_extend_tat(job_id: str, request: Request):
    _require_human_job_admin(request)
    payload = await request.json()
    try:
        extra_minutes = int(payload.get("minutes"))
    except (TypeError, ValueError):
        extra_minutes = 0
    if extra_minutes not in HUMAN_TAT_EXTENSION_OPTIONS:
        raise HTTPException(status_code=400, detail="Choose a 5, 10, 15, or 20 minute extension.")
    job = await _human_job(job_id)
    now = datetime.now()
    segment_id = str(payload.get("segment_id") or "").strip()
    if job.get("proofreader_uid") and str(payload.get("target") or "") == "proofreader":
        deadline = _as_dt(job.get("proofreader_deadlineAt"))
        if job.get("proofreader_status") not in {"assigned", "in_progress"} or not deadline or deadline <= now:
            raise HTTPException(status_code=409, detail="The proofreader deadline is no longer active.")
        await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {
            "proofreader_deadlineAt": deadline + timedelta(minutes=extra_minutes),
            "proofreader_tat_seconds": int(job.get("proofreader_tat_seconds") or 0) + extra_minutes * 60,
            "proofreader_tat_extension_minutes": int(job.get("proofreader_tat_extension_minutes") or 0) + extra_minutes,
            "updatedAt": firestore.SERVER_TIMESTAMP,
        })
        await _create_user_notification(
            str(job.get("proofreader_uid") or ""), f"deadline-extended:{job_id}:proofreader:{now.isoformat()}",
            "deadline_extended", "Proofreading time extended", f"Your deadline was extended by {extra_minutes} minutes.",
            route="human_worker", job_id=job_id, target_id=job_id,
        )
        return {"status": "extended", "job_id": job_id, "target": "proofreader", "minutes_added": extra_minutes}
    if _human_is_split_job(job):
        segments = [dict(item or {}) for item in (job.get("segments") or [])]
        target = next((item for item in segments if item.get("id") == segment_id), None) if segment_id else None
        if not target:
            raise HTTPException(status_code=400, detail="Choose the part whose deadline should be extended.")
        if target.get("status") not in {"assigned", "in_progress"} or not _as_dt(target.get("deadlineAt")) or _as_dt(target.get("deadlineAt")) <= now:
            raise HTTPException(status_code=409, detail="That part is no longer active, so its deadline cannot be extended.")
        target["deadlineAt"] = _as_dt(target.get("deadlineAt")) + timedelta(minutes=extra_minutes)
        target["tat_seconds"] = int(target.get("tat_seconds") or 0) + extra_minutes * 60
        target["tat_extension_minutes"] = int(target.get("tat_extension_minutes") or 0) + extra_minutes
        await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {"segments": segments, "updatedAt": firestore.SERVER_TIMESTAMP})
        await _create_user_notification(
            str(target.get("worker_uid") or ""), f"deadline-extended:{job_id}:{segment_id}:{now.isoformat()}",
            "deadline_extended", "Your job deadline was extended", f"Your deadline was extended by {extra_minutes} minutes.",
            route="human_worker", job_id=job_id, target_id=job_id,
        )
        return {"status": "extended", "job_id": job_id, "segment_id": segment_id, "minutes_added": extra_minutes}
    deadline = _as_dt(job.get("deadlineAt"))
    if job.get("status") not in {"assigned", "in_progress"} or not deadline or deadline <= now:
        raise HTTPException(status_code=409, detail="This job's deadline is no longer active.")
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {
        "deadlineAt": deadline + timedelta(minutes=extra_minutes),
        "tat_seconds": int(job.get("tat_seconds") or 0) + extra_minutes * 60,
        "tat_extension_minutes": int(job.get("tat_extension_minutes") or 0) + extra_minutes,
        "updatedAt": firestore.SERVER_TIMESTAMP,
    })
    await _create_user_notification(
        str(job.get("worker_uid") or ""), f"deadline-extended:{job_id}:transcriber:{now.isoformat()}",
        "deadline_extended", "Your job deadline was extended", f"Your deadline was extended by {extra_minutes} minutes.",
        route="human_worker", job_id=job_id, target_id=job_id,
    )
    return {"status": "extended", "job_id": job_id, "minutes_added": extra_minutes}


@app.post("/human-transcription/jobs/{job_id}/start")
async def human_worker_start(job_id: str, request: Request):
    actor = await _human_actor(request)
    if actor["role"] != "worker":
        raise HTTPException(status_code=403, detail="Worker access is required.")
    job = await _human_job(job_id)
    await _human_assert_access(job, actor, allow_admin=False)
    if _human_is_split_job(job):
        segments = [dict(item or {}) for item in (job.get("segments") or [])]
        target = next((item for item in segments if item.get("worker_uid") == actor["uid"] and item.get("status") in {"assigned", "in_progress"}), None)
        if target:
            if target.get("status") == "assigned":
                await _human_shift_assert_can_start_assigned(
                    actor, allow_after_hours_self_claim=target.get("after_hours_self_claim") is True,
                )
            target["status"] = "in_progress"
            await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {"segments": segments, "status": _human_split_parent_status(job, segments), "updatedAt": firestore.SERVER_TIMESTAMP})
            await _update_user_notification_states(actor["uid"], job_id=job_id, kinds={"assignment"}, read=True, completed=True)
            return {"status": "in_progress", "job_id": job_id, "segment_id": target.get("id")}
        if job.get("proofreader_uid") == actor["uid"] and job.get("proofreader_status") in {"assigned", "in_progress"}:
            if job.get("proofreader_status") == "assigned":
                await _human_shift_assert_can_start_assigned(actor)
            await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {"proofreader_status": "in_progress", "status": "proofreading_in_progress", "updatedAt": firestore.SERVER_TIMESTAMP})
            await _update_user_notification_states(actor["uid"], job_id=job_id, kinds={"assignment"}, read=True, completed=True)
            return {"status": "in_progress", "job_id": job_id, "role": "proofreader"}
        raise HTTPException(status_code=409, detail="This assignment is not ready to start.")
    if job.get("worker_uid") != actor["uid"]:
        raise HTTPException(status_code=403, detail="You do not have access to this job.")
    if job.get("status") not in {"assigned", "in_progress"}:
        raise HTTPException(status_code=409, detail="This job is not ready to start.")
    if job.get("status") == "assigned":
        await _human_shift_assert_can_start_assigned(
            actor, allow_after_hours_self_claim=job.get("after_hours_self_claim") is True,
        )
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {"status": "in_progress", "updatedAt": firestore.SERVER_TIMESTAMP})
    await _update_user_notification_states(actor["uid"], job_id=job_id, kinds={"assignment"}, read=True, completed=True)
    return {"status": "in_progress", "job_id": job_id}


@app.post("/human-transcription/jobs/{job_id}/submit")
async def human_worker_submit(
    job_id: str,
    request: Request,
    background_tasks: BackgroundTasks,
    transcript: str = Form(""),
    notes: str = Form(""),
    attachment: UploadFile = File(None),
    transcript_html: str = Form(""),
):
    actor = await _human_actor(request)
    if actor["role"] != "worker":
        raise HTTPException(status_code=403, detail="Worker access is required.")
    job = await _human_job(job_id)
    await _human_assert_access(job, actor, allow_admin=False)
    is_letter_job = str(job.get("job_type") or "").strip().lower() == "letter_job"
    if is_letter_job:
        if job.get("split_mode") != "single" or job.get("segments"):
            raise HTTPException(status_code=409, detail="Letter Jobs must remain one complete, unsplit assignment.")
        if not attachment or not attachment.filename:
            raise HTTPException(status_code=400, detail="Attach the finished Word document (.docx) before submitting a Letter Job.")
        if not str(attachment.filename).lower().endswith(".docx"):
            raise HTTPException(status_code=400, detail="Letter Jobs require a finished Word .docx document.")
        raw_docx = await attachment.read(LETTER_JOB_MAX_UPLOAD_BYTES + 1)
        if len(raw_docx) > LETTER_JOB_MAX_UPLOAD_BYTES:
            raise HTTPException(status_code=413, detail="The finished Word document is larger than 25 MB.")
        try:
            await asyncio.to_thread(_human_letter_docx_text, raw_docx)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        await attachment.seek(0)
    transcript_text = str(transcript or "").strip()
    clean_html = _sanitize_editor_html(transcript_html)

    if _human_is_split_job(job):
        segments = [dict(item or {}) for item in (job.get("segments") or [])]
        target = next((item for item in segments if item.get("worker_uid") == actor["uid"] and item.get("status") in {"assigned", "in_progress"}), None)
        if target:
            if target.get("status") == "assigned":
                await _human_shift_assert_can_start_assigned(
                    actor, allow_after_hours_self_claim=target.get("after_hours_self_claim") is True,
                )
            final_attachment = target.get("final_attachment")
            if attachment and attachment.filename:
                final_attachment = await _human_store_upload(job_id, attachment, f"final-{target.get('id')}")
            if not transcript_text and not final_attachment:
                raise HTTPException(status_code=400, detail="Add your part of the transcript, or attach the finished file, before submitting.")
            quote = job.get("quote") or {}
            minutes = int(target.get("minutes") or 0)
            rate = int(quote.get("transcriber_payout_kes_per_minute") or HUMAN_LEGACY_STANDARD_PAYOUT_KES)
            target.update({
                "status": "submitted",
                "transcript": transcript_text[:1000000],
                "transcript_html": clean_html,
                "final_attachment": final_attachment,
                "worker_notes": str(notes or "")[:12000],
                "submittedAt": datetime.now(),
                "workerCompletedAt": datetime.now(),
                "worker_minutes": minutes,
                "worker_amount_kes": max(0, minutes * rate),
                "payout_status": "unassigned",
            })
            parent_status = _human_split_parent_status(job, segments)
            both_submitted = parent_status == "proofreading_available"
            await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {
                "segments": segments,
                "status": parent_status,
                "updatedAt": firestore.SERVER_TIMESTAMP,
            })
            earning_job = {**job, "segments": segments, "status": parent_status}
            try:
                await _human_subadmin_accrue_job_earnings(
                    job_id, earning_job, _human_subadmin_submission_actor(earning_job, target),
                    segment_ids=[str(target.get("id") or "")],
                )
            except Exception:
                logger.exception("Could not accrue sub-admin earnings for submitted Human Work part %s/%s", job_id, target.get("id"))
            await _human_release_worker_claim(actor["uid"], job_id, str(target.get("id") or ""), "transcriber")
            await _update_user_notification_states(actor["uid"], job_id=job_id, kinds={"assignment"}, read=True, completed=True)
            await _notify_human_admins(
                f"human-submitted:{job_id}:{target.get('id')}", "job_submitted", "A job part was submitted",
                "Open the job to read this part and rate the worker now. You do not need to wait for the other parts.", route="human_ops", job_id=job_id, requires_action=True,
            )
            return {"status": parent_status, "job_id": job_id, "segment_id": target.get("id")}

        if job.get("proofreader_uid") == actor["uid"] and job.get("proofreader_status") in {"assigned", "in_progress"}:
            if job.get("proofreader_status") == "assigned":
                await _human_shift_assert_can_start_assigned(actor)
            final_attachment = job.get("final_attachment")
            if attachment and attachment.filename:
                final_attachment = await _human_store_upload(job_id, attachment, "final")
            if not all(item.get("status") == "submitted" for item in segments):
                raise HTTPException(status_code=409, detail="Some parts have not been submitted yet. Load them into your editor, proofread them, then submit the final transcript once every part is in.")
            combined = transcript_text or "\n\n".join(item.get("transcript", "") for item in segments if item.get("transcript"))
            if not combined and not final_attachment:
                raise HTTPException(status_code=400, detail="Review both parts and submit the combined transcript or a finished file.")
            minutes = int(job.get("minutes") or 0)
            proofreader_updates = {
                "status": "submitted",
                "transcript": combined[:1000000],
                "transcript_html": clean_html,
                "final_attachment": final_attachment,
                "worker_notes": str(notes or "")[:12000],
                "proofreader_status": "submitted", "reviewer_status": "completed", "reviewer_choice": "human",
                "proofreader_completedAt": datetime.now(),
                "proofreader_minutes": minutes,
                "proofreader_amount_kes": max(0, minutes * HUMAN_PROOFREADING_PAYOUT_KES),
                "proofreader_payout_status": "unassigned",
                "submittedAt": firestore.SERVER_TIMESTAMP,
                "updatedAt": firestore.SERVER_TIMESTAMP,
            }
            await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, proofreader_updates)
            earning_job = {**job, **proofreader_updates, "segments": segments}
            try:
                await _human_subadmin_accrue_job_earnings(job_id, earning_job, _human_subadmin_submission_actor(earning_job))
            except Exception:
                logger.exception("Could not accrue sub-admin earnings after proofreading submission for Human Work job %s", job_id)
            await _human_release_worker_claim(actor["uid"], job_id, "proofreader", "proofreader")
            await _update_user_notification_states(actor["uid"], job_id=job_id, kinds={"assignment"}, read=True, completed=True)
            await _notify_human_admins(
                f"human-submitted:{job_id}:proofreader", "job_submitted", "Proofreading was submitted",
                "Check the completed proofreading submission.", route="human_ops", job_id=job_id, requires_action=True,
            )
            return {"status": "submitted", "job_id": job_id, "role": "proofreader"}
        raise HTTPException(status_code=409, detail="This assignment is no longer active.")

    if job.get("proofreader_uid") == actor["uid"] and job.get("proofreader_status") in {"assigned", "in_progress"}:
        if job.get("proofreader_status") == "assigned":
            await _human_shift_assert_can_start_assigned(actor)
        if not transcript_text and not (attachment and attachment.filename):
            raise HTTPException(status_code=400, detail="Submit the proofread transcript or attach the checked Word document.")
        final_attachment = job.get("final_attachment")
        if attachment and attachment.filename:
            final_attachment = await _human_store_upload(job_id, attachment, "final-proofread")
        reviewed_transcript = transcript_text or str(job.get("transcript") or "")
        reviewed_html = clean_html if transcript_text or clean_html else str(job.get("transcript_html") or "")
        job_type = str(job.get("job_type") or "").strip().lower()
        minutes = max(1, int(job.get("minutes") or (job.get("quote") or {}).get("minutes") or 1))
        if job_type == "pdf_job":
            image_count = (job.get("pdf_review") or {}).get("page_count") or 1
            proofreader_amount = PDF_JOB_REVIEW_PAY_KES_PER_PAGE * max(1, int(image_count))
        else:
            proofreader_amount = max(0, minutes * HUMAN_PROOFREADING_PAYOUT_KES)
        proofreader_updates = {
            "status": "submitted", "transcript": reviewed_transcript[:1000000],
            "transcript_html": reviewed_html[:1500000], "final_attachment": final_attachment,
            "worker_notes": str(notes or "")[:12000], "proofreader_status": "submitted",
            "reviewer_choice": "human", "reviewer_status": "completed",
            "proofreader_completedAt": firestore.SERVER_TIMESTAMP, "proofreader_minutes": minutes,
            "proofreader_amount_kes": proofreader_amount, "proofreader_payout_status": "unassigned",
            "submittedAt": firestore.SERVER_TIMESTAMP, "updatedAt": firestore.SERVER_TIMESTAMP,
        }
        await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, proofreader_updates)
        earning_job = {**job, **proofreader_updates}
        try:
            await _human_subadmin_accrue_job_earnings(job_id, earning_job, _human_subadmin_submission_actor(earning_job))
        except Exception:
            logger.exception("Could not accrue sub-admin earnings after proofreading submission for Human Work job %s", job_id)
        await _human_release_worker_claim(actor["uid"], job_id, "proofreader", "proofreader")
        await _update_user_notification_states(actor["uid"], job_id=job_id, kinds={"assignment"}, read=True, completed=True)
        await _notify_human_admins(
            f"human-proofreader-submitted:{job_id}", "job_submitted", "Human proofreading was submitted",
            "The assigned human proofreader completed this job. Check the proofread transcript or Word document before final approval.",
            route="human_ops", job_id=job_id, requires_action=True,
        )
        return {"status": "submitted", "job_id": job_id, "role": "proofreader"}

    if job.get("worker_uid") != actor["uid"]:
        raise HTTPException(status_code=403, detail="You do not have access to this job.")
    if job.get("status") == "assigned":
        await _human_shift_assert_can_start_assigned(
            actor, allow_after_hours_self_claim=job.get("after_hours_self_claim") is True,
        )
    transcript_text = str(transcript or "").strip()
    final_attachment = job.get("final_attachment")
    if attachment and attachment.filename:
        final_attachment = await _human_store_upload(job_id, attachment, "final")
    if not transcript_text and not final_attachment:
        raise HTTPException(status_code=400, detail="Add the completed transcript, or attach the finished file, before submitting.")
    quote = job.get("quote") or {}
    is_pdf_job = str(job.get("job_type") or "").strip().lower() == "pdf_job"
    minutes = int(job.get("minutes") or quote.get("minutes") or 0)
    rate = _human_pdf_job_pay_kes(job) if is_pdf_job else int(quote.get("transcriber_payout_kes_per_minute") or HUMAN_LEGACY_STANDARD_PAYOUT_KES)
    worker_amount_kes = _human_pdf_job_pay_kes(job) if is_pdf_job else max(0, minutes * rate)
    if is_pdf_job and job.get("pdf_review"):
        worker_amount_kes = PDF_JOB_REVIEW_PAY_KES_PER_PAGE * max(1, int((job.get("pdf_review") or {}).get("page_count") or 1))
    updates = {
        "status": "submitted",
        "transcript": transcript_text[:1000000],
        "transcript_html": clean_html,
        "final_attachment": final_attachment,
        "worker_notes": str(notes or "")[:12000],
        "submittedAt": firestore.SERVER_TIMESTAMP,
        "updatedAt": firestore.SERVER_TIMESTAMP,
        "workerCompletedAt": datetime.now(),
        "worker_minutes": minutes,
        "worker_amount_kes": worker_amount_kes,
        "worker_gross_amount_kes": worker_amount_kes,
        "payout_status": "unassigned",
    }
    if is_pdf_job and job.get("pdf_review"):
        updates.update({"reviewer_choice": "human", "reviewer_status": "completed"})
    if is_letter_job:
        updates.update({
            "letter_ai_review_status": "not_started", "letter_ai_review_error": "",
            "letter_ai_review_attachment": None, "reviewer_choice": "", "reviewer_status": "not_started",
        })
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, updates)
    earning_job = {**job, **updates}
    try:
        await _human_subadmin_accrue_job_earnings(job_id, earning_job, _human_subadmin_submission_actor(earning_job))
    except Exception:
        logger.exception("Could not accrue sub-admin earnings for submitted Human Work job %s", job_id)
    await _human_release_worker_claim(actor["uid"], job_id, "", "transcriber")
    await _update_user_notification_states(actor["uid"], job_id=job_id, kinds={"assignment"}, read=True, completed=True)
    await _notify_human_admins(
        f"human-submitted:{job_id}:main", "job_submitted", "A Human Work job was submitted",
        "Review the submitted job.", route="human_ops", job_id=job_id, requires_action=True,
    )
    return {"status": "submitted", "job_id": job_id}


@app.post("/human-transcription/jobs/{job_id}/review")
async def human_admin_review(job_id: str, request: Request):
    actor = _require_human_job_admin(request)
    job = await _human_job(job_id)
    if job.get("status") not in {"submitted", "client_review"}:
        raise HTTPException(status_code=409, detail="This job is not ready for admin review.")
    payload = await request.json()
    rating = payload.get("rating")
    try:
        rating = max(1, min(5, int(rating))) if rating is not None else None
    except (TypeError, ValueError):
        rating = None
    worker_uids = _human_job_worker_uids(job)
    ratings_by_worker = dict(job.get("worker_ratings") or {})
    if rating is not None:
        rated_parts = {str(item.get("worker_uid")) for item in (job.get("part_ratings") or {}).values() if item.get("worker_uid")}
        for worker_uid in worker_uids:
            # Workers already rated part by part keep those ratings.
            if worker_uid in rated_parts:
                continue
            ratings_by_worker[worker_uid] = rating
    job_type = str(job.get("job_type") or "").strip().lower()
    is_pdf_job = job_type == "pdf_job"
    is_letter_job = job_type == "letter_job"
    reviewer_choice = str(job.get("reviewer_choice") or "").strip().lower()
    if not is_pdf_job and not is_letter_job:
        if reviewer_choice == "human":
            if job.get("proofreader_status") != "submitted":
                raise HTTPException(status_code=409, detail="The assigned human proofreader must submit before final admin approval.")
        elif reviewer_choice == "ai":
            if not str((job.get("ai_review") or {}).get("combined_text") or "").strip():
                raise HTTPException(status_code=409, detail="Run AI proofreading before final admin approval.")
            if job.get("ai_review_applied") is not True:
                raise HTTPException(status_code=409, detail="Apply the AI-proofread transcript before final admin approval.")
        else:
            raise HTTPException(status_code=409, detail="Choose an AI proofreader or assign a human proofreader before final admin approval.")
    if is_letter_job:
        if reviewer_choice == "human":
            if job.get("proofreader_status") != "submitted":
                raise HTTPException(status_code=409, detail="The assigned human proofreader must submit before the Letter Job can be released.")
        elif job.get("letter_ai_review_status") != "completed":
            raise HTTPException(status_code=409, detail="Run AI proofreading for this Letter Job or assign a human proofreader before final admin approval.")
    if is_pdf_job and job.get("pdf_review"):
        if reviewer_choice == "human":
            human_review_submitted = job.get("proofreader_status") == "submitted" or (job.get("worker_uid") and job.get("reviewer_status") == "completed")
            if not human_review_submitted:
                raise HTTPException(status_code=409, detail="The assigned human proofreader must submit before the image-file proofread can be completed.")
        elif reviewer_choice != "ai" or job.get("ai_agent_status") != "submitted":
            raise HTTPException(status_code=409, detail="Choose the AI proofreader or assign a human proofreader before approving this whole-file proofread.")
    internal_release = is_pdf_job or is_letter_job or job.get("admin_uploaded") is True
    review_status = "released" if internal_release else "client_review"
    updates = {
        "status": review_status,
        "worker_ratings": ratings_by_worker,
        "reviewedAt": firestore.SERVER_TIMESTAMP,
        "updatedAt": firestore.SERVER_TIMESTAMP,
    }
    if "feedback" in payload:
        updates["admin_feedback"] = str(payload.get("feedback") or "")[:12000]
    if rating is not None:
        updates["worker_rating"] = rating
    if internal_release:
        updates["releasedAt"] = firestore.SERVER_TIMESTAMP
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, updates)
    try:
        await _human_subadmin_accrue_job_earnings(job_id, job, actor)
    except Exception:
        logger.exception("Could not accrue sub-admin earnings for approved Human Work job %s", job_id)
    for worker_uid in worker_uids:
        await _human_worker_rating_summary(worker_uid, force_refresh=True)
    await _complete_human_admin_notifications(job_id, {"job_submitted"})
    if job.get("client_uid") and not internal_release:
        await _create_user_notification(
            str(job["client_uid"]), f"human-review-ready:{job_id}", "human_review_ready",
            "Your transcript is ready to review", "Open your Human Work job to review the completed transcript.",
            route="human_job", job_id=job_id, target_id=job_id, requires_action=True,
        )
    return {"status": review_status, "job_id": job_id}


@app.post("/human-transcription/jobs/{job_id}/ai-agent/finish")
async def human_admin_finish_ai_agent_draft(job_id: str, request: Request):
    """Finish a complete admin-uploaded AI draft without billing or contacting a client."""
    actor = _require_human_job_admin(request)
    job = await _human_job(job_id)
    if not _human_ai_draft_finish_eligible(job):
        raise HTTPException(
            status_code=409,
            detail="This internal AI draft is not ready to finish. Complete every part and resolve any human proofreading assignment first.",
        )
    await asyncio.to_thread(db.collection(HUMAN_JOB_COLLECTION).document(job_id).update, {
        "status": "released",
        "ai_agent_finished": True,
        "ai_agent_finishedAt": firestore.SERVER_TIMESTAMP,
        "ai_agent_finishedBy": str(actor.get("email") or "").strip().lower(),
        "releasedAt": firestore.SERVER_TIMESTAMP,
        "updatedAt": firestore.SERVER_TIMESTAMP,
    })
