async def _trainee_actor(request: Request):
    decoded = _verified_user(request)
    uid = decoded.get("uid") or ""
    email = (decoded.get("email") or "").strip().lower()
    profile = await _load_profile(uid) or {}
    profile = await _heal_profile_identity(uid, email, profile)
    return {"uid": uid, "email": email, "profile": profile}



@app.post("/api/trainee/complete-signup")
async def complete_trainee_signup(request: Request):
    actor = await _trainee_actor(request)
    payload = await request.json()
    reference = str(payload.get("reference") or "").strip()
    official_name = str(payload.get("official_name") or "").strip()
    if not reference or len(official_name) < 2:
        raise HTTPException(status_code=400, detail="The paid enrollment and official name are required.")
    if not db:
        raise HTTPException(status_code=503, detail="The enrollment database is unavailable.")
    snap = await asyncio.to_thread(db.collection("payment_intents").document(reference).get)
    intent = snap.to_dict() if snap.exists else {}
    if intent.get("product") != TRAINEE_PRODUCT:
        raise HTTPException(status_code=409, detail="This payment is not a trainee enrollment.")

    # A browser can reach account creation before the provider webhook has
    # updated Firestore. Re-check the provider here instead of creating a
    # normal client account and leaving the paid trainee half-enrolled.
    if intent.get("status") != "paid":
        provider = str(intent.get("provider") or "paystack").strip().lower()
        if provider == "kora":
            await verify_kora_and_enroll(reference)
        elif provider == "paystack":
            verification = await verify_paystack_payment(reference)
            if verification.get("status") == "success":
                await asyncio.to_thread(db.collection("payment_intents").document(reference).set, {
                    "status": "paid",
                    "paidAt": firestore.SERVER_TIMESTAMP,
                    "email": verification.get("email") or intent.get("email"),
                    "product": TRAINEE_PRODUCT,
                    "provider": "paystack",
                    "countryCode": intent.get("countryCode") or TRAINEE_COUNTRY,
                    "currency": verification.get("currency") or intent.get("currency") or "KES",
                }, merge=True)
        snap = await asyncio.to_thread(db.collection("payment_intents").document(reference).get)
        intent = snap.to_dict() if snap.exists else {}

    if intent.get("status") != "paid":
        raise HTTPException(status_code=409, detail="Payment has not been confirmed for this enrollment yet. Please wait a moment and try again.")
    if str(intent.get("email") or "").strip().lower() != actor["email"]:
        raise HTTPException(status_code=403, detail="This payment belongs to a different email address.")
    saved_official_name = str((actor.get("profile") or {}).get("officialIdName") or "").strip()
    if saved_official_name and saved_official_name.casefold() != official_name.casefold():
        raise HTTPException(status_code=409, detail="The official name from your trainee registration is locked. Contact support if it needs correcting.")
    if payload.get("mpesa_confirmed") is not True:
        raise HTTPException(status_code=400, detail="Confirm that the submitted details are registered to your M-Pesa account.")
    mpesa_name, mpesa_number = _normalize_mpesa_details(payload.get("mpesa_registered_name"), payload.get("mpesa_number"))
    if not mpesa_name or not mpesa_number:
        raise HTTPException(status_code=400, detail="Enter both the M-Pesa registered name and number before opening the Training Room.")
    await asyncio.to_thread(db.collection("users").document(actor["uid"]).set, {
        "name": official_name, "officialIdName": official_name,
        "mpesaRegisteredName": mpesa_name, "mpesaNumber": mpesa_number,
        "mpesaDetailsUpdatedAt": firestore.SERVER_TIMESTAMP,
    }, merge=True)
    result = await enroll_paid_trainee(actor["email"], reference, TRAINEE_PRICE_USD, str(intent.get("currency") or "KES"), TRAINEE_COUNTRY, str(intent.get("provider") or "paystack"), user_id=actor["uid"])
    if not result.get("success"):
        raise HTTPException(status_code=409, detail=result.get("error") or "The trainee account could not be completed.")

    # Trainees bypass the normal profile-creation path, so send their own
    # welcome message after payment and enrolment have both succeeded. Email
    # delivery is deliberately non-blocking for account completion.
    trainee_subject, trainee_html, trainee_text = build_trainee_welcome_email(official_name)
    await _send_resend_message(actor["email"], trainee_subject, trainee_html, trainee_text, "Trainee welcome email")
    return {"success": True, "training_room": True}

async def _load_training_submissions(uid):
    if not db:
        return {}
    def read_all():
        return [db.collection("training_submissions").document(f"{uid}-{level}").get() for level in range(1, len(TRAINING_LEVELS) + 1)]
    snapshots = await asyncio.to_thread(read_all)
    results = {}
    for snapshot in snapshots:
        if snapshot.exists:
            item = snapshot.to_dict() or {}
            item.pop("uid", None)
            item.pop("email", None)
            results[str(item.get("level") or snapshot.id.rsplit("-", 1)[-1])] = _human_public(item)
    return results


_GUIDELINES_CACHE = {"at": 0.0, "html": "", "text": ""}


def _docx_to_html_and_text(raw: bytes):
    """Render the guidelines document to safe HTML plus plain text."""
    from html import escape
    from docx.table import Table
    from docx.text.paragraph import Paragraph

    document = Document(BytesIO(raw))

    def runs_html(paragraph):
        out = []
        for run in paragraph.runs:
            text = escape(run.text or "")
            if not text:
                continue
            if run.bold:
                text = f"<strong>{text}</strong>"
            if run.italic:
                text = f"<em>{text}</em>"
            if run.underline:
                text = f"<u>{text}</u>"
            out.append(text)
        return "".join(out)

    html_parts, text_parts = [], []
    in_list = False
    for child in document.element.body.iterchildren():
        tag = child.tag.rsplit("}", 1)[-1]
        if tag == "p":
            paragraph = Paragraph(child, document)
            plain = (paragraph.text or "").strip()
            style = (paragraph.style.name if paragraph.style is not None else "") or ""
            is_item = "list" in style.lower() or child.find(".//{http://schemas.openxmlformats.org/wordprocessingml/2006/main}numPr") is not None
            if not plain:
                if in_list:
                    html_parts.append("</ul>")
                    in_list = False
                continue
            body = runs_html(paragraph) or escape(plain)
            if is_item:
                if not in_list:
                    html_parts.append("<ul>")
                    in_list = True
                html_parts.append(f"<li>{body}</li>")
                text_parts.append(f"- {plain}")
                continue
            if in_list:
                html_parts.append("</ul>")
                in_list = False
            if style.lower().startswith("heading") or style.lower() == "title":
                level = 2 if style.lower() in {"title", "heading 1"} else 3
                html_parts.append(f"<h{level}>{escape(plain)}</h{level}>")
                text_parts.append(f"\n{plain.upper()}")
            else:
                html_parts.append(f"<p>{body}</p>")
                text_parts.append(plain)
        elif tag == "tbl":
            if in_list:
                html_parts.append("</ul>")
                in_list = False
            table = Table(child, document)
            html_parts.append("<table>")
            for row in table.rows:
                cells = []
                for cell in row.cells:
                    cells.append(f"<td>{escape(cell.text or '')}</td>")
                html_parts.append("<tr>" + "".join(cells) + "</tr>")
                text_parts.append(" | ".join((cell.text or "").strip() for cell in row.cells))
            html_parts.append("</table>")
    if in_list:
        html_parts.append("</ul>")
    return "".join(html_parts), "\n".join(text_parts)


async def _guidelines_content():
    """Guidelines HTML and text, read from the private bucket (cached briefly)."""
    if _GUIDELINES_CACHE["html"] and time.time() - _GUIDELINES_CACHE["at"] < 600:
        return _GUIDELINES_CACHE["html"], _GUIDELINES_CACHE["text"]
    bucket = _training_assets_bucket()
    if bucket is None:
        raise HTTPException(status_code=503, detail="The guidelines are temporarily unavailable.")
    try:
        raw = await asyncio.to_thread(bucket.blob(f"{TRAINING_ASSET_STORAGE_PREFIX}transcription-guidelines.docx").download_as_bytes)
        html_out, text_out = await asyncio.to_thread(_docx_to_html_and_text, raw)
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception("Could not read the guidelines document")
        raise HTTPException(status_code=503, detail="The guidelines are temporarily unavailable.") from exc
    _GUIDELINES_CACHE.update({"at": time.time(), "html": html_out, "text": text_out})
    return html_out, text_out


def _can_view_training_materials(actor):
    profile = actor.get("profile") or {}
    profile_role = str(profile.get("role") or profile.get("user_type") or "").lower()
    paid_trainee = profile_role == "trainee" and profile.get("trainingRoomAccess") is True and str(profile.get("trainingPaymentStatus") or "").lower() == "paid"
    return actor.get("role") in {"admin", "worker"} or paid_trainee


@app.get("/human-transcription/guidelines")
async def human_guidelines(request: Request):
    """The general guidelines as a readable page for workers, trainees and admins."""
    actor = await _human_actor(request)
    if not _can_view_training_materials(actor):
        raise HTTPException(status_code=403, detail="Worker, trainee or admin access is required to read the guidelines.")
    html_out, _ = await _guidelines_content()
    return {"title": "TypeMyworDz General Guidelines", "html": html_out}


@app.get("/api/admin/ai-guidelines")
async def admin_get_ai_guidelines(request: Request):
    _require_admin(request)
    ref = db.collection("admin_settings").document("ai_guidelines")
    snap = await asyncio.to_thread(ref.get)
    data = snap.to_dict() if snap.exists else None
    if not data or not str(data.get("text") or "").strip():
        try:
            _, seed = await _guidelines_content()
        except HTTPException:
            seed = ""
        data = {"text": seed}
        if seed:
            await asyncio.to_thread(ref.set, {"text": seed, "seededAt": firestore.SERVER_TIMESTAMP}, merge=True)
    return {"text": str(data.get("text") or ""), "updated_at": _human_iso(data.get("updatedAt"))}


@app.put("/api/admin/ai-guidelines")
async def admin_put_ai_guidelines(request: Request):
    _require_admin(request)
    payload = await request.json()
    text = str(payload.get("text") or "")[:120000]
    await asyncio.to_thread(db.collection("admin_settings").document("ai_guidelines").set, {"text": text, "updatedAt": firestore.SERVER_TIMESTAMP}, merge=True)
    return {"status": "saved", "length": len(text)}


async def _admin_guidelines_text():
    snap = await asyncio.to_thread(db.collection("admin_settings").document("ai_guidelines").get)
    data = snap.to_dict() if snap.exists else {}
    text = str((data or {}).get("text") or "").strip()
    if text:
        return text
    try:
        return (await _guidelines_content())[1]
    except HTTPException:
        return ""


async def _admin_fill_identity(uid: str, data: dict) -> dict:
    """Fills a missing email from Firebase sign-in so admins always see it."""
    data = dict(data or {})
    email = str(data.get("email") or "").strip()
    if not email:
        try:
            auth_user = await asyncio.to_thread(firebase_auth.get_user, uid)
            email = (auth_user.email or "").strip().lower()
            if not data.get("name") and not data.get("displayName") and auth_user.display_name:
                data["displayName"] = auth_user.display_name
        except Exception:
            email = ""
    return await _heal_profile_identity(uid, email, data)


@app.get("/api/admin/workers")
async def admin_workers(request: Request):
    """Promoted workers with their contact details and current rating."""
    _require_admin(request)
    if not db:
        return {"workers": []}
    snapshots = await asyncio.to_thread(lambda: list(db.collection("users").where(filter=FieldFilter("workerApproved", "==", True)).stream()))
    rows = []
    for snap in snapshots:
        data = snap.to_dict() or {}
        try:
            rating = await _human_worker_rating_summary(snap.id, data)
        except Exception:
            rating = {"average": None, "count": 0}
        data = await _admin_fill_identity(snap.id, data)
        rows.append({
            "uid": snap.id,
            "name": data.get("name") or data.get("full_name") or data.get("displayName") or "Unnamed worker",
            "email": data.get("email") or "",
            "country": data.get("country") or "Kenya",
            "official_name": data.get("officialIdName") or "",
            "mpesa_name": data.get("mpesaRegisteredName") or "",
            "phone": data.get("mpesaNumber") or data.get("phone") or "",
            "rating": rating.get("average"),
            "rating_count": rating.get("count") or 0,
            "is_available": data.get("is_available") is True,
            "approved_at": _human_iso(data.get("workerApprovedAt")),
            "can_proofread": (rating.get("average") or 0) >= MIN_PROOFREADER_RATING,
        })
    rows.sort(key=lambda item: (-(item["rating"] or 0), item["name"].lower()))
    return {"workers": rows, "min_claim_rating": MIN_HUMAN_WORKER_RATING, "min_proofread_rating": MIN_PROOFREADER_RATING}


